  egypt_unify: { n: 'La unificación de Egipto', p: 'Menfis, Egipto', d: 'Narmer unifica el Alto y el Bajo Egipto y funda uno de los Estados más longevos de la historia mundial.' },
  indus_civ: { n: 'La civilización del valle del Indo', p: 'Mohenjo-daro, valle del Indo', d: 'Ciudades trazadas en cuadrícula, con alcantarillas y pesos normalizados, florecen en el valle del Indo — tan urbanas como Egipto o Sumer y aún en gran parte indescifradas.' },
  trypillia: { n: 'Los grandes asentamientos de Trípila', p: 'Talianky, Ucrania', d: 'Los agricultores de la cultura Cucuteni-Trípila de la actual Ucrania levantan los mayores asentamientos de la Tierra de su época — Talianky alberga tal vez 15.000 personas en cientos de hectáreas, 5000 años antes de Kyiv.' },
  giza_pyramid: { n: 'Se construye la Gran Pirámide de Guiza', p: 'Guiza, Egipto', d: 'La pirámide de Keops — 146 m de altura, la estructura humana más alta durante 3800 años — se alza en la orilla occidental del Nilo.' },
  stonehenge: { n: 'Se completa Stonehenge', p: 'Stonehenge, Britania', d: 'Constructores neolíticos alzan los grandes trilítos de sarsén en la llanura de Salisbury, alineados con el amanecer del solsticio de verano — contemporáneos de los constructores de las pirámides.' },
  caral: { n: 'La civilización Caral-Supe', p: 'Caral, Perú', d: 'La ciudad más antigua conocida de América florece en la costa peruana con pirámides monumentales — sin cerámica, sin señales de guerra y con registros parecidos a los quipus.' },
  akkad: { n: 'El Imperio acadio — el primer imperio', p: 'Acad, Mesopotamia', d: 'Sargón de Acad forja el primer imperio multiétnico de la historia, extendido del golfo Pérsico al Mediterráneo.' },
  gilgamesh: { n: 'La Epopeya de Gilgamesh', p: 'Uruk, Mesopotamia', d: 'La obra maestra más antigua conservada de la literatura universal se compone en sumerio: la búsqueda de la inmortalidad de un rey.' },
  shang: { n: 'La dinastía Shang', p: 'Anyang, China', d: 'La primera dinastía arqueológicamente confirmada de China, célebre por la fundición de bronce y la escritura en huesos oraculares — el ancestro de la escritura china.' },
  minoan: { n: 'La civilización minoica', p: 'Cnosos, Creta', d: 'La primera gran civilización de Europa domina el Egeo desde el palacio de Cnosos, con frescos vibrantes y una escritura aún sin descifrar.' },
  hammurabi: { n: 'El Código de Hammurabi', p: 'Babilonia', d: 'Hammurabi promulga uno de los códigos legales descifrados más antiguos: 282 leyes talladas en una estela — «ojo por ojo».' },
  bronze_collapse: { n: 'El colapso de la Edad del Bronce tardía', p: 'Mediterráneo oriental', d: 'En pocas décadas se desploman las economías palacianas de Micenas a Ugarit — sequía, hambruna, terremotos y los enigmáticos «pueblos del mar».' },
  troy: { n: 'La guerra de Troya (fecha tradicional)', p: 'Troya, Anatolia', d: 'Leyenda y arqueología se confunden: una guerra por Helena de Troya, inmortalizada luego por Homero, en los años en que el mundo del bronce se desmoronaba.' },
  phoenician_alpha: { n: 'El alfabeto fenicio', p: 'Biblos, Fenicia', d: 'Comerciantes fenicios crean un alfabeto consonántico de 22 letras — el ancestro del griego, el latín, el árabe, el hebreo y de la mayoría de las escrituras actuales.' },
  david: { n: 'El Jerusalén del rey David', p: 'Jerusalén', d: 'Según la Biblia, David conquista Jerusalén y la convierte en capital de un reino israelita unido.' },
  kush: { n: 'El reino de Kush', p: 'Meroe, Nubia', d: 'El reino nubio de Kush domina el alto Nilo durante más de un milenio — llega a conquistar el propio Egipto — y levanta en Meroe sus propias pirámides.' },
  olmec: { n: 'La civilización olmeca', p: 'La Venta, México', d: 'La «cultura madre» de Mesoamérica talla colosales cabezas de piedra y establece patrones rituales que heredarán luego mayas y aztecas.' },
  zhou: { n: 'La dinastía Zhou', p: 'Haojing, China', d: 'La dinastía más longeva de China introduce el «Mandato del Cielo», mientras sus últimos siglos producen a Confucio, Laozi y las Cien Escuelas del Pensamiento.' },
  assyria: { n: 'El Imperio neoasirio', p: 'Nínive, Asiria', d: 'La primera verdadera superpotencia: ejércitos de hierro, deportaciones en masa y la gran biblioteca de Asurbanipal hacen de Asiria la dueña de Oriente Próximo.' },
  new_kingdom_ramses: { n: 'Ramsés II', p: 'Tebas, Egipto', d: 'El mayor faraón de Egipto reina 66 años, combate a los hititas en Kadesh y construye Abu Simbel.' },
  olympics: { n: 'Los primeros Juegos Olímpicos', p: 'Olimpia, Grecia', d: 'Las ciudades-estado griegas suspenden las guerras cada cuatro años mientras atletas compiten desnudos en Olimpia en honor de Zeus.' },
  rome_founded: { n: 'La fundación de Roma', p: 'Roma', d: 'Fecha tradicional de la fundación de Roma por Rómulo en el monte Palatino — una aldea que llegará a dominar el Mediterráneo.' },
  homer: { n: 'Homero compone la Ilíada y la Odisea', p: 'Jonia (Esmirna)', d: 'Aedo ciego o tradición de aedos — en cualquier caso, en la costa de Asia Menor se pone la primera piedra de la literatura occidental.' },
  scythia: { n: 'El reino escita', p: 'Estepa del bajo Dniéper, Ucrania', d: 'Nómadas ecuestres a quienes Heródoto entrevistó dominan la estepa ucraniana y venden grano a Atenas; sus kurganes reales aún entregan obras maestras de oro como el Pectoral.' },
  buddha: { n: 'Siddhartha Gautama — el Buda', p: 'Bodh Gaya, India', d: 'Un príncipe del clan Shakya alcanza la iluminación bajo el árbol Bodhi y enseña el Camino Medio: nace una de las grandes religiones del mundo.' },
  confucius: { n: 'Confucio', p: 'Qufu, China', d: 'El pensador más influyente de China enseña una ética de lealtad familiar, ritual y gobierno benevolente — sus ideas moldean Asia Oriental hasta hoy.' },
  achaemenid: { n: 'El Imperio persa aqueménida', p: 'Persépolis, Persia', d: 'Ciro el Grande funda el mayor imperio visto hasta entonces; sus sucesores construyen Persépolis y toleran las religiones locales — incluido el regreso de los judíos a Jerusalén.' },
  temple_destroyed: { n: 'Nabucodonosor destruye Jerusalén', p: 'Jerusalén', d: 'Los ejércitos babilonios incendian el templo de Salomón y deportan a la élite de Judá a Babilonia — el cautiverio babilónico.' },
