  marathon: { n: 'La batalla de Maratón', p: 'Maratón, Grecia', d: 'Los hoplitas atenienses rechazan la primera invasión persa; la legendaria carrera del mensajero Fidípides da nombre a la maratón.' },
  salamis: { n: 'Clima de las guerras médicas', p: 'Termópilas y Salamina', d: 'Los 300 de Leónidas caen en las Termópilas; luego la flota griega destruye la armada de Jerjes en Salamina — la Grecia clásica se salva.' },
  bosporan: { n: 'El Reino del Bósforo', p: 'Panticapeo (Kertch)', d: 'Un reino de raíz griega a ambas orillas del estrecho de Kertch se convierte en el cliente más oriental de Roma — y en la gran vía del comercio entre la estepa y el mar Negro.' },
  warring_states: { n: 'El período de los Reinos Combatientes', p: 'China', d: 'Siete reinos chinos libran una guerra de aniquilación de 250 años que impulsa una carrera de filosofía, táctica y tecnología — de la que emerge Qin.' },
  socrates: { n: 'Sócrates', p: 'Atenas', d: 'El tábano de Atenas lo cuestiona todo; juzgado por «corromper a la juventud», muere por cicuta — enseña filosofía con el ejemplo.' },
  plato: { n: 'Platón', p: 'Atenas', d: 'El discípulo de Sócrates funda la Academia — la universidad prototipo — y escribe diálogos que moldean el pensamiento occidental durante 2400 años.' },
  chersonesus: { n: 'Fundación de Quersoneso', p: 'Quersoneso (Sebastopol)', d: 'Colonos griegos de Heraclea Póntica fundan una polis democrática en la costa suroeste de Crimea; cultivará la costa durante dos milenios y acuñará moneda propia.' },
  aristotle: { n: 'Aristóteles', p: 'Atenas y Pella', d: 'Maestro de Alejandro y fundador del Liceo, sistematiza la lógica, la biología, la ética y la política — «el maestro de los que saben».' },
  alexander: { n: 'Alejandro Magno', p: 'Pella, Macedonia', d: 'En 13 años el joven macedonio conquista de Grecia a la India, difunde la cultura helenística y muere a los 32 en Babilonia.' },
  hellenistic: { n: 'Las conquistas de Alejandro', p: 'Macedonia → India', d: 'Lengua, arte y ciencia griegos se funden con Oriente del Nilo al Indo: la semilla del mundo helenístico.' },
  euclid: { n: 'Los «Elementos» de Euclides', p: 'Alejandría', d: 'El libro de texto más influyente jamás escrito sistematiza la geometría desde cinco axiomas — en uso hasta el siglo XX.' },
  library_alexandria: { n: 'La Biblioteca de Alejandría', p: 'Alejandría, Egipto', d: 'Los Ptolomeos intentan reunir todos los libros del mundo; la gran biblioteca convierte a Alejandría en capital científica del Mediterráneo durante siglos.' },
  maurya: { n: 'El Imperio Maurya', p: 'Pataliputra, India', d: 'Chandragupta Maurya unifica por primera vez la mayor parte del sur de Asia; su ministro Chanakya escribe el maquiavélico «Arthashastra» — 1700 años antes de tiempo.' },
  ashoka: { n: 'Asoka el Grande', p: 'Pataliputra, India', d: 'Tras la carnicería de Kalinga, el mayor emperador de la India abrazará el budismo y tallará edictos de tolerancia religiosa por todo el subcontinente.' },
  kalinga: { n: 'Asoka se convierte al budismo', p: 'Kalinga, India', d: 'Horrorizado por su propia y sangrienta conquista de Kalinga, Asoka se vuelve budista y envía misioneros hasta Egipto y Grecia.' },
