  qin_unify: { n: 'La unificación de China', p: 'Xianyang, China', d: '«Todo bajo el cielo» queda unido bajo un emperador — el comienzo de 2000 años de China imperial.' },
  terracotta: { n: 'El ejército de terracota', p: 'Xi’an, China', d: 'Miles de soldados de arcilla a tamaño real, cada uno distinto, custodian la tumba del Primer Emperador — descubiertos en 1974 por campesinos que cavaban un pozo.' },
  great_wall: { n: 'Comienza la Gran Muralla', p: 'Norte de China', d: 'Ingenieros Qin enlazan murallas anteriores en una «muralla de 10.000 li» contra las incursiones nómadas.' },
  punic2: { n: 'La segunda guerra púnica — Aníbal', p: 'Alpes e Italia', d: 'Aníbal cruza los Alpes con elefantes de guerra y devasta Italia 15 años, aplastando a Roma en Cannas — pero Cartago acaba perdiendo.' },
