  gupta: { n: 'El Imperio Gupta', p: 'Pataliputra, India', d: 'La edad de oro clásica de la India: la poesía de Kalidasa, el Kama Sutra, las matemáticas decimales y el concepto de cero.' },
  aryabhata: { n: 'Ariabhata', p: 'Kusumapura, India', d: 'Calcula π con cuatro decimales, la rotación de la Tierra y la duración del año con asombrosa precisión — a los 23 años.' },
  maya_classic: { n: 'El período clásico maya', p: 'Tikal, Guatemala', d: 'Ciudades-estado de templos piramidales y escritura jeroglífica alcanzan su apogeo, con Tikal y Calakmul como superpotencias rivales.' },
  teotihuacan: { n: 'Teotihuacán', p: 'Teotihuacán, México', d: 'La primera metrópolis de América — más de 100.000 personas a lo largo de la Calzada de los Muertos — exporta arte, dioses e influencia por toda Mesoamérica.' },
  aksum: { n: 'El reino de Aksum', p: 'Aksum, Etiopía', d: 'El imperio mercantil del Cuerno de África emite moneda de oro propia, adopta el cristianismo (hacia 330) y reclama el legado de la reina de Saba.' }
