  gunpowder: { n: 'Se inventa la pólvora', p: 'China', d: 'Alquimistas chinos que buscaban elixires de inmortalidad crean en cambio lo que definirá el próximo milenio de la guerra.' },
  viking_age: { n: 'La era vikinga', p: 'Lindisfarne → Vinland', d: 'Saqueadores, comerciantes y colonos nórdicos alcanzan cuatro continentes — descubren Islandia, Groenlandia y América (hacia 1000) mientras aterran a Europa.' },
  birka: { n: 'Birka — emporio comercial de la era vikinga', p: 'Birka, Suecia', d: 'En una isla del lago Mälaren, la primera verdadera ciudad de Suecia cambia pieles y esclavos por plata del mundo árabe; doscientos años de tumbas cuentan la historia.' },
  gotland_route: { n: 'Gotland y la ruta oriental', p: 'Visby, Gotland', d: 'Mercaderes escandinavos y las tripulaciones llamadas «rus» abren la ruta Báltico → Ládoga → Dniéper → Bizancio; los tesoros de plata de Gotland son los más ricos del mundo vikingo. Cuánto moldearon esas tripulaciones el estado que creció en Kyiv sigue siendo objeto de debate.' },
  harald_fairhair: { n: 'Harald Cabellera Hermosa unifica Noruega', p: 'Hafrsfjord, Noruega', d: 'La victoria de Hafrsfjord (fecha tradicional 872) hace a Harald primer rey de toda Noruega — y, dicen las sagas, empuja a los vencidos a poblar Islandia.' },
