  meiji: { n: 'La Restauración Meiji', p: 'Tokio', d: 'Fin del gobierno samurái; Japón se industrializa a velocidad de vértigo — del aislamiento feudal a potencia mundial en una sola vida.' },
  german_unification: { n: 'La unificación de Alemania', p: 'Berlín (Versalles)', d: 'La «sangre y hierro» de Bismarck — tres guerras, un Reich, proclamado en la Galería de los Espejos.' },
