  munch: { n: 'Edvard Munch', p: 'Oslo, Noruega', d: 'El grito (1893): la ansiedad misma se vuelve icono — «pinté… el grito de la naturaleza», de un hombre que no dejó nunca de pintar el interior de la mente.' },
  nansen: { n: 'Fridtjof Nansen', p: 'Oslo, Noruega', d: 'Explorador polar que dejó congelar su barco a propósito — y luego alto comisionado para los refugiados: el pasaporte Nansen devuelve el nombre a los apátridas y gana el Nobel de la Paz de 1922.' },
  amundsen: { n: 'Roald Amundsen', p: 'Noruega', d: 'Primero por el paso del Noroeste (1903–06), primero en el polo Sur (14 de diciembre de 1911, cinco semanas antes que Scott), primero en sobrevolar el polo Norte — desaparecido en 1928 volando a rescatar a un rival.' },
  nobel: { n: 'Alfred Nobel', p: 'Estocolmo, Suecia', d: 'El inventor de la dinamita dedica su fortuna — cada año desde 1901 — a premiar a quienes «hubieran conferido el mayor beneficio a la humanidad».' },
  kalevala: { n: 'Se publica el «Kalevala»', p: 'Helsinki/Carelia, Finlandia', d: 'Elias Lönnrot cosecha runos cantados por bardos carelios en la epopeya nacional finlandesa — los mitos de Väinämöinen que enseñan a un pueblo que es un pueblo.' },
  curie: { n: 'Marie Curie', p: 'París', d: 'Dos premios Nobel en dos ciencias; acuña «radiactividad» y lleva radio en los bolsillos hasta la muerte.' },
  hrushevsky: { n: 'Myjailo Hrushevsky', p: 'Kyiv', d: 'Su «Historia de Ucrania-Rus» en diez volúmenes devolvió la Rus de Kiev a la historia ucraniana — la respuesta académica a la escuela imperial que la había anexionado al pasado ruso; en 1917 presidió el primer parlamento de Ucrania, la Rada Central, y murió en el exilio soviético.' },
  opium_war: { n: 'La primera guerra del Opio', p: 'Cantón, China', d: 'Gran Bretaña lucha por seguir vendiendo opio en China — y gana Hong Kong y puertos de tratado a cañonazos.' },
  taiping: { n: 'La rebelión Taiping', p: 'Nankín, China', d: 'Un maestro de aldea que decía ser hermano menor de Cristo desata la guerra civil más sangrienta de la historia — 20 millones de muertos.' },
