  panama_canal: { n: 'Se abre el canal de Panamá', p: 'Panamá', d: 'Un corte de 77 km en la selva, más de 25.000 muertos por enfermedad y tierra — el Atlántico y el Pacífico se dan la mano.' },
  wright: { n: 'El primer vuelo con motor', p: 'Kitty Hawk, EE. UU.', d: '12 segundos, 36 metros — los hermanos Wright abren la era de la aviación en una playa ventosa de Carolina.' },
  einstein: { n: 'Albert Einstein', p: 'Berna → Princeton', d: 'Empleado de patentes en Berna, celebridad en Berlín, sabio en Princeton — relatividad, efecto fotoeléctrico, E=mc².' },
  relativity: { n: 'La teoría de la relatividad', p: 'Berna y Berlín', d: '1905: relatividad especial y E=mc²; 1915: la gravedad como espaciotiempo curvado — los eclipses le dan la razón en 1919.' },
  ww1: { n: 'La Primera Guerra Mundial', p: 'Sarajevo → todo el mundo', d: 'Las balas de un asesino en Sarajevo deshacen un siglo de imperios: 20 millones de muertos, matanza de trincheras y el mundo rehecho.' },
  russian_rev: { n: 'La Revolución rusa', p: 'Petrogrado', d: '«Paz, pan y tierra» — caen los Románov, los bolcheviques de Lenin toman el poder: el primer Estado socialista del mundo.' },
