  estonia_1918: { n: 'Estonia declara la independencia', p: 'Tallin, Estonia', d: '24 de febrero de 1918: el Comité de Salvación proclama la República; sigue la guerra de independencia — victoria sobre el Ejército Rojo en Võnnu en 1919, sellada por la Paz de Tartu de 1920.' },
  latvia_1918: { n: 'Letonia declara la independencia', p: 'Riga, Letonia', d: '18 de noviembre de 1918, en el teatro de Riga: un Estado para un pueblo cuyas tierras habían codiciado cruzados, polacos, suecos y rusos durante 700 años.' },
  lithuania_1918: { n: 'Lituania restaura su estadidad', p: 'Vilnius, Lituania', d: '16 de febrero de 1918: el Consejo de Lituania aprueba el Acta de Independencia — el primer Estado lituano moderno desde el Gran Ducado; Vilna, tomada por Polonia en 1920, deja a Kaunas como «capital provisional».' },
  finland_1917: { n: 'Finlandia declara la independencia', p: 'Helsinki, Finlandia', d: '6 de diciembre de 1917: tras 108 años como gran ducado ruso — y 560 como mitad oriental de Suecia — Finlandia se vuelve nación, y la Rusia de Lenin la reconoce primero.' },
