  executed_renaissance: { n: 'El Renacimiento Ejecutado', p: 'Járkov y Kyiv', d: 'La deslumbrante generación ucraniana de los años 1920 — la prosa de Jvylovy, el teatro Berezil de Kurbas, el neoclasicismo de Zerov — es aniquilada por detenciones masivas; en noviembre de 1937 cientos de escritores, académicos y artistas de la república son fusilados en el claro de Sandarmoj.' },
  ww2: { n: 'La Segunda Guerra Mundial', p: 'Todo el mundo', d: 'El conflicto más mortífero de la historia: 70–85 millones de muertos, el Holocausto y el orden mundial reconstruido sobre las cenizas.' },
  soviet_baltic_occupation: { n: 'La ocupación soviética de los países bálticos', p: 'Estonia · Letonia · Lituania', d: 'Protocolo secreto, ultimátum, anexión (1940); decenas de miles deportados a Siberia en vagones de ganado en 1941 y 1949; los Hermanos del Bosque resisten desde los bosques hasta los años 1950. La ocupación dura hasta 1991.' },
  winter_war: { n: 'La guerra de Invierno', p: 'Istmo de Carelia, Finlandia', d: 'Stalin envía 450.000 hombres a Finlandia en pleno invierno ártico — y los finlandeses, con esquís y cócteles Molotov, aguantan 105 días; ceden tierra, pero jamás son conquistados.' },
  holocaust: { n: 'El Holocausto', p: 'Europa ocupada', d: 'La Alemania nazi industrializa el genocidio: seis millones de judíos, además de gitanos, eslavos, presos políticos y otros, asesinados.' },
  wallenberg: { n: 'Raoul Wallenberg', p: 'Budapest, Hungría', d: 'El diplomático sueco que entregó pasaportes protectores y casas seguras a decenas de miles de judíos húngaros — y fue luego detenido por los soviéticos en 1945 para desaparecer en la Lubyanka; declarado muerto en 1947.' },
  dday: { n: 'El día D', p: 'Normandía, Francia', d: 'El mayor desembarco anfibio de la historia — 156.000 soldados aliados ponen pie en Francia y comienza la liberación de Europa occidental.' },
  babi_yar: { n: 'La masacre de Babi Yar', p: 'Kyiv', d: 'El 29 y 30 de septiembre de 1941, el Einsatzgruppe C de las SS fusila a 33.771 judíos de Kyiv en el barranco de Babi Yar — una de las mayores matanzas individuales del Holocausto; durante la ocupación mueren allí decenas de miles de personas más.' },
  upa: { n: 'Ejército Insurgente Ucraniano (UPA)', p: 'Ucrania occidental', d: 'Ejército guerrillero que combatió por un Estado ucraniano independiente contra las fuerzas soviéticas y alemanas — e implicado en la limpieza étnica de civiles polacos en Volinia (1943–44) que aún pesa en la memoria polaco-ucraniana. La cacería soviética duró hasta los años 1950.' },
  hiroshima: { n: 'El bombardeo atómico de Hiroshima', p: 'Hiroshima, Japón', d: 'Una sola bomba destruye una ciudad en segundos; más de 70.000 mueren al instante y comienza la era nuclear.' },
