Object.assign(window.DATA_ES, {
  un_founded: { n: 'Se funda la Organización de las Naciones Unidas', p: 'San Francisco', d: '51 Estados firman la Carta de la ONU en San Francisco — «para preservar a las generaciones venideras del flagelo de la guerra».' },
  india_independence: { n: 'Independencia de la India y partición', p: 'Nueva Delhi', d: 'Termina el Raj; nacen la India y Pakistán — y hasta un millón de personas mueren en el caos de la partición mientras 15 millones huyen.' },
  gandhi: { n: 'Mahatma Gandhi', p: 'India', d: 'Un abogado en taparrabos derrota al mayor imperio de la Tierra sin disparar un tiro — y luego muere asesinado por uno.' },
  prc: { n: 'Se proclama la República Popular China', p: 'Pekín', d: 'Mao anuncia desde la Puerta de la Paz Celestial: «el pueblo chino se ha levantado».' },
  mao: { n: 'Mao Zedong', p: 'Pekín', d: 'Estratega guerrillero, tirano fundador: el Gran Salto Adelante hambrea a decenas de millones; la Revolución Cultural quema una década.' },
  cold_war: { n: 'La guerra fría', p: 'Washington ↔ Moscú', d: 'Dos superpotencias, miles de cabezas nucleares, guerras por delegación en todos los continentes — y, por poco, no hay tercera guerra mundial.' },
  korean_war: { n: 'La guerra de Corea', p: 'Corea', d: 'La primera guerra caliente de la guerra fría: tres años, 3 millones de muertos y una península aún dividida en el paralelo 38.' },
  decolonization_africa: { n: 'La descolonización de África', p: 'Acra, Ghana', d: 'Ghana abre el camino; en dos décadas la mayor parte de África es libre — «buscad primero el reino político» — Nkrumah.' },
  sputnik: { n: 'Se lanza el Sputnik', p: 'Tiuratam, URSS', d: 'Una esfera metálica de 58 cm pita sobre nuestras cabezas — comienza la era espacial, y EE. UU., en pánico, crea la NASA.' },
  gagarin: { n: 'Gagarin orbita la Tierra', p: 'Baikonur', d: '«¡Vamos!» — 108 minutos que hacen de Yuri Gagarin el primer ser humano en el espacio, para siempre.' },
  everest: { n: 'Primer ascenso al Everest', p: 'Monte Everest', d: 'Hillary y Tenzing pisan la cima del mundo el 29 de mayo de 1953 — la noticia llega a Londres el día de la coronación.' },
  dna: { n: 'Se descubre la estructura del ADN', p: 'Cambridge', d: 'Watson, Crick y la Foto 51 de Franklin revelan la doble hélice — el plano de la vida.' },
  cuban_crisis: { n: 'La crisis de los misiles de Cuba', p: 'Cuba', d: 'Trece días al borde de la guerra nuclear — Kennedy y Jruschov ceden, y luego construyen el teléfono rojo.' },
  mlk_speech: { n: '«Tengo un sueño»', p: 'Washington D. C.', d: 'Un cuarto de millón de personas marcha sobre Washington; desde los escalones del Lincoln, el sueño de King entra en la historia.' },
  mlk: { n: 'Martin Luther King Jr.', p: 'Atlanta, EE. UU.', d: 'La no violencia como estrategia y sermón — la voz con Nobel del movimiento por los derechos civiles, asesinado a los 39.' },
  vietnam_war: { n: 'La guerra de Vietnam', p: 'Vietnam', d: 'Veinte años de guerra acaban con helicópteros despegando del techo de la embajada de Saigón — la primera guerra perdida por televisión.' },
  apollo11: { n: 'El Apolo 11 aluniza', p: 'Cabo Cañaveral → Luna', d: '«El Águila ha alunizado». Armstrong y Aldrin caminan en otro mundo ante 600 millones de espectadores — «un gran salto para la humanidad».' },
  berlin_wall: { n: 'Cae el muro de Berlín', p: 'Berlín', d: 'Una conferencia de prensa desastrosa, y luego martillos: el muro se abre, y el más concreto símbolo de la guerra fría se desmorona.' },
  singing_revolution: { n: 'La Revolución Cantada y la Vía Báltica', p: 'Tallin → Riga → Vilnius', d: 'Cientos de miles cantan a una voz canciones prohibidas — y el 23 de agosto de 1989 dos millones de personas se cogen de la mano a lo largo de 675 km de Tallin a Vilnius. Lituania declara primero la restauración (11 de marzo de 1990); en agosto de 1991 los tres países ya son libres.' },
  www: { n: 'Se inventa la World Wide Web', p: 'CERN, Ginebra', d: 'Tim Berners-Lee publica HTML, HTTP y el primer navegador — y luego lo regala todo gratis.' },
  soviet_collapse: { n: 'Disolución de la URSS', p: 'Moscú', d: 'Quince repúblicas, una bandera arriada: la Unión Soviética termina el día de Navidad de 1991 — y con ella la guerra fría.' },
  ukraine_independence: { n: 'Ucrania declara su independencia', p: 'Kyiv', d: 'El 24 de agosto de 1991, tras el colapso del golpe de Moscú, la Rada Suprema declara la independencia; el 1 de diciembre, más del 90 % de los votantes — con mayorías en todas las regiones — la confirma en referéndum.' },
  maidan: { n: 'Euromaidán / Revolución de la Dignidad', p: 'Kyiv', d: 'Protestas masivas estallan cuando el gobierno suspende el Acuerdo de Asociación con la UE; a los tres meses, francotiradores matan a un centenar de manifestantes (el Centenar Celestial) y el presidente huye — Rusia responde anexionándose Crimea e incendiendo la guerra en el Donbás.' },
  stus: { n: 'Vasyl Stus', p: 'Región de Vinnitsa, Ucrania', d: 'Poeta y traductor que se negó a abjurar: 23 años de su vida entre prisiones, campos y exilio, muerto en huelga de hambre en Perm-36 en 1985 — rehabilitado póstumamente y enterrado de nuevo como figura nacional.' },
  ukraine_war: { n: 'La guerra ruso-ucraniana', p: 'Ucrania', d: 'Comenzando con la anexión de Crimea y la guerra encubierta en el Donbás (2014), Rusia lanza su invasión a gran escala de Ucrania el 24 de febrero de 2022 — la mayor guerra en Europa desde 1945. Kyiv resiste, y la guerra reordena el mundo.' },
  mandela_elected: { n: 'Mandela, elegido presidente', p: 'Pretoria', d: 'Tras 27 años preso, Nelson Mandela gana las primeras elecciones libres de Sudáfrica — y perdona a sus carceleros.' },
  mandela: { n: 'Nelson Mandela', p: 'Sudáfrica', d: '27 años en la isla Robben y luego la reconciliación antes que la venganza — la conciencia de una nación.' },
  sept11: { n: 'Atentados del 11 de septiembre', p: 'Nueva York', d: 'Aviones secuestrados derriban las Torres Gemelas: 2977 muertos y la primera jornada de infamia del siglo XXI.' },
  covid: { n: 'Pandemia de COVID-19', p: 'Wuhan → todo el mundo', d: 'La primera pandemia de la era conectada: más de 7 millones de muertos notificados, ciudades confinadas, vacunas de ARNm en un año.' },
  ghana_empire: { n: 'Imperio de Ghana (Wagadu)', p: 'Kumbi Saleh, Mauritania', d: 'El primer gran Estado comercial del Sahel: el oro del sur se encuentra con la sal y las caravanas del norte — los autores árabes llaman a su soberano «el rey más rico».' },
  songhai: { n: 'Imperio songhay', p: 'Gao, Malí', d: 'Sunni Alí y Askia Mohamed construyen el mayor imperio de África occidental a lo largo del Níger; termina en los mosquetes marroquíes de Tondibi (1591).' },
  benin: { n: 'Reino de Benín', p: 'Ciudad de Benín, Nigeria', d: 'Sus murallas, más largas que la Gran Muralla, y sus fundiciones de latón — los «bronces de Benín» — entre la mejor escultura jamás hecha; saqueadas por una expedición punitiva británica en 1897.' },
  kongo: { n: 'Reino del Congo', p: 'M’banza-Kongo, Angola', d: 'Un reino de África central en diplomacia directa con Portugal desde 1483 — hasta que la trata y la conquista colonial lo entierran.' },
  swahili: { n: 'Costa suajili y Kilwa', p: 'Kilwa, Tanzania', d: 'Ciudades-estado de Mogadiscio a Sofala funden los mundos africano, árabe y persa; el comercio de oro de Kilwa financia un palacio de coral en piedra cuando llega Vasco da Gama.' },
  moche: { n: 'Cultura moche', p: 'Valle de Moche, Perú', d: 'La costa norte del Perú domina el riego, la cerámica de línea fina y los retratos en metal precioso — un milenio antes que los incas.' },
  tiwanaku: { n: 'Tiwanaku', p: 'Tiwanaku, Bolivia', d: 'A 3800 m en el altiplano, una ciudad de piedra con puertas monolíticas y agricultura en camellones ancla la civilización andina durante seis siglos.' },
  nazca: { n: 'Líneas de Nazca', p: 'Desierto de Nazca, Perú', d: 'Cientos de figuras gigantes — colibrí, mono, ¿astronauta? — grabadas en el desierto, legibles solo desde el cielo.' },
  delhi_sultanate: { n: 'Sultanato de Delhi', p: 'Delhi', d: 'Sultanes turco-afganos gobiernan el norte de la India 320 años — conteniendo a los mongoles, alzando el Qutb Minar y dejando una síntesis persa-hindustaní.' },
  vijayanagara: { n: 'Vijayanagara', p: 'Hampi, India', d: 'La mayor ciudad de la India — quizá del mundo — hacia 1500, con templos y bazares alabados por visitantes persas y portugueses.' },
  majapahit: { n: 'Majapahit', p: 'Trowulan, Indonesia', d: 'La talasocracia de Java gobierna (o grava con impuestos) puertos de Sumatra a Nueva Guinea — la gran edad de los mares de las especias.' },
  srivijaya: { n: 'Srivijaya', p: 'Palembang, Indonesia', d: 'Un imperio marítimo budista de Sumatra controla el estrecho de Malaca — el gozne del comercio entre China e India — hasta que la flota Chola lo saquea.' },
  kamakura: { n: 'Shogunato Kamakura', p: 'Kamakura, Japón', d: 'Los samuráis toman el poder real a la corte de Kioto; comienza la edad guerrera de Japón — que sobrevive a dos invasiones mongolas (1274, 1281) ayudada por el «viento divino».' },
  hangul: { n: 'Hangul — el alfabeto coreano', p: 'Seúl, Corea', d: 'Los sabios del rey Sejong diseñan un alfabeto tan lógico que «un hombre sabio puede aprenderlo en una mañana» — hoy, las mejores tasas de alfabetización del mundo.' },
  samanid: { n: 'Dinastía samánida', p: 'Bujará', d: 'La lengua y las letras persas renacen bajo una dinastía que hizo de Bujará rival de Bagdad — ancestros de Rumi y semillero del islam persa.' },
  maratha: { n: 'Imperio maratha', p: 'Raigad, India', d: 'El reino de fuertes en colinas de Shivaji crece hasta la potencia que rompe la supremacía mogol — y casi la sustituye, antes de que prevalezcan las armas británicas.' },
  movable_type: { n: 'Se inventan los tipos móviles', p: 'Kaifeng, China', d: 'El plebeyo Bi Sheng funde caracteres en arcilla — cuatro siglos antes que Gutenberg; en el enorme inventario de signos del chino, la xilografía siguió siendo a menudo más barata.' },
  peopling_americas: { n: 'Los primeros americanos', p: 'Clovis, Nuevo México', d: 'Cazadores-recolectores de la era glacial venidos de Beringia se extienden al sur por la costa del Pacífico y las llanuras libres de hielo; sus puntas acanaladas Clovis aparecen de Alaska a Chile en pocos siglos — gente en casa en un mundo aún lleno de mamuts.' },
  poverty_point: { n: 'Poverty Point', p: 'Poverty Point, Luisiana', d: 'Cazadores-recolectores de Luisiana — sin agricultura, sin cerámica — levantan un vasto complejo de terraplenes concéntricos en el bajo Misisipi, importando cobre, piedra y concha de media región.' },
  hopewell: { n: 'Terraplenes Hopewell', p: 'Chillicothe, Ohio', d: 'Comunidades del valle del Ohio alzan terraplenes geométricos precisos alineados con el sol y la luna, reuniendo mica de las Carolinas, obsidiana de Yellowstone y conchas del golfo para ceremonias funerarias que unieron un continente.' },
  muisca: { n: 'Confederación muisca', p: 'Sabana de Bogotá, Colombia', d: 'Centros cacicales del frío altiplano andino trabajan el oro en ofrendas para lagos sagrados — el nuevo cacique, cubierto de polvo de oro, se lanzaba en balsa al lago Guatavita: la semilla de «El Dorado».' },
  amazonia_towns: { n: 'Ciudades jardín amazónicas', p: 'Alto Xingú, Amazonía', d: 'Lejos de ser un desierto vacío: ciudades de plazas, empalizadas y pesquerías unidas por caminos bordeados, con suelos negros de terra preta creados y cultivados por manos humanas — la arqueología está reescribiendo la Amazonía.' },
  chaco: { n: 'Cañón del Chaco', p: 'Cañón del Chaco, Nuevo México', d: 'Los pueblo ancestrales alzan un centro ceremonial desértico de grandes casas de varias plantas alineadas con el sol y la luna, cosidas por caminos a través de la cuenca del San Juan — hasta que la sequía lo dispersa.' },
  chimu: { n: 'Chimú — Chan Chan', p: 'Chan Chan, Perú', d: 'La mayor ciudad de adobe de la Tierra, 20 km² de ciudadelas amuralladas, gobierna la mayor parte de la costa peruana con canales, embalses y tributo — hasta que los incas se llevan a sus orfebres al Cusco.' },
  thule: { n: 'Expansión thule', p: 'Vertiente Norte, Alaska', d: 'Cazadores de ballenas inuit en botes de piel y trineos de perros se extienden de Alaska a Groenlandia en tres siglos, sucediendo al antiguo pueblo dorset — ancestros de los inuit de hoy, en casa donde casi nadie más vive.' },
  mesa_verde: { n: 'Viviendas en acantilado de Mesa Verde', p: 'Mesa Verde, Colorado', d: 'Los pueblos pueblo ancestrales mudan ciudades enteras a los abrigos rocosos — el Palacio del Acantilado solo tiene 150 habitaciones — antes de que sequía y tensión vacíen las mesetas hacia 1300.' },
  haudenosaunee: { n: 'Confederación Haudenosaunee', p: 'Onondaga, Nueva York', d: 'El Pacificador y Hiawatha unen cinco naciones en guerra bajo el Gran Árbol de la Paz en Onondaga — jefes elegidos por las madres de clan, decisiones en consejo; la confederación aún se reúne, y sus ideas federales resuenan en la unión americana.' },
  potosi: { n: 'Potosí — la montaña de plata', p: 'Potosí, Bolivia', d: 'La plata del Cerro Rico — extraída con la mita, el trabajo forzado que reclutaba a las comunidades andinas — financia las guerras de España y gran parte de la moneda del mundo; hacia 1600 la ciudad del boom rivaliza con las capitales de Europa, a 4000 m.' },
  mapuche_resistance: { n: 'Resistencia mapuche', p: 'Araucanía, Chile', d: 'Lautaro, antes paje de Valdivia, vuelve el arte de la caballería española contra España; casi un siglo de guerra acaba en el Tratado de Quilín (1641), que reconoce las tierras mapuches al sur del Biobío — una frontera que España honró en gran medida durante dos siglos.' },
  jamestown: { n: 'Jamestown', p: 'Jamestown, Virginia', d: 'El primer asentamiento inglés permanente de América: el «tiempo del hambre», Pocahontas, el tabaco de John Rolfe — y 1619, cuando la primera asamblea electa y los primeros africanos cautivos de la América inglesa llegan con un mes de diferencia.' },
  quebec_founded: { n: 'Fundación de Quebec', p: 'Ciudad de Quebec', d: 'La «habitación» de Champlain sobre el acantilado del San Lorenzo se vuelve capital de la Nueva Francia — hoy la ciudad francófona más antigua de América.' },
  palenques: { n: 'Palenques — pueblos africanos libres', p: 'San Basilio de Palenque, Colombia', d: 'Africanos cimarrones bajo Benkos Biohó alzan pueblos libres amurallados en la hinterland de Cartagena; San Basilio de Palenque, que arrancó su reconocimiento a España en 1691, aún habla el único criollo de base española de América.' },
  mayflower: { n: 'El Acuerdo del Mayflower', p: 'Plymouth, Massachusetts', d: 'Antes de desembarcar, los pasajeros del Mayflower pactan un «cuerpo político civil» — autogobierno por acuerdo, texto fundacional del constitucionalismo americano.' },
  salem: { n: 'Los juicios de brujas de Salem', p: 'Salem, Massachusetts', d: 'Acusaciones, «pruebas espectrales» y 19 ahorcamientos en un solo año — la cacería de brujas de Nueva Inglaterra se vuelve el sinónimo mundial de una justicia movida por el miedo.' },
  toussaint: { n: 'Toussaint Louverture', p: 'Saint-Domingue (Haití)', d: 'Nacido esclavo en una plantación, llega a general y gobernador de la Revolución haitiana, derrota a España, Gran Bretaña y la expedición de Napoleón — y muere en una cárcel francesa meses antes de declararse la independencia.' },
  tecumseh: { n: 'Tecumseh', p: 'Thamesville, Canadá', d: 'El estadista shawnee que forjó una confederación panindígena de los Grandes Lagos al golfo para frenar la expansión americana — muerto combatiendo junto a los británicos en la guerra de 1812; con él muere la confederación.' },
  tupac_amaru_ii: { n: 'La gran rebelión de Túpac Amaru II', p: 'Tungasuca, Perú', d: 'Un cacique descendiente del último inca reivindica el nombre de su ancestro y alza los Andes contra el trabajo forzado y los impuestos — el mayor levantamiento de la América colonial muere ahogado en sangre, una generación antes de la independencia.' },
  yorktown: { n: 'El sitio de Yorktown', p: 'Yorktown, Virginia', d: 'Washington y Rochambeau inmovilizan a Cornwallis contra el río York mientras la flota de de Grasse sella la bahía de Chesapeake — «el mundo al revés»: Gran Bretaña negocia, y la independencia está ganada.' },
  lewis_clark: { n: 'La expedición de Lewis y Clark', p: 'San Luis → Pacífico', d: 'El «Cuerpo de Descubrimiento» de Jefferson cartografía la nueva Compra de Luisiana de San Luis al Pacífico y vuelta — guiado a través de las montañas y de regreso a casa por la diplomática shoshone Sacagawea.' },
  mexico_independence: { n: 'El Grito de Dolores', p: 'Dolores, México', d: 'A medianoche del 16 de septiembre de 1810, el cura Miguel Hidalgo hace sonar la campana parroquial y proclama la independencia — once años de guerra acaban con el Ejército de las Tres Garantías entrando en la Ciudad de México.' },
  brazil_independence: { n: 'La independencia de Brasil', p: 'Ipiranga, São Paulo', d: '«¡Independencia o muerte!» — el príncipe Pedro desenvaina su espada junto al arroyo de Ipiranga, y Brasil se separa de Portugal sin guerra, conservando monarca hasta 1889.' },
  trail_of_tears: { n: 'El Sendero de Lágrimas', p: 'Apalaches del sur → Oklahoma', d: 'Bajo la ley de traslado de los indios, unas 60.000 personas de las naciones cherokee, choctaw, chickasaw, creek y seminola son forzadas al oeste del Misisipi; miles mueren en el camino, y la sentencia del Tribunal Supremo a su favor se ignora sin más.' },
  gold_rush: { n: 'La fiebre del oro de California', p: 'Sutter’s Mill, California', d: 'El oro del río Americano atrae a 300.000 personas por tierra y mar en tres años — San Francisco es ciudad de la noche a la mañana y California estado en 1850, sobre tierra arrebatada a México semanas después del primer hallazgo.' },
  transcontinental_rr: { n: 'El primer ferrocarril transcontinental', p: 'Promontory Summit, Utah', d: 'Cuadrillas irlandesas y chinas empujan la Union Pacific y la Central Pacific una contra otra; el último clavo cae el 10 de mayo de 1869, y el viaje de costa a costa baja de meses a una semana.' },
  canada_confed: { n: 'La Confederación canadiense', p: 'Ottawa', d: 'Ontario, Quebec, Nueva Escocia y Nuevo Brunswick se unen como Dominio de Canadá — «paz, orden y buen gobierno»: la primera colonia que cambia imperio por autogobierno responsable.' },
  abolition_brazil: { n: 'Brasil abole la esclavitud', p: 'Río de Janeiro', d: 'La Ley Áurea pone fin al último régimen esclavista de América — unos cuatro millones de africanos y descendientes esclavizados a lo largo de 350 años — sin tierra ni compensación para los liberados; la monarquía cae en dieciocho meses.' },
  klondike: { n: 'La fiebre del oro de Klondike', p: 'Klondike, Yukón', d: 'Cien mil aventureros cargan cada uno una tonelada de equipo por el paso Chilkoot hasta el Yukón; el boom se agota en dos años dejando pueblos fantasma — y a Jack London.' },
  mexican_revolution: { n: 'La Revolución mexicana', p: 'México', d: 'La caída de Díaz abre una década de guerra civil — la «Tierra y Libertad» de Zapata, la caballería de Villa, la constitución de 1917 con derechos laborales y agrarios — un millón de muertos y una nación repensada por sus muralistas.' },
  cuban_revolution: { n: 'La Revolución cubana', p: 'Sierra Maestra, Cuba', d: 'Castro, el Che y ochenta expedicionarios desembarcan del Granma; dos años de guerra guerrillera en la Sierra Maestra acaban con su entrada en La Habana — reforma agraria y campañas de alfabetización dentro; exilio y crisis fuera.' },
  aboriginal: { n: 'Culturas aborígenes australianas', p: 'Tierra de Arnhem, Australia', d: 'Más de 65.000 años de cultura continua — la más antigua del mundo — con historias orales que quizá recuerdan costas reales de la era glacial.' }
});

/* Príncipes de la Rus de Kyiv — añadidos el 27-10-2026 (fuentes ucranianas) */
Object.assign(window.DATA_ES, {
  askold_dir: { n: 'Askold y Dir — príncipes de Kyiv', p: 'Tumba de Askold, Kyiv', d: 'Gobernantes de Kyiv antes de los Ruríkidas: dirigieron la primera incursión de la Rus contra Constantinopla (860) y, según la tradición posterior, recibieron allí el bautismo. Muertos a manos del príncipe Oleg, que hizo de la ciudad la «madre de las ciudades rus»; la tumba de Askold en Kyiv aún lleva su nombre.' },
  oleg: { n: 'Oleg el Profeta', p: 'Kyiv', d: 'Tutor del pequeño Ígor: tomó Smolensk y Kyiv (882) y arrancó a Bizancio concesiones comerciales en los tratados de 907 y 911 — el constructor del Estado que la crónica llama Rus.' },
  ihor: { n: 'Ígor el Viejo', p: 'Kyiv', d: 'Heredero de Riúrik según la crónica, primer Ruríkida en el trono de Kyiv; renovó los tratados con Bizancio tras una incursión fallida (941) y murió cobrando tributo en Iskorosten — la revuelta de los drevlianos la domó su viuda Olga.' },
  olha: { n: 'La princesa Olga — regente de la Rus', p: 'Kyiv', d: 'Regente del pequeño Sviatoslav tras el asesinato de Ígor: sus distritos de tributo y puestos de posta (uroky y povosty) son la primera reforma administrativa conocida de la Rus, y su bautismo en Constantinopla (hacia 955) anticipó el año 988. Venerada como santa.' },
  sviatoslav: { n: 'Sviatoslav el Bravo', p: 'Kyiv', d: 'El primer príncipe de la Rus que no se quedó quieto: destruyó el jaganato jázaro (965), buscó el Danubio y una nueva capital en Pereyaslávets, plantó cara a Bizancio en Doróstolon — y cayó ante los pechenegos en los rápidos del Dniéper.' },
  yaropolk: { n: 'Yaropolk Sviatoslávich', p: 'Kyiv', d: 'Hijo mayor de Sviatoslav, benévolo con los cristianos de una Kyiv aún pagana; murió por la traición de Blud a manos de su hermano Volodímir, que se apoderó del trono.' },
  sviatopolk_ok: { n: 'Sviatopolk el Maldito', p: 'Kyiv', d: 'Príncipe de Túrov que tomó el trono en 1015 y asesinó a sus hermanos Borys y Hlib — los primeros santos de la Rus; derrotado por Yaroslav junto al río Alta (1019), murió huyendo hacia Polonia.' },
  iziaslav1: { n: 'Iziaslav I Yaroslávich', p: 'Kyiv', d: 'El mayor de los hijos de Yaroslav: tres veces en el trono de Kyiv y dos expulsado — una por el levantamiento de Kyiv de 1068 tras la derrota ante los polovtsy, otra por la coalición de sus hermanos; cayó en Nezhatyna Nyva (1078) junto a Vsevolod.' },
  vseslav: { n: 'Vseslav el Hechicero de Pólatsk', p: 'Pólatsk, Bielorrusia', d: 'El príncipe legendario de Pólatsk — nacido con el velo, al que el Cantar de las huestes de Ígor atribuye aullidos de lobo nocturnos: el alzamiento de 1068 lo sentó siete meses en el trono de Kyiv — el único no Yaroslávich del siglo.' },
  sviatoslav2: { n: 'Sviatoslav II Yaroslávich de Cherníhiv', p: 'Cherníhiv', d: 'Hijo mediano de Yaroslav, príncipe de Cherníhiv, que depuso a su hermano mayor Iziaslav (1073) — el primer golpe fraterno de la Rus; mecenas del Izbornik de 1076, el libro eslovaco oriental datado más antiguo.' },
  vsevolod1: { n: 'Vsevolod I Yaroslávich', p: 'Pereyaslav, Ucrania', d: 'El menor de los Yaroslávich — letrado, helenista, se decía que hablaba cinco lenguas; sostuvo desde Pereyaslav la frontera esteparia y acabó como soberano único (1078–93), el último que mantuvo la Rus entera; padre de Vladímir Monómaco.' },
  sviatopolk2: { n: 'Sviatopolk II Iziaslávich', p: 'Kyiv', d: 'Gobernó en el apogeo polovtsiano con cargas pesadas y moneda falsificada; al morir él, Kyiv se alzó (1113) y llamó al trono a Vladímir Monómaco.' },
  monomakh: { n: 'Vladímir II Monómaco', p: 'Kyiv', d: 'Llamado al trono por el alzamiento de 1113: su Estatuto limitó la usura y la servidumbre por deudas, su «Enseñanza» fijó la ética del príncipe, y sus campañas esteparias quebraron las incursiones polovtsianas por una generación.' },
  mstyslav1: { n: 'Mstislav I el Grande', p: 'Kyiv', d: 'El último soberano de una Rus unida (1125–32): sometió al linaje principesco de Pólatsk a la estepa, deportó a los príncipes de Pólatsk a Bizancio y fundó la iglesia de la Pyrohoshcha de Kyiv — el cronista lo llamó el Grande.' },
  yaropolk2: { n: 'Yaropolk II Volodímirovich', p: 'Kyiv', d: 'Heredó todo el Estado, pero pagó la paz cediendo Pereyaslav a los Ólgovich de Cherníhiv — la concesión que armó a todas las ramas; murió en 1139 cuando Vsevolod II ya marchaba sobre Kyiv.' },
  viacheslav: { n: 'Viacheslav Volodímirovich', p: 'Kyiv', d: 'Tercer hijo de Monómaco: dos veces gran príncipe ceremonial (1139, 1150–54) mientras rivales menores retenían el poder real — sus «reinados» muestran el trono convertido en premio de la política de coaliciones.' },
  vsevolod2: { n: 'Vsevolod II Ólgovich', p: 'Cherníhiv', d: 'Príncipe de Cherníhiv que preguntó al veche de Kyiv sin más: «¿Me queréis?» — y este respondió que sí (1139). El primer Ólgovich en el trono; bajo él el eje de la Rus se desplazó a Cherníhiv, y la ciudad la conservó con dádivas.' },
  ihor2: { n: 'Ígor II Ólgovich', p: 'Cherníhiv', d: 'Hermano de Vsevolod II: dos semanas en el trono hasta que el veche lo relevó; apresado en la iglesia del Diezmo, linchado por la muchedumbre de Kyiv (1147) — venerado luego como pasionario.' },
  iziaslav2: { n: 'Iziaslav II Mstislávich', p: 'Volodímir, Ucrania', d: 'El favorito del veche — un nieto belicoso de Monómaco que se peleó por Kyiv con Yuri Dolgorúkov durante los años 1140–50, defendió el derecho de la ciudad a su príncipe y respaldó al primer metropolita nacido en la Rus, Klym Smoliátich.' },
  dolgoruky: { n: 'Yuri Dolgorúkov («Brazo Largo»)', p: 'Súzdal', d: 'Príncipe de Rostov-Súzdal, el menor de Monómaco: tomó Kyiv dos veces (1149–51, 1155–57) y murió allí, con sospechas de envenenamiento. La primera mención de Moscú (1147) es su invitación a un banquete — germen de la leyenda fundacional de aquella ciudad.' },
  rostyslav1: { n: 'Rostislav I Mstislávich de Smolensk', p: 'Smolensk', d: 'El intermediario honroso de una sucesión rota: llamado dos veces por el veche (1154, 1159–67), su segundo y largo reinado dio a un Kyiv agotado dos décadas de orden y zanjó la disputa eclesiástica con Cherníhiv.' },
  iziaslav3: { n: 'Iziaslav III Davídovich', p: 'Cherníhiv', d: 'Un Davidida de Cherníhiv que cabalgó sobre las querellas de los Monómaco para sentarse tres veces en el trono (1154–55, 1157–58, 1161); murió en 1162 tentando un cuarto reinado.' },
  mstyslav2: { n: 'Mstislav II Iziaslávich', p: 'Kyiv', d: 'Príncipe de Volinia, la elección del veche (1167–69) y el último gran príncipe fuerte de Kyiv: la coalición vengativa de Andréi Bogoliubski saqueó la ciudad (1169) y rompió para siempre su primacía.' },
  hlib: { n: 'Gleb Yuriévich', p: 'Pereyaslav, Ucrania', d: 'Hijo de Dolgorúkov, príncipe de Pereyaslav, sentado en Kyiv por Andréi Bogoliubski (1169–71) — el primer príncipe impuesto desde el norte; murió de repente en 1171, y la crónica susurra veneno.' },
  volodymyr3: { n: 'Volodímir III Mstislávich', p: 'Dorohobuzh, Ucrania', d: 'El hijo menor de Mstislav el Grande, príncipe de Dorohobuzh: cinco meses en el trono de Kyiv en 1171 por voluntad del veche — un respiro entre soberanos impuestos.' },
  mykhalko: { n: 'Mijalko Yuriévich', p: 'Vyshhorod, Ucrania', d: 'Llamado al trono por los kyivitas (1171), se quedó en Vyshhorod y Torchesk — prueba de que el trono había perdido su tirón; murió en 1176 en Gorodets, junto al Oster.' },
  roman1: { n: 'Román I Rostislávich de Smolensk', p: 'Smolensk', d: 'Dos reinados en el trono de Kyiv (1171–73, 1174–76): equilibró a los Rostislávich de Smolensk frente a Sviatoslav de Cherníhiv, hasta que este superó a todos.' },
  vsevolod3: { n: 'Vsevolod el Gran Nido', p: 'Vladímir sobre el Kliazma', d: 'Padre de una docena de príncipes: pasó por Kyiv unas semanas de 1173, cuando la ciudad se alzó contra los delegados de Bogoliubski, y luego gobernó las tierras del Kliazma desde Vladímir — más rico y fuerte que Kyiv, pero ya sin ser su príncipe.' },
  riuryk: { n: 'Riúrik Rostislávich de Ovruch', p: 'Ovruch, Ucrania', d: 'Más co-gobernante que soberano único: el «duunvirato» de 1181–94 con Sviatoslav III dirigió el Estado desde Kyiv y Ovruch. El 2 de enero de 1203 condujo a los Ólgovich y los polovtsy contra la propia Kyiv — Román de Hálich respondió tonsurándolo a la fuerza como monje.' },
  yaroslav2: { n: 'Yaroslav II Iziaslávich de Lutsk', p: 'Lutsk, Ucrania', d: 'El decano de la línea voliniana: gran príncipe nominal en 1173–74 con el respaldo de Smolensk y del veche, mientras los delegados de Súzdal flaqueaban; su hijo Íngvar mantuvo viva la pretensión de Lutsk sobre Kyiv hasta los años 1230.' },
  sviatoslav3: { n: 'Sviatoslav III Vsevolódovich', p: 'Cherníhiv', d: 'Príncipe de Cherníhiv al que el Cantar de las huestes de Ígor dirige su «palabra dorada»: co-soberano desde 1181, gran príncipe único desde 1194 — su gobierno fue el último gobierno fuerte de Kyiv.' },
  roman2: { n: 'Román Mstislávich el Grande', p: 'Hálich, Ucrania', d: 'Príncipe de Volinia que conquistó Hálich y, dice la crónica, se volvió «autócrata de toda la Rus»: retuvo Kyiv en 1202–05 y cayó en Zawichost (1205) luchando contra los polacos — la unión de Hálich y Volinia que forjó se convirtió en heredera de la estatalidad de Kyiv.' },
  ingvar: { n: 'Íngvar Yaroslávich de Lutsk', p: 'Lutsk, Ucrania', d: 'Príncipe de Lutsk al que Román el Grande sentó en el trono de Kyiv como su regente (1201–03); en 1212 ayudó a expulsar a Vsevolod el Rojo y luego entregó voluntariamente la capital a Mstislav el Viejo. Héroe de la crónica de Hálich-Volinia, citado en el Cantar de las huestes de Ígor.' },
  rostyslav2: { n: 'Rostislav II Riuríkovich', p: 'Vyshhorod, Ucrania', d: 'Hijo de Riúrik, sentado en Kyiv por Román el Grande (1204–05) mientras su padre vestía el hábito — una nota al margen del intento de Román de controlar ambas capitales; muerto antes de 1210.' },
  vsevolod4: { n: 'Vsevolod el Rojo', p: 'Cherníhiv', d: '«El Rojo», un Sviatoslávich de Cherníhiv: tomó Kyiv dos veces (1206–07, 1210–12) en el pulso Cherníhiv–Smolensk, hasta que Mstislav el Viejo e Íngvar se lo llevaron para siempre.' },
  mstyslav3: { n: 'Mstislav III el Viejo', p: 'Smolensk', d: 'Príncipe de Smolensk que retuvo Kyiv entre 1212 y 1223 y llevó el ejército de los príncipes al Kalka (1223): confió en un campamento fortificado más que en el arte estepario — y allí pereció con toda su druzhina.' },
  volodymyr4: { n: 'Volodímir IV Riuríkovich', p: 'Ovruch, Ucrania', d: 'Gran príncipe desde el Kalka (1223–35, de nuevo 1236–39): en 1235 una cabalgada de Hálich y Cherníhiv lo tomó prisionero y desplumó Kyiv hasta los huesos, a las puertas de la invasión mongola.' },
  iziaslav4: { n: 'Iziaslav IV Mstislávich', p: 'Kyiv', d: 'El nombre más opaco de la lista — un Mstislávich incierto que retuvo Kyiv brevemente en 1235–36, en mitad del último forcejeo; los historiadores todavía discuten quién fue.' },
  yaroslav3: { n: 'Yaroslav III Vsevolódovich', p: 'Pereslavl-Zaleski', d: 'Príncipe de Súzdal, padre de Aleksandr (Nevski): llamado a Kyiv en 1236, lo abandonó antes de la tormenta de Batú — y volvió como el gran príncipe dócil de Vladímir de la Horda (1243).' },
  mykhailo2: { n: 'Miguel Vsevolódovich de Cherníhiv', p: 'Cherníhiv', d: 'El último gran príncipe soberano de Kyiv (1238–39, 1241–43): dejó la ciudad antes del asalto de Batú, rechazó los ritos idolátricos de la Horda y murió mártir en 1246 — la Iglesia lo cuenta entre sus santos.' },
  rostyslav3: { n: 'Rostislav III Mstislávich', p: 'Hálich, Ucrania', d: 'Hijo de Mstislav el Audaz de Hálich: gran príncipe por una temporada (1239) en el último forcejeo, luego yerno y capitán del rey Béla IV de Hungría como ban de Macsó — el último que llevó el título de Kyiv en alguna realidad.' }
});

/* Hetmanes de Ucrania — añadidos el 27-10-2026 (fuentes ucranianas) */
Object.assign(window.DATA_ES, {
  dashkevych: { n: 'Ostafii Dashkevych', p: 'Kaniv, Ucrania', d: 'Starosta de Kaniv y Cherkasy que las crónicas cuentan entre los primeros jefes — y el primero al que las fuentes llaman hetman — de los cosacos ucranianos; dos décadas de sus incursiones llegaron a Ochákiv y la costa de Crimea.' },
  vyshnevetsky: { n: 'Dmytro Vyshnevetsky (Baida)', p: 'Isla Mala Jortytsia', d: 'El príncipe starosta que construyó una fortaleza en Mala Jortytsia (1556) — semilla de la Sich de Zaporiyia — y unió a los cosacos del Niz; traicionado en Moldavia, ejecutado en Constantinopla.' },
  kishka: { n: 'Samiilo Kishka', p: 'Sich de Zaporiyia', d: 'Dos veces anciano de los cosacos registrados y héroe de los dúmos: llevado a una galera turca, se liberó a sí mismo y a sus compañeros de remo apoderándose del barco con sus cañones.' },
  shakh: { n: 'Yakiv Shakh', p: 'Sich de Zaporiyia', d: 'Atamán kosh que las fuentes titulan «hetman de la tierra baja»: asaltó por Crimea y Moldavia y cayó en batalla contra los tártaros.' },
  oryshovsky: { n: 'Yan Oryshovsky', p: 'Kaniv, Ucrania', d: 'Anciano de los cosacos registrados que la Corona contaba como hetman: mantuvo el inquieto ejército al servicio y golpeó los uluses de la Horda de Crimea y de Nogai.' },
  kosynsky: { n: 'Kryshtof Kosynsky', p: 'Bila Tserkva, Ucrania', d: 'Centurión de Kaniv y hetman de los registrados: su alzamiento de 1591 tomó el castillo de Bila Tserkva y abrió la era de las revueltas cosacas; derrotado en Piatka, murió de sus heridas (1593).' },
  loboda: { n: 'Hryhorii Loboda', p: 'Sich de Zaporiyia', d: 'Hetman del ejército del Niz que marchó con Nalyvaiko hacia Bielorrusia; murió a manos de rebeldes de su propio campamento en las querellas de 1596.' },
  shaula: { n: 'Matvii Shaula', p: 'Sich de Zaporiyia', d: 'Sucedió a Loboda al frente del alzamiento quebrado de 1596: tras Solonytsia mantuvo unido el ejército disperso tres años más — un final oscuro de un oficio oscuro.' },
  baibuza: { n: 'Tykhin Baibuza', p: 'Sich de Zaporiyia', d: 'Hetman de los zaporiyianos cuyas incursiones de 1597 llegaron a las fortalezas del Danubio — uno de los nombres más opacos de la línea, conservado en una canción popular.' },
  izapovich: { n: 'Hryhorii Izapovych', p: 'Sich de Zaporiyia', d: 'Hetman de los registrados en la gran década de incursiones: en su año las chaiky volvieron a arder en las costas de Crimea y del Otomano.' },
  borodavka: { n: 'Yakiv Borodavka-Neroda', p: 'Sich de Zaporiyia', d: 'Hetman del ejército no registrado en el acuerdo de Rzeszów de 1619; depuesto y muerto en el campamento de Jotín de 1621, cuando Sahaidachny tomó la maza a la guerra.' },
  doroshenko_m: { n: 'Mykhailo Doroshenko', p: 'Cherkasy, Ucrania', d: 'Hetman que devolvió el crédito a los cosacos tras Cecora — honrado por zar y rey por igual — y condujo la famosa campaña de Crimea de 1628, cayendo cerca de Perekop.' },
  chorny: { n: 'Hritsko Chorny', p: 'Sich de Zaporiyia', d: 'Dos veces hetman de los registrados: aplicó las condiciones de Kurukove, y los rebeldes de la Sich le respondieron con la horca (1630).' },
  tryasylo: { n: 'Taras Fedorovych (Triasylo)', p: 'Sich de Zaporiyia', d: 'Atamán kosh y «hetman de la tierra baja» que encabezó el alzamiento de 1630: la victoria en Pereyaslav obligó a la Corona a duplicar el registro — la noche del ataque se recuerda como la noche de Tarás.' },
  sulyma: { n: 'Ivan Sulyma', p: 'Sich de Zaporiyia', d: 'Hetman que asaltó y arrasó la fortaleza polaca de Kodak (1635); traicionado por una recompensa, decapitado en Varsovia — un mártir del que escribió toda Europa.' },
  pavliuk: { n: 'Pavlo Pavliuk', p: 'Sich de Zaporiyia', d: 'Atamán kosh que alzó la revuelta de 1637: quebrado en Kumeiky, torturado hasta la muerte en Varsovia — y el registro, recortado a 6.000.' },
  ostryanyn: { n: 'Yakiv Ostryanyn (Ostrianytsia)', p: 'Lubni, Ucrania', d: 'Lideró la última revuelta antes de Jmelnitski: tras la derrota en Zhovnyn llevó 900 familias a establecerse en Moscovia — donde sus propios colonos lo mataron (1641).' },
  hunya: { n: 'Dmytro Hunia', p: 'Sich de Zaporiyia', d: 'Hetman de la Sich en el año de la represión: sostuvo el Dniéper inferior frente al ejército real y luego negoció la capitulación del ejército — el último hetman libre antes de 1648.' },
  gulak: { n: 'Maksym Hulak', p: 'Sich de Zaporiyia', d: 'El último hetman de la línea antes de Jmelnitski: las notas crónicas de sus incursiones contra los uluses de Crimea son casi todo lo que sobrevive de él.' },
  khmelnytsky_yu: { n: 'Yurii Jmelnitski', p: 'Chyhyryn, Ucrania', d: 'Hijo de Jmelnitski, dos veces hetman (1657–63, 1677–81): a medida que la Ruina se profundizaba cambió de señores polacos, moscovitas y otomanos, y acabó sus días como monje.' },
  vyhovsky: { n: 'Ivan Vyhovsky', p: 'Hadiach, Ucrania', d: 'Hetman 1657–59: su unión de Hadiach devolvió Ucrania a la Mancomunidad como ducado de Rus, y Konotop aniquiló un ejército moscovita — pero los coroneles de Kyiv no le perdonaron el porte de oligarca; asesinado por rivales cosacos (1664).' },
  teterya: { n: 'Pavlo Teteria', p: 'Korsun, Ucrania', d: 'Hetman de la orilla derecha en la órbita polaca (1663–66): huyó a Moldavia cuando amotinaron sus propios coroneles, y allí murió.' },
  briukhovetsky: { n: 'Ivan Briujovetsky', p: 'Hadiach, Ucrania', d: 'El hetman moscovita de la orilla izquierda (1663–68): besó la cruz al zar — y luego, bajo gobernadores e impuestos, se rebeló; la multitud que se alzó con él lo destrozó.' },
  doroshenko_p: { n: 'Petro Doroshenko', p: 'Chyhyryn, Ucrania', d: 'El mejor estadista de la Ruina: hetman de la orilla derecha y luego de ambas, jugó con Varsovia, Moscú e Istanbul por un principado cosaco independiente, sostuvo Chyhyryn contra todo — y acabó en exilio honorífico junto a Moscú.' },
  mnohohrishny: { n: 'Demian Mnohohrishny', p: 'Baturín, Ucrania', d: 'Hetman de la orilla izquierda (1668–72): un general capaz que reconstruyó el orden en torno a Baturín hasta que Moscú, con cargos falsos, lo desterró a Siberia.' },
  khanenko: { n: 'Mykhailo Khanenko', p: 'Umán, Ucrania', d: 'Hetman del partido pro-polaco de la orilla derecha (1669–74): luchó contra Doroshenko con ejércitos polacos — y perdió contra él y contra la Horda.' },
  samus: { n: 'Samiilo Samus', p: 'Korsun, Ucrania', d: 'Hetman del ejército resucitado de la orilla derecha (1693–1704): mantuvo los regimientos restaurados en el campo contra la Horda hasta pasar la maza a Mazepa.' },
  kunytsky: { n: 'Stefan Kunytsky', p: 'Bila Tserkva, Ucrania', d: 'Hetman pro-polaco de la orilla derecha (1683–84) cuya caballería cosaca cabalgó en auxilio de Viena — y que murió pronto en custodia polaca.' },
  mohyla: { n: 'Andrii Mohyla', p: 'Nemyriv, Ucrania', d: 'Príncipe moldavo de la casa Mohyla que sostuvo el hetmanato pro-polaco de la orilla derecha (1684–89) en el pulso con el partido de Doroshenko.' },
  samoilovych: { n: 'Ivan Samoilovich', p: 'Baturín, Ucrania', d: 'Hetman de la orilla izquierda (1672–87): consolidó el Hetmanato y sus escuelas, y cayó cuando fracasó la campaña de Crimea de 1687 — desterrado al Yeniséi.' },
  skoropadsky_i: { n: 'Ivan Skoropadski', p: 'Hlukhiv, Ucrania', d: 'Hetman elegido tras la defección de Mazepa (1708–22): fiel a Pedro I y despojado de poder igualmente — el colegio imperial gobernaba a su lado mientras el hetmanato se vaciaba.' },
  polubotok: { n: 'Pavlo Polubotok', p: 'Hlukhiv, Ucrania', d: 'Hetman interino (1722–24): el hombre más rico del Ejército presentó peticiones por los derechos cosacos y murió en la fortaleza de Petersburgo — germen de la leyenda de su testamento dorado en un banco de Londres.' },
  apostol: { n: 'Danylo Apostol', p: 'Hlukhiv, Ucrania', d: 'Hetman (1727–34), el último electo: reconquistó el cargo tras los años del colegio — y cuando murió, el imperio suspendió de nuevo el hetmanato.' },
  rozumovsky: { n: 'Kyrylo Rozumovsky', p: 'Baturín, Ucrania', d: 'El último hetman (1750–64): hermano del favorito de la emperatriz, restauró los tribunales del Hetmanato y proyectó una universidad para Baturín — y entregó la maza cuando Catalina II suprimió el cargo.' },
  orlyk: { n: 'Pylyp Orlyk — hetman en el exilio', p: 'Bender (en el exilio)', d: 'Elegido en Bender tras Poltava y autor del «Pacto y Constitución» de 1710; levantó ejércitos tártaro-suecos para el regreso de Ucrania y murió en Jassy — la maza sobrevivió al Estado.' },
  zalizniak: { n: 'Maksym Zalizniak', p: 'Umán, Ucrania', d: 'Cosaco de la Sich proclamado hetman durante la Koliyivshchyna de 1768: el alzamiento tomó Umán y sacudió a la Mancomunidad hasta que los regulares rusos lo acabaron; su suerte tras el destierro es leyenda popular.' },
  skoropadsky_p: { n: 'Pavlo Skoropadski — Hetman de Ucrania', p: 'Kyiv', d: 'Bisnieto del hetman Ivan Skoropadski: un general que en abril de 1918, con respaldo alemán, tomó el poder y declaró Ucrania un Estado hetman — ministerios, academias, un ejército — y cayó con la salida de los alemanes en diciembre; murió en la Alemania ocupada.' }
});

/* Reyes de la Rus (Galicia-Volinia) — añadidos el 27-10-2026 */
Object.assign(window.DATA_ES, {
  vasylko: { n: 'Vasylko Romanovych — corregente de Volinia', p: 'Volodímir, Ucrania', d: 'Hermano menor de Danilo y la otra mitad del reino: príncipe de Volinia (1231–69), sostuvo las tierras occidentales frente a yotvingios y polacos — y no acudió a la coronación de su hermano, quedando como el príncipe sin corona de la casa real.' },
  lev_danylovych: { n: 'El rey Lev Danylovych', p: 'Lviv, Ucrania', d: 'Hijo mayor de Danilo: rey de la Rus (hacia 1264–1301) que hizo de Lviv — la ciudad fundada por su padre en su honor — su residencia, mantuvo entero el reino en guerras con Lituania, la Horda y Polonia; un cronista austríaco lo llama en 1278 «el rey Lev de la Rus».' },
  mstyslav_danylovych: { n: 'El rey Mstyslav Danylovych', p: 'Volodímir, Ucrania', d: 'Hijo menor de Danilo: príncipe de Lutsk y luego de Volodímir — la segunda línea coronada del reino en Volinia hasta 1300; sepultado en la catedral de Volodímir.' },
  yurii_1: { n: 'El rey Yurii I Lvovych', p: 'Volodímir, Ucrania', d: 'Hijo de Lev: rey de la Rus (1301–08, según otro cómputo 1315) que reunió todas las tierras de los Romanóvich bajo una corona, fundó la metrópoli de Malorusia (1303) y selló sus cartas «Rex Rusie, princeps Ladimerie» — rey de la Rus, príncipe de Volodímir.' },
  andrii_lev2: { n: 'Los reyes Andrii y Lev II Yuriiovych', p: 'Volodímir, Ucrania', d: 'Hijos de Yurii I — correyes de la Rus (hacia 1308/15–23): en su sello aparece por primera vez la corona real de la Rus; ambos cayeron en 1323, según una tradición en batalla contra la Horda — y la línea real nativa se extinguió.' },
  yurii_2: { n: 'El rey Yurii II Boleslav (Trojdenovych)', p: 'Volodímir, Ucrania', d: 'Un Piasta de Mazovia — nieto de Yurii I por su madre María, rebautizado Yurii: se tituló «príncipe de toda la Malorusia» y «príncipe del reino de la Rus» (1323–40), no logró convivencia con los boyardos; envenenado en Volodímir en 1340 — la puerta por la que entraron Polonia y Lituania.' },
  liubart: { n: 'Dmytro-Liubart — el último portador de la corona de la Rus', p: 'Lutsk, Ucrania', d: 'Príncipe gedimínida y yerno de Yurii II: el ortodoxo Dmytro-Liubart sostuvo Volinia (1340–84) frente a Casimiro el Grande y levantó el castillo de piedra de Lutsk — el último que llevó la pretensión real de la Rus a la era lituana.' }
});

/* Monarcas de Dinamarca, Noruega y Suecia — 27-10-2026 */
Object.assign(window.DATA_ES, {
  dk_knud_i: { n: 'Knud I Hardeknud', p: 'Jelling, Dinamarca', d: 'Fundador semilegendario de la línea de Jelling — el Hardeknud de las crónicas alemanas —, abuelo de Gorm el Viejo.' },
  dk_gorm: { n: 'Gorm el Viejo', p: 'Jelling, Dinamarca', d: 'El primer rey de Dinamarca históricamente seguro: alzó la piedra menor de Jelling por su reina Thyra; la grande la alzó su hijo.' },
  dk_harald_bt: { n: 'Harald I Diente Azul', p: 'Jelling, Dinamarca', d: 'Alzó la gran piedra de Jelling — «el Harald que ganó toda Dinamarca y Noruega e hizo cristianos a los daneses» —, recibió el bautismo (hacia 965) y unió Noruega a su corona.' },
  dk_sveyn_1: { n: 'Svend I Barba Bifurcada', p: 'Roskilde, Dinamarca', d: 'Expulsó a su padre, saqueó Inglaterra una década y murió semanas después de conquistarla — rey de daneses, ingleses y parte de los noruegos.' },
  dk_harald_ii: { n: 'Harald II de Dinamarca', p: 'Roskilde, Dinamarca', d: 'Sostuvo Dinamarca mientras su hermano Canuto tomaba Inglaterra — murió al cuarto año.' },
  dk_knud_iii: { n: 'Canuto III Hardeknud', p: 'Roskilde, Dinamarca', d: 'Hijo de Canuto el Grande: último rey del núcleo danés del imperio del Mar del Norte — murió borracho en una boda en Lambeth (1042).' },
  dk_sveyn_ii: { n: 'Svend II Estridsen', p: 'Roskilde, Dinamarca', d: 'Sobrino de Canuto y fundador de una dinastía de 500 años: reconstruyó el reino y engendró quince hijos — cinco reinarían.' },
  dk_harald_hen: { n: 'Harald III Hen', p: 'Roskilde, Dinamarca', d: 'La piedra de afilar: un rey suave que suavizó las leyes, del que las sagas se burlan como «mente de campesino».' },
  dk_knud_iv: { n: 'Canuto IV el Santo', p: 'Odense, Dinamarca', d: 'Exigió diezmos y ley regia — asesinado por rebeldes en la iglesia de San Albano de Odense (1086); el santo real de Dinamarca.' },
  dk_olaf_hunger: { n: 'Olaf I el Hambriento', p: 'Roskilde, Dinamarca', d: 'Años de hambre y un reino quebrado bajo el hermano que desplazó al santo.' },
  dk_erik_ejegod: { n: 'Erik I Ejegod', p: 'Roskilde, Dinamarca', d: '«Siempre bueno»: cabalgó por Rusia hacia Jerusalén como el primer rey peregrino nórdico — murió en Chipre (1103).' },
  dk_niels: { n: 'Niels', p: 'Roskilde, Dinamarca', d: 'Cuatro décadas tranquilas acabaron cuando su hijo Magnus mató a Canuto Lavard — la guerra civil devoró a la dinastía.' },
  dk_erik_emune: { n: 'Erik II Emune', p: 'Roskilde, Dinamarca', d: 'El Memorable: venció la matanza de Fotevik — y fue asesinado en una asamblea por su propio copero.' },
  dk_erik_lam: { n: 'Erik III el Cordero', p: 'Roskilde, Dinamarca', d: 'El Cordero: el único rey danés medieval que abdicó — dejando el reino a los reyes rivales de la guerra civil.' },
  dk_knud_sven: { n: 'Canuto V y Svend III — reyes rivales', p: 'Roskilde, Dinamarca', d: 'Los dos tronos de la gran guerra civil: Canuto V Magnussen y Svend III Grathe desgarraron el reino hasta que Valdemar lo acabó en la matanza de Roskilde (1157).' },
  dk_valdemar_i: { n: 'Valdemar I el Grande', p: 'Roskilde, Dinamarca', d: 'Salió de la matanza de Roskilde a reunificar Dinamarca y tomó Rugia con el obispo Absalón — empezó la edad dorada valdemariana.' },
  dk_knud_vi: { n: 'Canuto VI', p: 'Roskilde, Dinamarca', d: 'Dinamarca del Elba al Báltico — «rey de los daneses y los vendos»: el orgulloso centro de la edad dorada.' },
  dk_valdemar_ii: { n: 'Valdemar II el Victorioso', p: 'Roskilde, Dinamarca', d: 'Conquistó la costa báltica, vio caer el Danebrog del cielo en Lyndanisse (1219) — y perdió casi todo en Bornhöved (1227).' },
  dk_erik_iv: { n: 'Erik IV Plovpenning', p: 'Roskilde, Dinamarca', d: 'El penique de arado: tasó cada arado para una cruzada — decapitado por los hombres de su hermano Abel en el Schlei (1250).' },
  dk_abel: { n: 'Abel', p: 'Schleswig', d: 'Mató a su hermano por la corona, reinó diecinueve meses, murió luchando contra los frisones — «Abel por asesinato, Abel por nombre», dice el proverbio.' },
  dk_kristoffer_i: { n: 'Kristoffer I', p: 'Roskilde, Dinamarca', d: 'Exilió al arzobispo Jakob Erlandsen y luchó contra la Iglesia — murió (1259), susurraban, «envenenado por el vino de la comunión».' },
  dk_erik_v: { n: 'Erik V Klipping', p: 'Roskilde, Dinamarca', d: 'Asesinado en el granero de Finderup por nobles enmascarados (1286) — el crimen sin resolver que exilió a los «señores proscritos» de Dinamarca.' },
  dk_erik_vi: { n: 'Erik VI Menved', p: 'Roskilde, Dinamarca', d: 'Soñó un imperio báltico con mercenarios alemanes — y empeñó el reino para pagarlo.' },
  dk_kristoffer_ii: { n: 'Kristoffer II', p: 'Roskilde, Dinamarca', d: 'Firmó la corona carta a carta a favor de los nobles — depuesto dos veces; tras él el trono quedó vacío ocho años.' },
  dk_valdemar_iii: { n: 'Valdemar III', p: 'Roskilde, Dinamarca', d: 'Un rey niño de la casa ducal de Schleswig, peón de los holsteinianos en el interregno.' },
  dk_valdemar_iv: { n: 'Valdemar IV Atterdag', p: 'Vordingborg, Dinamarca', d: '«Habrá otro día»: reconstruyó Dinamarca desde la nada, rescató cada tierra empeñada — murió en campaña por un imperio báltico (1375).' },
  dk_olaf_ii: { n: 'Olaf II Håkonsen', p: 'Roskilde, Dinamarca', d: 'El pequeño hijo de Margarita: rey de Dinamarca a los cinco y de Noruega a los diez — muerto a los dieciséis, el último de los Bjälbo.' },
  dk_erik_pomerania: { n: 'Erik VII de Pomerania', p: 'Copenhague', d: 'Heredero de Margarita en los tres tronos del norte — el rey de la Unión de Kalmar que los perdió por rebeliones y murió caudillo pirata en Pomerania (1459).' },
  dk_kristoffer_iii: { n: 'Kristoffer III de Baviera', p: 'Copenhague', d: 'El rey de la paz: el sueco Karl Knutsson lo aceptó por la unión — murió sin hijos (1448) y llegaron los Oldemburgo.' },
  dk_christian_i: { n: 'Cristián I Oldemburgo', p: 'Copenhague', d: 'Pagó la corona en obligaciones de Schleswig-Holstein — una hipoteca que Dinamarca sirvió 360 años; fundó la universidad de Copenhague (1479).' },
  dk_hans: { n: 'El rey Juan', p: 'Copenhague', d: 'Unión solo en el papel: los suecos lo vencieron en Brunkeberg y los ditmarsios en Hemmingstedt — Dinamarca misma prosperó.' },
  dk_christian_ii: { n: 'Cristián II el Tirano', p: 'Copenhague', d: 'El baño de sangre de Estocolmo (1520) le costó Suecia; sus propias reformas danesas, Dinamarca — 27 años preso en Sønderborg.' },
  dk_frederik_i: { n: 'Federico I', p: 'Copenhague', d: 'Duque holsteiniano elegido tras el tirano: la Reforma danesa comenzó bajo su protección mientras maduraba la guerra del Conde.' },
  dk_christian_iii: { n: 'Cristián III', p: 'Copenhague', d: 'Ganó la guerra del Conde e hizo de Dinamarca un país oficialmente luterano — la iglesia estatal que aún habla danés es su obra.' },
  dk_frederik_ii: { n: 'Federico II', p: 'Copenhague', d: 'Construyó Kronborg — el Elsinor del Hamlet de Shakespeare — y peleó la agotadora Guerra de los Siete Años nórdica hasta el empate.' },
  dk_christian_iv: { n: 'Cristián IV', p: 'Copenhague', d: 'El rey constructor: sesenta años, las torres y gremios de Copenhague, la guerra de Kalmar — y dos derrotas ruinosas dentro de la Guerra de los Treinta Años.' },
  dk_frederik_iii: { n: 'Federico III', p: 'Copenhague', d: 'El afortunado: los burgueses de Copenhague sostuvieron los muros contra Carlos X Gustavo (1658–60) — y lo hicieron rey absoluto hereditario.' },
  dk_christian_v: { n: 'Cristián V', p: 'Copenhague', d: 'Reinó según el Kongeloven — la única carta absolutista escrita de Europa — y perdió de nuevo la guerra de Escania ante Suecia.' },
  dk_frederik_iv: { n: 'Federico IV', p: 'Copenhague', d: 'Golpeó dos veces al imperio sueco que se derrumbaba, liberó a los siervos de Zelanda — y vivió en bigamia mientras rugía la Gran Guerra del Norte.' },
  dk_christian_vi: { n: 'Cristián VI', p: 'Copenhague', d: 'El constructor piadoso: Christiansborg creció mientras cerraban los teatros y se vigilaban los domingos.' },
  dk_frederik_v: { n: 'Federico V', p: 'Copenhague', d: 'Rey apacible bajo el ministerio ilustrado de Bernstorff — una corte de arte y aguardiente, muerto a los 42.' },
  dk_christian_vii: { n: 'Cristián VII', p: 'Copenhague', d: 'El rey loco: el médico Struensee gobernó con la reina Carolina Matilde hasta que el golpe de 1772 se llevó a ambos.' },
  dk_frederik_vi: { n: 'Federico VI', p: 'Copenhague', d: 'Regente en los bombardeos ingleses de Copenhague (1801, 1807) — perdió Noruega en Kiel (1814), reformó el Estado después.' },
  dk_christian_viii: { n: 'Cristián VIII', p: 'Copenhague', d: 'Rey de cinco meses de Noruega en 1814 — murió en 1848, semanas antes de la constitución que había preparado.' },
  dk_frederik_vii: { n: 'Federico VII', p: 'Copenhague', d: 'Firmó la constitución libre de Dinamarca (junio 1849), acabando el absolutismo — el último rey de la línea principal Oldemburgo.' },
  dk_christian_ix: { n: 'Cristián IX Glücksburgo', p: 'Copenhague', d: 'Perdió Schleswig-Holstein en 1864 — pero como «suegro de Europa» sentó a su familia en tronos de Londres a Atenas.' },
  dk_frederik_viii: { n: 'Federico VIII', p: 'Copenhague', d: 'El heredero paciente, por fin rey — murió de repente en Hamburgo, volviendo de Niza (1912).' },
  dk_christian_x: { n: 'Cristián X', p: 'Copenhague', d: 'Cabalgó solo por la Copenhague ocupada en 1940 — icono de la ocupación; internado por los alemanes tras la crisis de 1943.' },
  dk_frederik_ix: { n: 'Federico IX', p: 'Copenhague', d: 'El rey marino de la radio y la televisión — cambió la ley sucesoria para que reinara su hija.' },
  dk_margrethe_ii: { n: 'Margarita II', p: 'Copenhague', d: 'La reina con el reinado más largo de Europa: arqueóloga, escenógrafa, modernizadora de la corona — abdicó a los 83 (enero 2024).' },
  dk_frederik_x: { n: 'Federico X', p: 'Copenhague', d: 'Proclamado el 14 de enero de 2024 — el primer rey danés en tres siglos que sucede por abdicación.' },
  no_harald_i: { n: 'Harald I la Bella Cabellera', p: 'Avaldsnes, Noruega', d: 'Según las sagas, unificó Noruega tras Hafrsfjord (872) y reinó hasta los ochenta — fundador de la línea real noruega.' },
  no_eirik_blodoks: { n: 'Eirik I Hacha de Sangre', p: 'Avaldsnes, Noruega', d: 'Expulsó a sus hermanos uno a uno, perdió Noruega ante Haakon en dos años — murió luego rey de York en Inglaterra.' },
  no_hakon_gode: { n: 'Haakon I el Bueno', p: 'Avaldsnes, Noruega', d: 'Hijastro de Athelstan de Inglaterra: trajo el cristianismo y las leyes del Frostating — cayó ante los hijos de Eirik en Fitjar.' },
  no_harald_grafell: { n: 'Harald II Manto Gris', p: 'Lade, Noruega', d: 'Reinó junto a su madre Gunnhild, quemó al jarl de Lade en su salón — y fue entregado a los daneses (970).' },
  no_olav_tryggvason: { n: 'Olav I Tryggvason', p: 'Nidaros (Trondheim), Noruega', d: 'El invasor bautizado: cristianizó Noruega a fuego y espada — murió cuando su Serpiente Larga fue tomada en Svolder (1000).' },
  no_olav_haraldsson: { n: 'Olav II el Santo (San Olav)', p: 'Nidaros (Trondheim), Noruega', d: 'El ex vikingo que impuso la ley cristiana: cayó en Stiklestad (1030) — y se volvió el eterno rey santo de Noruega.' },
  no_magnus_gode: { n: 'Magnus I el Bueno', p: 'Nidaros (Trondheim), Noruega', d: 'Hijo de San Olav, elegido por Noruega y Dinamarca — abolió las leyes de venganza y murió joven (1047).' },
  no_harald_hardrada: { n: 'Harald III Hardrada', p: 'Nidaros (Trondheim), Noruega', d: 'Capitán varego de Bizancio hecho el último rey vikingo — cayó en Stamford Bridge (1066), tres semanas antes que Hastings.' },
  no_magnus_ii: { n: 'Magnus II Haraldsson', p: 'Nidaros (Trondheim), Noruega', d: 'Correy de su hermano Olav Kyrre — muerto a los diecisiete, padre de la línea Descalza.' },
  no_olav_kyrre: { n: 'Olav III el Tranquilo', p: 'Nidaros (Trondheim), Noruega', d: 'El Tranquilo: veinticinco años de paz — iniciada la catedral de Nidaros, ordenada la Iglesia.' },
  no_magnus_barefoot: { n: 'Magnus III Descalzo', p: 'Bergen, Noruega', d: 'Tomó Orcadas, Man y las Hébridas y vestía como sus súbditos occidentales — muerto en una emboscada en Ulster (1103).' },
  no_sigurd_jorsalfare: { n: 'Sigurd I el Cruzado', p: 'Bergen, Noruega', d: 'El caminante de Jerusalén: primer rey europeo que llegó en persona a Tierra Santa (1110) — héroe de saga, luego loco, siempre magnífico.' },
  no_eystein_i: { n: 'Øystein I Magnusson', p: 'Nidaros (Trondheim), Noruega', d: 'El correy del interior: caminos, villas pesqueras y la primera administración real de verdad.' },
  no_olav_magnusson: { n: 'Olav Magnusson', p: 'Nidaros (Trondheim), Noruega', d: 'El correy niño, coronado a los cuatro — una nota al pie entre sus hermanos, muerto a los trece.' },
  no_magnus_blind: { n: 'Magnus IV el Ciego', p: 'Bergen, Noruega', d: 'Cegado y mutilado a los quince — primera crueldad de la guerra civil; restaurado brevemente, ahogado en 1139.' },
  no_harald_gille: { n: 'Harald IV Gille', p: 'Bergen, Noruega', d: 'Pretendiente irlandés que probó sangre real por la ordalía del hierro al rojo — asesinado de noche en Bergen (1136).' },
  no_sigurd_munn: { n: 'Sigurd II Munn', p: 'Tønsberg, Noruega', d: 'Correy niño de la línea Gille — acribillado desde un escondite por los hombres de Inge tras el banquete de Tønsberg (1155).' },
  no_inge_krokrygg: { n: 'Inge I el Corcovado', p: 'Bergen, Noruega', d: 'El rey jorobado de la ley que sostuvo al partido del orden en la primera década de guerra civil — cayó en Oslo (1161).' },
  no_eystein_ii: { n: 'Øystein II Haraldsson', p: 'Bergen, Noruega', d: 'Tercer hermano Gille: saqueó Suecia para pagar a su hueste — muerto en emboscada en Rissa (1157).' },
  no_hakon_bredsuld: { n: 'Haakon II Hombros Anchos', p: 'Nidaros (Trondheim), Noruega', d: 'El rey niño del partido de la ley — asesinado en Sekken por la flota de Erling Skakke (1162).' },
  no_magnus_erlingsson: { n: 'Magnus V Erlingsson', p: 'Bergen, Noruega', d: 'El niño ungido por la Iglesia del partido Skakke — el primer rey coronado de Noruega, caído en Nordnes ante Sverre (1184).' },
  no_sverre: { n: 'Sverre Sigurdsson', p: 'Bergen, Noruega', d: 'Un sacerdote feroés que se dijo hijo de rey — y ganó: veinte años de guerra de guerrillas lo hicieron el más dinámico soberano medieval de Noruega.' },
  no_hakon_iii: { n: 'Haakon III Sverresson', p: 'Bergen, Noruega', d: 'Se reconcilió con la Iglesia que su padre rompió — muerto en dos años, veneno susurran.' },
  no_guttorm: { n: 'Guttorm Sigurdsson', p: 'Nidaros (Trondheim), Noruega', d: 'El rey de cuatro meses: un niño de diez años entre dos asesinatos.' },
  no_inge_ii: { n: 'Inge II Bårdsson', p: 'Nidaros (Trondheim), Noruega', d: 'Unió a bagler y birkebeiner en un solo reino — la primera paz firme de Noruega en cuarenta años.' },
  no_hakon_iv: { n: 'Haakon IV el Viejo', p: 'Bergen, Noruega', d: 'De huérfano birkebeiner al cénit de Noruega: Islandia y Groenlandia se unieron a la corona y las cortes de Europa cortejaron.' },
  no_magnus_vi: { n: 'Magnus VI el Legislador', p: 'Bergen, Noruega', d: 'Sustituyó las leyes regionales por un código nacional (1274) — el primer derecho común de Noruega.' },
  no_erik_ii: { n: 'Eirik II el Odiador de Sacerdotes', p: 'Bergen, Noruega', d: 'Coronado a los ocho, casado con la escocesa Margarita a los nueve — aquí empezó el largo declive del reino.' },
  no_hakon_v: { n: 'Haakon V', p: 'Oslo, Noruega', d: 'Llevó la capital a Oslo y construyó Akershus — murió dejando una hija de tres años y una unión por venir.' },
  no_haakon_vi: { n: 'Haakon VI Magnusson', p: 'Bergen, Noruega', d: 'Rey de Noruega 1355–80 y correy de Suecia por matrimonio — la generación de la Peste Negra, padre de Olav IV.' },
  no_haakon_vii: { n: 'Haakon VII', p: 'Oslo, Noruega', d: 'El príncipe danés Carl, que rehusó dos veces la corona hasta que Noruega votó (1905) — se mantuvo en el puesto también en el exilio de 1940.' },
  no_olav_v: { n: 'Olav V', p: 'Oslo, Noruega', d: 'El rey del pueblo: esquiaba la carrera Birkebeiner y pagaba su tranvía — ancla de la generación de la ocupación.' },
  no_harald_v: { n: 'Harald V', p: 'Oslo, Noruega', d: 'Rey regatista y campeón olímpico desde 1991 — habló de tolerancia cuando Noruega sangró en 2011; murió en agosto de 2026, llorado por todo el Norte.' },
  no_haakon_viii: { n: 'Haakon VIII', p: 'Oslo, Noruega', d: 'Rey desde agosto de 2026 — continuidad de la monarquía moderna tras treinta y cinco años del querido reinado paterno.' },
  se_erik_segersall: { n: 'Erik el Victorioso', p: 'Upsala, Suecia', d: 'Venció al ejército danés en Fyrisvellir — el primer rey sueco que la historia conoce por su nombre.' },
  se_olof_skotkonung: { n: 'Olof Skötkonung', p: 'Upsala, Suecia', d: 'Primer rey cristiano de los suiones: acuñó las primeras monedas suecas en Sigtuna, bautizado en Husaby.' },
  se_anund_jacob: { n: 'Anund Jacob', p: 'Sigtuna, Suecia', d: 'Aliado de San Olav contra Canuto — veintiocho años de paz mientras esperaba su hermano Emund.' },
  se_emund_gamle: { n: 'Emund el Viejo', p: 'Sigtuna, Suecia', d: 'Último de la vieja línea: arregló la frontera con Dinamarca y murió sin hijo — empezó la era Stenkil.' },
  se_stenkil: { n: 'Stenkil', p: 'Skara, Suecia', d: 'Conde de los godos occidentales casado en la vieja línea: protector del joven obispado de Skara.' },
  se_erik_eriksonerna: { n: 'Erik Stenkilsson y Erik el Pagano — reyes rivales', p: 'Skara, Suecia', d: 'Dos Eriks rivales — el heredero Stenkil y el pretendiente pagano — pelearon por el trono y ambos cayeron el mismo año.' },
  se_halsten: { n: 'Halsten Stenkilsson', p: 'Skara, Suecia', d: 'Un rey pacífico entre dos revueltas paganas — luego correy junto a su hermano Inge.' },
  se_hakan_rode: { n: 'Håkan el Rojo', p: 'Sigtuna, Suecia', d: 'Un interludio oscuro — tal vez el rey del backlash pagano — entre los hermanos Stenkil.' },
  se_inge_stare: { n: 'Inge el Viejo', p: 'Skara, Suecia', d: 'Expulsado por negarse al sacrificio de Upsala, volvió para ganar Suecia definitivamente para el cristianismo.' },
  se_blot_sven: { n: 'Blot-Sven', p: 'Upsala, Suecia', d: 'Elevado al trono por prometer los viejos sacrificios — muerto en tres años a manos de Inge.' },
  se_filip: { n: 'Filip Halstensson', p: 'Skara, Suecia', d: 'Correy junto a Inge el Joven — doce años apacibles de los sobrinos Stenkil.' },
  se_inge_yngre: { n: 'Inge el Joven', p: 'Skara, Suecia', d: 'El último Stenkil de su línea — murió en el año del hambre 1125.' },
  se_ragnvald: { n: 'Ragnvald Knaphövde', p: 'Skara, Suecia', d: '«Cabeza de vasija»: cabalgó al thing de los gautas sin tomar rehenes, como exigía la costumbre — matado en el camino.' },
  se_magnus_stark: { n: 'Magnus el Fuerte', p: 'Skara, Suecia', d: 'Nieto nacido en Dinamarca de Sigurd el Cruzado — primer pretendiente sueco con sangre real noruega; cayó en Fotevik (1134).' },
  se_sverker_aldre: { n: 'Sverker I el Viejo', p: 'Linköping, Suecia', d: 'Primero de la línea Sverker de Östergötland: fundó la abadía de Alvastra — asesinado por su propio criado camino de misa (1156).' },
  se_erik_helige: { n: 'Erik IX el Santo', p: 'Upsala, Suecia', d: 'Lideró la cruzada a Finlandia con el obispo Enrique — asesinado en la misa de la Ascensión de Upsala; santo patrón de Suecia.' },
  se_magnus_henriksson: { n: 'Magnus Henriksson', p: 'Skara, Suecia', d: 'Pretendiente respaldado por Dinamarca que tomó la corona tras el asesinato de Erik — muerto en un año.' },
  se_karl_sverkersson: { n: 'Carlos VII Sverkersson', p: 'Visingsö, Suecia', d: 'Primero titulado «rey de los suiones y los gautas» — cayó en la disputa de Visingsö con los hijos de Erik (1167).' },
  se_knut_eriksson: { n: 'Canuto I Eriksson', p: 'Upsala, Suecia', d: 'Construyó la dinastía Erik: tomó Visingsö, acuñó monedas, dejó dos hijos que Suecia coronaría.' },
  se_sverker_yngre: { n: 'Sverker II el Joven', p: 'Visingsö, Suecia', d: 'Perdió corona y clan en Lena (1208) ante los hijos de Erik — cayó en Gestilren dos años después.' },
  se_erik_knutsson: { n: 'Erik X Knutsson', p: 'Upsala, Suecia', d: 'Vengó a su padre en Lena y fue el primer rey coronado de Suecia (1210).' },
  se_johan_sverkersson: { n: 'Juan I Sverkersson', p: 'Upsala, Suecia', d: 'Último de la línea Sverker: dirigió a los veinte una cruzada condenada a Estonia, muerto a los veintiuno.' },
  se_erik_xi: { n: 'Erik XI el Ceceo y Cojo', p: 'Upsala, Suecia', d: 'Dos veces coronado, dos veces exiliado — el tranquilo último rey de la línea Erik.' },
  se_knut_lange: { n: 'Canuto II el Largo', p: 'Upsala, Suecia', d: 'Un usurpador folkung — cinco años de gobierno firme entre los reinados Erik.' },
  se_valdemar_birgersson: { n: 'Valdemar Birgersson', p: 'Estocolmo', d: 'El rey niño del jarl Birger: Estocolmo fundada (1252), cruzada a Tavastland — depuesto por su propio hermano Magnus.' },
  se_magnus_ladulas: { n: 'Magnus III Ladulås', p: 'Estocolmo', d: '«Candado del granero»: quitó la corona a su hermano y dio a los nobles exención fiscal por servicio de caballería (Alsnö, 1280).' },
  se_birger: { n: 'Birger Magnusson', p: 'Estocolmo', d: 'La corona folkung ahogándose en querellas familiares — encarceló a sus hermanos, fue depuesto por ellos, murió en el exilio.' },
  se_magnus_ericsson: { n: 'Magnus IV Eriksson', p: 'Estocolmo', d: 'Heredó Noruega a los tres y Suecia a los diecisiete — dos coronas, la Peste Negra en medio, y ambas perdidas.' },
  se_albrekt: { n: 'Alberto de Mecklemburgo', p: 'Estocolmo', d: 'El rey alemán de los nobles — capturado por Margarita en Falköping (1389) cuando sus alemanes se volvieron demasiado codiciosos.' },
  se_karl_knutsson: { n: 'Karl Knutsson Bonde', p: 'Estocolmo', d: 'El rey separatista de Suecia en las grietas de la unión — tres reinados, la corona de Noruega por un año, y el futuro Bonde comenzado.' },
  se_gustav_vasa: { n: 'Gustavo I Vasa', p: 'Estocolmo', d: 'El jinete que sobrevivió al baño de sangre: elegido rey al caer la unión — fundó el Estado, la iglesia y la dinastía de Suecia.' },
  se_eric_xiv: { n: 'Erik XIV', p: 'Estocolmo', d: 'Empujó a Suecia al borde del imperio en Estonia — luego asesinó a los nobles Sture en Upsala (1568); depuesto, envenenado en prisión (1577).' },
  se_johan_iii: { n: 'Juan III', p: 'Estocolmo', d: 'Casó con una Jagellón y tiró de Suecia hacia los ritos romanos — la guerra litúrgica que heredó su hijo.' },
  se_sigismund: { n: 'Segismundo', p: 'Estocolmo', d: 'Rey católico de la Suecia protestante: depuesto por su tío en Stångebro (1598) — conservó Polonia, donde su línea luchó un siglo contra Suecia.' },
  se_karl_ix: { n: 'Carlos IX', p: 'Upsala, Suecia', d: 'El tío regente que hizo la regencia permanente: aplastó a Segismundo, coronado por fin (1607), entregó el imperio a su hijo.' },
  se_kristina: { n: 'Cristina', p: 'Estocolmo', d: 'La reina filósofa de la paz de Westfalia — abdicó, se convirtió a Roma y murió en Roma entre sus libros.' },
  se_karl_x_gustav: { n: 'Carlos X Gustavo', p: 'Estocolmo', d: 'Marchó un ejército sobre los Beltes helados hasta Copenhague (1658) — Suecia en su máxima anchura, Dinamarca partida por tratado.' },
  se_karl_xi: { n: 'Carlos XI', p: 'Estocolmo', d: 'El reductor: devolvió a la corona las tierras de la nobleza — el ejército carolino y el Estado absoluto fueron su obra.' },
  se_karl_xii: { n: 'Carlos XII', p: 'Estocolmo', d: 'El último carolino: Narva a los dieciocho, Poltava a los veintiséis, una bala en Fredriksten (1718) — el imperio murió con él.' },
  se_ulrika_eleonora: { n: 'Ulrica Eleonora', p: 'Estocolmo', d: 'Elegida reina solo al aceptar la nueva constitución noble — abdicó en un año en favor de su esposo hessiano.' },
  se_fredrik_i: { n: 'Federico I de Hesse', p: 'Estocolmo', d: 'El rey figurino de la Era de la Libertad — Sombreros y Gorros gobernaban mientras él cazaba.' },
  se_adolf_fredrik: { n: 'Adolfo Federico', p: 'Estocolmo', d: 'El rey obispo de Lübeck instalado por los Sombreros — murió, dice la leyenda, de un festín de postres.' },
  se_gustav_iii: { n: 'Gustavo III', p: 'Estocolmo', d: 'El rey teatro: su golpe de 1772 restauró el poder real — reformó, pleiteó y fue tiroteado en un baile de máscaras; Verdi hizo una ópera.' },
  se_gustav_iv_adolf: { n: 'Gustavo IV Adolfo', p: 'Estocolmo', d: 'El idealista obstinado: perdió Finlandia ante Rusia (1809) y su trono en el mismo golpe del año.' },
  se_karl_xiii: { n: 'Carlos XIII', p: 'Estocolmo', d: 'El viejo rey sin hijos que adoptó a un mariscal francés — la línea Bernadotte reina aún.' },
  se_karl_xiv_johan: { n: 'Carlos XIV Juan (Bernadotte)', p: 'Estocolmo', d: 'Mariscal napoleónico — príncipe heredero — rey: cambió de bando, tomó Noruega en 1814, fundó la dinastía.' },
  se_oskar_i: { n: 'Óscar I', p: 'Estocolmo', d: 'El Bernadotte blando: liberalizó la unión, construyó el primer ferrocarril sueco, se mantuvo fuera de la guerra de Crimea.' },
  se_karl_xv: { n: 'Carlos XV', p: 'Estocolmo', d: 'Rey poeta y pintor, rey del escandinavismo — la unión con Noruega se aflojó pero se sostuvo.' },
  se_oskar_ii: { n: 'Óscar II', p: 'Estocolmo', d: 'El último maestro de la unión: en 1905 dejó ir a Noruega sin un disparo — el monarca constitucional modelo de Europa.' },
  se_gustaf_v: { n: 'Gustavo V', p: 'Estocolmo', d: 'Cinco décadas: rey tenista, neutral en dos guerras mundiales, cortesano de una Suecia modernizándose.' },
  se_gustaf_vi_adolf: { n: 'Gustavo VI Adolfo', p: 'Estocolmo', d: 'El rey arqueólogo: excavaciones etruscas y propiedad constitucional a través de tres décadas de reformas.' },
  se_carl_xvi_gustaf: { n: 'Carlos XVI Gustavo', p: 'Estocolmo', d: 'Rey desde 1973 — jefe de Estado ceremonial bajo la constitución de 1974, la moderna figura de abuelo de los Bernadotte.' }
});

