  us_johnson: { n: 'Andrew Johnson', p: 'Greeneville, Tennessee', d: 'El sastre que llegó a presidente por un asesinato en el teatro: acusado por obstruir la Reconstrucción — absuelto por un voto.' },
  us_grant: { n: 'Ulysses S. Grant', p: 'Galena, Illinois', d: 'El general que ganó la Guerra Civil: aplastó al primer Klan, presidió escándalos — y escribió unas memorias maestras en su lecho de muerte.' },
