  us_bharrison: { n: 'Benjamin Harrison', p: 'Indianápolis, Indiana', d: 'Nieto de un presidente: seis nuevos estados, la ley Sherman antimonopolio — y derrotado por Cleveland en la revancha.' },
  us_mckinley: { n: 'William McKinley', p: 'Canton, Ohio', d: 'El guardián del patrón oro: ganó la guerra hispano-estadounidense y un imperio — asesinado por un anarquista en Búfalo (1901).' },
