  us_wilson: { n: 'Woodrow Wilson', p: 'Princeton, Nueva Jersey', d: 'El presidente profesor: la Reserva Federal, el impuesto sobre la renta, el voto femenino — y la Liga de Naciones que el Senado rechazó.' },
