  us_kennedy: { n: 'John F. Kennedy', p: 'Hyannis Port, Massachusetts', d: 'El joven presidente televisivo: la Bahía de Cochinos, la crisis de los misiles aguantada — y la promesa cortada en Dallas (1963).' },
