  us_carter: { n: 'Jimmy Carter', p: 'Plains, Georgia', d: 'El ingeniero de Plains: la paz de Camp David, los derechos humanos, la «malaise» — y luego cuatro décadas del mejor expresidente jamás vivido.' },
  us_reagan: { n: 'Ronald Reagan', p: 'Dixon, Illinois', d: 'El comunicador: «señor Gorbachov, derribe este muro» — recortes fiscales, el final de la Guerra Fría e Irán-Contra.' },
