/* Reyes y gobernantes de Francia — 27-10-2026 */
Object.assign(window.DATA_ES, {
  fr_childeric_i: { n: 'Childerico I de los francos', p: 'Soissons, Francia', d: 'El primer rey franco históricamente verificado — su anillo-sello hallado en la tumba de Tournai en 1653; padre de Clodoveo.' },
  fr_clovis: { n: 'Clodoveo I', p: 'Soissons, Francia', d: 'Unió las tribus francas y recibió el bautismo católico en Reims (hacia 496) — el comienzo de Francia y de sus reyes coronados por la Iglesia.' },
  fr_sons_clovis: { n: 'Los hijos de Clodoveo — el reino dividido', p: 'Soissons, Francia', d: 'Childeberto (París), Clodomiro (Orleans), Teodorico (Reims) y Clotario (Soissons) repartieron el reino y asesinaron herederos ajenos — hasta que Clotario lo reunió todo (558).' },
  fr_grandsons_clovis: { n: 'Los nietos de Clodoveo — tres reinos, dos reinas', p: 'Soissons, Francia', d: 'Cariberto, Guntramno, Sigeberto y Chilperico volvieron a repartir Francia: Bruniquilda de Austrasia y Fredegunda de Neustria libraron cuarenta años de regicidios y guerra civil.' },
  fr_chlothar_ii: { n: 'Clotario II el Grande', p: 'Soissons, Francia', d: 'Reunió toda Francia (613) haciendo despedazar a la vieja reina Bruniquelda — y su Edicto de París (614) recortó por primera vez el poder de la corona.' },
  fr_dagobert_i: { n: 'Dagoberto I', p: 'Soissons, Francia', d: 'El último merovingio fuerte: llevó el tesoro real a Saint-Denis — y acabó en la canción infantil como «bon roi Dagobert», con el calzón al revés.' },
  fr_rois_faineants: { n: 'Los rois fainéants — reyes holgazanes', p: 'Soissons, Francia', d: 'De Clodoveo II a Childerico III, los reyes sombra de melena larga firmaban lo que les ponían los mayordomos de palacio; Carlos Martel gobernaba, y su hijo cortó la última melena en 751.' },
  fr_pepin: { n: 'Pipino el Breve', p: 'Soissons, Francia', d: 'El mayordomo que se hizo rey con bendición papal (751) — coronado de nuevo por el Papa (754) y regaló a Roma las tierras que serían los Estados Pontificios.' },
  fr_louis_pious: { n: 'Ludovico Pío', p: 'Aquisgrán', d: 'Heredero de Carlomagno y emperador de Occidente: penitente, cantor, jurado a la reforma — las guerras civiles de sus hijos disolvieron el imperio que custodiaba.' },
  fr_charles_bald: { n: 'Carlos II el Calvo', p: 'París', d: 'Francia Occidental tras el reparto de Verdún (843): peleó con sus hermanos por una corona de fragmentos — coronado emperador en Roma (875), murió cruzando los Alpes.' },
  fr_louis_stammerer: { n: 'Luis II el Tartamudo', p: 'París', d: 'Dos veces coronado y dos veces viudo, reinó veinte meses — dos hijos pequeños heredaron un reino que se debilitaba.' },
  fr_louis_iii_carloman: { n: 'Luis III y Carlomán II', p: 'París', d: 'Dos reyes niños contra los vikingos: Luis ganó la batalla cantada de Saucourt (881) — ambos muertos adolescentes en cinco años.' },
  fr_charles_fat: { n: 'Carlos III el Gordo', p: 'París', d: 'Reunió un instante el imperio de Carlomagno, compró el asedio vikingo de París (886) — y fue depuesto por débil por su propio sobrino.' },
  fr_odo: { n: 'Eudes de París — el primer no carolingio', p: 'París', d: 'El conde de París que defendió la ciudad del asedio vikingo (885–86): los nobles lo coronaron — primer sabor de la corona para la línea Robertina.' },
  fr_charles_simple: { n: 'Carlos III el Simple', p: 'Laon, Francia', d: 'Coronado a los diecinueve frente a Eudes: cedió Normandía al caudillo vikingo Rollón (911) — luego encarcelado por sus propios barones hasta la muerte.' },
  fr_robert_i: { n: 'Roberto I', p: 'París', d: 'Hermano de Eudes, elegido rey contra Carlos el Simple — muerto en batalla contra los mismos invasores contra los que luchó toda su vida (Soissons, 923).' },
  fr_raoul: { n: 'Raúl de Borgoña', p: 'París', d: 'Yerno de Roberto I: un duque borgoñón en el trono francés, trece años combatiendo rebeldes y normandos.' },
  fr_louis_iv: { n: 'Luis IV de Ultramar', p: 'París', d: '«De ultramar» — criado en Inglaterra, restaurado por Hugo el Grande: el último intento real de los carolingios por reinar — contra sus propios vasallos.' },
  fr_lothair: { n: 'Lotario', p: 'París', d: 'El penúltimo carolingio: treinta y dos años sosteniendo el reino entre el imperio de Otón y los Robertinos en ascenso.' },
  fr_louis_v: { n: 'Luis V el Holgazán', p: 'París', d: 'El último carolingio: coronado por su padre, muerto al año en una caída de caza — «el Inútil» fue el epitafio de la línea.' },
  fr_hugh_capet: { n: 'Hugo Capeto', p: 'París', d: 'El duque de los francos elegido rey al extinguirse los carolingios (987) — su condado discreto dio nombre a una dinastía de ocho siglos.' },
  fr_robert_ii: { n: 'Roberto II el Piadoso', p: 'París', d: 'El cristiano fervoroso que se excomulgó casándose — quemas de herejes, un reino crecido a dotes, y la primera corregencia para su hijo.' },
  fr_henry_i_fr: { n: 'Enrique I de Francia', p: 'París', d: 'Coronado en vida de su padre: luchó contra su madre y su hermano rebeldes — y ayudó al joven Guillermo a gobernar Normandía antes de que Normandía conquistara Inglaterra.' },
  fr_philip_i: { n: 'Felipe I', p: 'París', d: 'El primero en titularse «rey de Francia» — largo reinado, codicioso y obeso: excomulgado por su matrimonio doble, aún entregó el reino intacto.' },
  fr_louis_vi: { n: 'Luis VI el Gordo', p: 'París', d: 'El guerrero que domó a los señores ladrones de la Isla de Francia castillo a castillo — y puso al abad Suger, gran cronista, a escribirlo.' },
  fr_louis_vii: { n: 'Luis VII el Joven', p: 'París', d: 'Marchó a la Segunda Cruzada y volvió sin su reina, Leonor de Aquitania — cuyo nuevo matrimonio dobló el imperio Plantagenet.' },
  fr_philip_ii: { n: 'Felipe II Augusto', p: 'París', d: 'El conquistador: Bouvines (1214), Normandía y Anjou quitados al rey Juan — el rey que hizo del borrajo feudal el reino más rico de Europa.' },
  fr_louis_viii: { n: 'Luis VIII el León', p: 'París', d: 'Cruzado contra los cátaros del sur — murió de vuelta de una campaña que casi le dio la Gascuña inglesa.' },
  fr_louis_ix: { n: 'Luis IX — San Luis', p: 'París', d: 'El rey justo: dos cruzadas, ambas desastres; murió de peste ante Túnez (1270) — canonizado, el modelo de la realeza medieval.' },
  fr_philip_iii: { n: 'Felipe III el Atrevido', p: 'París', d: 'Heredó la cruzada en la que murió su padre — se retiró de Aragón en una retirada que mató más por disentería que por combate.' },
  fr_philip_iv: { n: 'Felipe IV el Hermoso', p: 'París', d: 'El rey de hierro: quebró a Bonifacio VIII, destruyó a los templarios (1307), exprimió a los judíos — y murió de caza con la maldición del Templo sonando.' },
  fr_louis_x: { n: 'Luis X el Obstinado', p: 'París', d: 'Dieciocho meses de fiestas y cartas serviles — muerto a los veintiséis tras un partido de tenis, dejando reina embarazada.' },
  fr_john_posthumous: { n: 'Juan I el Póstumo', p: 'París', d: 'Rey de Francia durante cinco días de vida de cuna — muerto de infante, su tío Felipe tomó el trono, y la ley sálica se endureció.' },
  fr_philip_v: { n: 'Felipe V el Largo', p: 'París', d: 'Venció la pretensión de su sobrina con el principio de que las mujeres no heredan la corona — reformó la moneda, murió a los treinta.' },
  fr_charles_iv_fr: { n: 'Carlos IV el Hermoso', p: 'París', d: 'El último Capeto directo: murió sin hijos y con reina embarazada — la crisis sucesoria que abrió la Guerra de los Cien Años.' },
  fr_philip_vi: { n: 'Felipe VI de Valois', p: 'París', d: 'El primo elegido frente a Eduardo III — cuya contra-pretensión encendió la Guerra de los Cien Años; derrotado en Crécy y perdido Calais (1347).' },
  fr_john_ii: { n: 'Juan II el Bueno', p: 'París', d: 'Capturado en Poitiers (1356) — volvió de su honorable cautiverio inglés para morir, porque un príncipe que rompía su palabra no era príncipe.' },
  fr_charles_v: { n: 'Carlos V el Sabio', p: 'París', d: 'Recuperó todo con guerra de emboscadas y Bertrand du Guesclin — construyó la Bastilla y la biblioteca real, murió sospechando de todos.' },
  fr_charles_vi: { n: 'Carlos VI el Loco', p: 'París', d: 'El rey loco que asesinó a sus propios caballeros en un delirio en el bosque (1392): Francia se partió entre armagnacs y borgoñones — y entraron los ingleses.' },
  fr_henry_vi_fr: { n: 'Enrique VI de Inglaterra — rey de Francia', p: 'París', d: 'El Tratado de Troyes hizo rey de Francia al infante inglés (1422): diez años de monarquía doble — hasta que una campesina de Domrémy la quebró.' },
  fr_charles_vii: { n: 'Carlos VII — el bien servido', p: 'París', d: 'Coronado en Reims gracias a Juana de Arco: acabó la Guerra de los Cien Años en Castillon (1453) — la entregó al fuego y luego la rehabilitó.' },
  fr_louis_xi: { n: 'Luis XI — la araña universal', p: 'París', d: 'Astuto bajo un sombrero caído: quebró a Carlos el Temerario en Nancy (1477), hiló el correo, la imprenta — y una telaraña de miedo.' },
  fr_charles_viii: { n: 'Carlos VIII', p: 'París', d: 'El afable rey joven que invadió Italia (1494) — murió a los veintiocho golpeándose la cabeza con el dintel de una puerta, sin hijos.' },
  fr_louis_xii: { n: 'Luis XII — Padre del Pueblo', p: 'París', d: '«Padre de su pueblo»: casó con Juana la Coja y luego con la viuda Ana de Bretaña — conservó su ducado, la paz y los impuestos bajos.' },
  fr_francis_i: { n: 'Francisco I', p: 'París', d: 'El rey caballero del Renacimiento: Marignano, Leonardo muriendo en sus brazos, Fontainebleau — capturado en Pavía (1525) escribió a su madre la carta famosa.' },
  fr_henry_ii_fr: { n: 'Enrique II', p: 'París', d: 'El rey de Diana de Poitiers: persiguió herejes con la Cámara Ardiente — murió de una lanza astillada en el ojo en el torneo de la boda de su hija (1559).' },
  fr_francis_ii: { n: 'Francisco II', p: 'París', d: 'El niño enfermizo casado con María Estuardo — los hermanos Guisa gobernaron en su nombre; muerto a los dieciséis, un absceso de oído.' },
  fr_charles_ix: { n: 'Carlos IX', p: 'París', d: 'El rey de las Guerras de religión — y de la matanza de San Bartolomé (1572), que lo royó hasta el lecho de muerte.' },
  fr_henry_iii: { n: 'Enrique III', p: 'París', d: 'El último Valois: elegante, piadoso, apuñalado por un fanático dominico tras mandar asesinar él al duque de Guisa (1589) — la línea murió con él.' },
  fr_henry_iv: { n: 'Enrique IV de Borbón', p: 'París', d: '«París bien vale una misa»: el bearnés que se convirtió para acabar las guerras — Edicto de Nantes, gallina en cada olla, apuñalado por Ravaillac (1610).' },
  fr_louis_xiii: { n: 'Luis XIII el Justo', p: 'París', d: 'El rey reservado y el cardenal Richelieu: rompieron las fortalezas de los nobles y entraron en la Guerra de los Treinta Años — murió oyendo misa, en la Ascensión.' },
  fr_louis_xiv: { n: 'Luis XIV — el Rey Sol', p: 'Versalles, Francia', d: 'Setenta y dos años en el trono: «El Estado soy yo» — Versalles construido, las dragonadas contra hugonotes, y Europa aliada contra él cuatro guerras.' },
  fr_louis_xv: { n: 'Luis XV', p: 'Versalles, Francia', d: '«Después de mí, el diluvio»: el Amado querido volvióse indiferente — perdió la Guerra de los Siete Años y casi todo el imperio, aplaudiendo en su ópera de despedida.' },
  fr_louis_xvi: { n: 'Luis XVI', p: 'Versalles, Francia', d: 'El rey cerrajero que quiso ser bueno: convocó los Estados Generales y perdió el control de la Revolución — guillotinado el 21 de enero de 1793.' },
  fr_louis_xviii: { n: 'Luis XVIII', p: 'París', d: 'El conde de Provenza con gota, devuelto tras Napoleón: otorgó la Carta constitucional — reinó a través de la interrupción de los Cien Días.' },
  fr_charles_x: { n: 'Carlos X', p: 'París', d: 'El hermano ultrarrealista: coronación con ritos medievales, censura y indemnizaciones — la Revolución de Julio de 1830 lo mandó al exilio.' },
  fr_louis_philippe: { n: 'Luis Felipe I — el rey ciudadano', p: 'París', d: 'El rey banquero de Orleans con paraguas: reinó para la monarquía burguesa de Julio — huyó disfrazado de «Mr. Smith» en la revolución de 1848.' },
  fr_napoleon_iii: { n: 'Napoleón III', p: 'París', d: 'El sobrino que fue presidente por voto y emperador por plebiscito (1852): el París de Haussmann, la concesión del Suez — y Sedán (1870).' }
});

/* Monarcas de Inglaterra y Gran Bretaña — 27-10-2026 */
Object.assign(window.DATA_ES, {
  eng_alfred: { n: 'Alfredo el Grande', p: 'Winchester, Inglaterra', d: 'Rey de Wessex que quemó los pasteles y derrotó al Gran Ejército Pagano — el único rey inglés llamado «el Grande», el primero en llamarse rey de los anglosajones.' },
  eng_edward_elder: { n: 'Eduardo el Viejo', p: 'Winchester, Inglaterra', d: 'Tomó el Danelaw sur pueblo a pueblo y se tituló, sobre la plantilla de su padre, rey de los anglosajones.' },
  eng_aethelstan: { n: 'Athelstan', p: 'Winchester, Inglaterra', d: 'El primer verdadero Rey de Inglaterra: venció la gran batalla de Brunanburh (937) y gobernó del Canal al Firth of Forth.' },
  eng_edmund_i: { n: 'Edmundo I', p: 'Winchester, Inglaterra', d: 'Restauró el movimiento monástico y el culto de su predecesor asesinado — muerto en un banquete por un forajido desterrado (946).' },
  eng_edred: { n: 'Eadred', p: 'Winchester, Inglaterra', d: 'El rey monje que sostuvo el reino frente a los noruegos de York — muerto a los treinta y dos de salud machacada.' },
  eng_edwy: { n: 'Eadwig el Bello', p: 'Winchester, Inglaterra', d: 'Coronado a los catorce, enemistado con santos y obispos por un escándalo de coronación — expulsado de Mercia a los tres años.' },
  eng_edgar: { n: 'Edgar el Pacífico', p: 'Winchester, Inglaterra', d: 'La cota más alta del orden anglosajón — una coronación en Bath cuyo rito copiarían palabra por palabra los reyes posteriores.' },
  eng_edward_martyr: { n: 'Eduardo el Mártir', p: 'Winchester, Inglaterra', d: 'Asesinado en Corfe por la facción de su madrastra (978) — el rey niño venerado antes de que el país comenzara a fabricar santos.' },
  eng_ethelred: { n: 'Etelred el Indeciso', p: 'Winchester, Inglaterra', d: '«Mal aconsejado»: pagó el Danegeld, huyó de la conquista de Svend — y volvió para morir con su reino desmoronándose.' },
  eng_edmund_ironside: { n: 'Edmundo II Costillas de Hierro', p: 'Winchester, Inglaterra', d: 'Empató cinco batallas con Canuto — murió semanas después del tratado que repartía Inglaterra, según la leyenda apuñalado en el retrete.' },
  eng_harold_harefoot: { n: 'Haroldo I Pie de Liebre', p: 'Winchester, Inglaterra', d: 'Hijo de Canuto que arrebató la regencia a su hermanastro — regente hecho rey, muerto en cuatro años.' },
  eng_edward_confessor: { n: 'Eduardo el Confesor', p: 'Londres', d: 'El rey piadoso y normanófilo del inicio del tapiz de Bayeux — fundador de la abadía de Westminster; sin hijos, encendió la crisis de 1066.' },
  eng_harold_ii: { n: 'Harold II Godwinson', p: 'Londres', d: 'El último rey anglosajón: venció a los noruegos en Stamford Bridge, marchó al sur y cayó en Hastings tres semanas después.' },
  eng_edgar_aetheling: { n: 'Edgar Atheling', p: 'Londres', d: 'Elegido por el witan tras Hastings pero jamás coronado — el heredero legítimo que se sometió a Guillermo y vivió hasta las cruzadas.' },
  eng_william_i: { n: 'Guillermo I el Conquistador', p: 'Londres', d: 'Hastings, el asolamiento del Norte, el Domesday Book — Inglaterra se volvió de la noche a la mañana un estado feudal francófono.' },
  eng_william_ii: { n: 'Guillermo II el Rojo', p: 'Londres', d: 'El Rojo: un rey vistoso que robaba a la Iglesia — abatido por una flecha en el Bosque Nuevo (1100), por accidente o a propósito.' },
  eng_henry_i: { n: 'Enrique I Beauclerc', p: 'Londres', d: 'El rey erudito: se apoderó de la corona, casó con Escocia — y perdió a su único hijo legítimo en el White Ship (1120).' },
  eng_stephen: { n: 'Esteban de Blois', p: 'Londres', d: 'El rey bondadoso cuya blandura dejó que los «diecinueve largos inviernos» de guerra civil con Matilde asolara Inglaterra.' },
  eng_matilda: { n: 'La emperatriz Matilde — la pretendiente', p: 'Oxford, Inglaterra', d: 'Hija de Enrique I: elegida «dama de los ingleses» en 1141, nunca coronada — a través de su hijo nació la pretensión Plantagenet.' },
  eng_henry_ii: { n: 'Enrique II Plantagenet', p: 'Londres', d: 'Un imperio de Escocia a los Pirineos: Becket asesinado en su propia catedral — y el common law que sus jueces construyeron.' },
  eng_richard_i: { n: 'Ricardo I Corazón de León', p: 'Londres', d: 'Tercera Cruzada, cautiverio en Austria, diez semanas en Inglaterra de un reinado de diez años — y un virote de ballesta en Châlus.' },
  eng_john: { n: 'Juan sin Tierra', p: 'Londres', d: 'Perdió Normandía, pleiteó con el Papa — y en Runnymede selló la Carta Magna (1215) bajo los cuchillos de sus barones.' },
  eng_henry_iii: { n: 'Enrique III', p: 'Londres', d: 'El reinado medieval más largo: reconstruyó la abadía de Westminster en gótico — mientras las Provisiones baroniales parían el parlamento inglés.' },
  eng_edward_i: { n: 'Eduardo I Piernas Largas', p: 'Londres', d: 'El Parlamento Modelo, la conquista de Gales — y el «Martillo de los escoceses», como reza su tumba.' },
  eng_edward_ii: { n: 'Eduardo II', p: 'Londres', d: 'El rey de los favoritos derrotado en Bannockburn — depuesto por su propia reina y asesinado en el castillo de Berkeley (1327).' },
  eng_edward_iii: { n: 'Eduardo III', p: 'Londres', d: 'La cúspide caballeresca: Crécy y Poitiers, la Orden de la Jarretera — y la Guerra de los Cien Años abierta por su pretensión francesa.' },
  eng_richard_ii: { n: 'Ricardo II', p: 'Londres', d: 'Coronado a los diez, aplastó la revuelta campesina a los catorce — luego apresado por su primo Bolingbroke y muerto de hambre en Pontefract.' },
  eng_henry_iv: { n: 'Enrique IV Bolingbroke', p: 'Londres', d: 'El usurpador que tomó la corona en vez de su herencia — catorce años perseguido por revueltas.' },
  eng_henry_v: { n: 'Enrique V', p: 'Londres', d: 'Azincourt (1415) y el Tratado de Troyes: heredero de la corona de Francia — muerto a los treinta y cinco, semanas antes del rey francés.' },
  eng_henry_vi: { n: 'Enrique VI', p: 'Londres', d: 'El rey niño piadoso cuyos dos reinados se hundieron en la Guerra de las Rosas — asesinado en la Torre la noche del regreso de York (1471).' },
  eng_edward_iv: { n: 'Eduardo IV', p: 'Londres', d: 'El superviviente yorkista: venció en Towton y Tewkesbury, lo malgastó en amantes — muerto gordo a los cuarenta (1483).' },
  eng_edward_v: { n: 'Eduardo V', p: 'Londres', d: 'El rey niño de la Torre: declarado ilegítimo por su tío y jamás visto otra vez — uno de los Príncipes de la Torre.' },
  eng_richard_iii: { n: 'Ricardo III', p: 'Londres', d: 'El villano jorobado del drama Tudor — o el capaz último Plantagenet: muerto en Bosworth (1485), hallado bajo un aparcamiento de Leicester en 2012.' },
  eng_henry_vii: { n: 'Enrique VII Tudor', p: 'Londres', d: 'El rey contable: ganó Bosworth, casó con la rosa rival — y llenó la tesorería con rigor de banquero.' },
  eng_henry_viii: { n: 'Enrique VIII', p: 'Londres', d: 'Seis esposas, dos decapitadas: rompió con Roma por Ana Bolena y se hizo cabeza suprema de una iglesia inglesa.' },
  eng_edward_vi: { n: 'Eduardo VI', p: 'Londres', d: 'El rey niño reformador: Inglaterra se volvió calvinista en su nombre — muerto a los quince antes de que su «devise» coronara a lady Jane.' },
  eng_jane_grey: { n: 'Lady Jane Grey — la reina de los nueve días', p: 'Londres', d: 'Proclamada, destronada por María en nueve días, ejecutada a los diecisiete (1554) — peón del protestantismo en el trono.' },
  eng_mary_i: { n: 'María I Tudor', p: 'Londres', d: 'Bloody Mary: quemó a trescientos herejes, casó con Felipe de España — y perdió Calais, el último puerto francés de Inglaterra.' },
  eng_elizabeth_i: { n: 'Isabel I', p: 'Londres', d: 'La reina Virgen: la Armada derrotada, Shakespeare en los escenarios, Inglaterra en ascenso — «tengo el corazón y el estómago de un rey».' },
  eng_james_i: { n: 'Jaime I (Jacobo VI de Escocia)', p: 'Londres', d: 'Cabalgó al sur hacia el trono de Isabel: la Biblia del rey Jacobo, la Conspiración de la Pólvora — y la teoría del derecho divino por la que murió su hijo.' },
  eng_charles_i: { n: 'Carlos I', p: 'Londres', d: 'El rey del derecho divino que pleiteó el Parlamento hasta la guerra civil — juzgado y decapitado en Whitehall (1649).' },
  eng_william_mary: { n: 'Guillermo III y María II', p: 'Londres', d: 'Los soberanos conjuntos de la Revolución Gloriosa: invitados por el Parlamento, aceptando la Declaración de Derechos (1689) — María murió en 1694, Guillermo siguió reinando.' },
  eng_anne: { n: 'Ana Estuardo', p: 'Londres', d: 'La última Estuardo: la unión con Escocia (1707) la hizo primera reina de Gran Bretaña — enterró a los diecisiete hijos.' },
  eng_george_i: { n: 'Jorge I de Hannover', p: 'Londres', d: 'El rey que no hablaba inglés: Walpole, el primer primer ministro, gobernó en su nombre — y ardieron revueltas jacobitas.' },
  eng_george_ii: { n: 'Jorge II', p: 'Londres', d: 'El último rey que dirigió un ejército en batalla (Dettingen, 1743) — el Mesías de Handel sonaba en su corte.' },
  eng_george_iii: { n: 'Jorge III', p: 'Londres', d: 'El rey que perdió América y sobrevivió a su propia mente — sesenta años, la Union Jack y quince hijos.' },
  eng_george_iv: { n: 'Jorge IV', p: 'Londres', d: 'El regente del Pabellón de Brighton y de deudas enormes — el único monarca moderno que vetó a su esposa en su propia coronación.' },
  eng_william_iv: { n: 'Guillermo IV', p: 'Londres', d: 'El rey marino — «Silly Billy» — que puenteó la era reformista y murió dejando la corona a Victoria, de dieciocho.' },
  eng_victoria: { n: 'Victoria', p: 'Londres', d: 'Sesenta y tres años y un imperio en el que no se ponía el sol — cuarenta de ellos de luto negro por Alberto.' },
  eng_edward_vii: { n: 'Eduardo VII', p: 'Londres', d: 'Bertie, el tío playboy de Europa: la Entente Cordiale con Francia — coronado a los cincuenta y nueve tras cincuenta y nueve años de espera.' },
  eng_george_v: { n: 'Jorge V Windsor', p: 'Londres', d: 'El rey que renombró la dinastía Windsor: soberano de la Primera Guerra Mundial — y el primer mensaje navideño por radio (1932).' },
  eng_edward_viii: { n: 'Eduardo VIII', p: 'Londres', d: 'El abdicador: once meses en el trono — «he encontrado imposible llevar la pesada carga sin la mujer que amo».' },
  eng_george_vi: { n: 'Jorge VI', p: 'Londres', d: 'El rey tartamudo del Blitz: se quedó en el Londres bombardeado — murió a los cincuenta y seis, haciendo reina a su hija a los veinticinco.' },
  eng_elizabeth_ii: { n: 'Isabel II', p: 'Londres', d: 'Setenta años: quince primeros ministros y un jubileo de platino — la monarca moderna más longeva del mundo, «nuestra Isabel».' },
  eng_charles_iii: { n: 'Carlos III', p: 'Londres', d: 'El heredero que esperó setenta y tres años, coronado en 2023 — defensor del medio ambiente en un trono que su madre sostuvo siete décadas.' }
});

/* ── 52 monarcas alemanes + 39 gobernantes de Austria (2026-10-28) ── */
Object.assign(window.DATA_ES, {
  de_louis_ii_german: { n: 'Luis II el Germánico', p: 'Ratisbona, Alemania', d: 'Nieto de Carlomagno: el Tratado de Verdún (843) le da Francia Oriental, el tercio oriental germanohablante — el primer «Reino de Alemania» como reino propio.' },
  de_carloman_bavaria: { n: 'Carlomán de Baviera', p: 'Ratisbona, Alemania', d: 'Hijo mayor de Luis el Germánico: Baviera por herencia, Italia y la corona imperial por conquista — un derrame cerebral lo corta todo en cuatro años.' },
  de_louis_iii_younger: { n: 'Luis III el Joven', p: 'Ratisbona, Alemania', d: 'Derrotó la invasión franca occidental en Andernach (876) — el momento en que Francia Oriental se sostiene sola — y añadió la Lotaringia occidental; murió a los treinta y tres.' },
  de_arnulf: { n: 'Arnulfo de Carintia', p: 'Ratisbona, Alemania', d: 'El sobrino ilegítimo que depuso a su tío Carlos el Gordo, reunió al este contra vikingos y magiares — y fue coronado emperador tras romper el asedio normando de Lovaina (891).' },
  de_louis_iv_child: { n: 'Luis IV el Niño', p: 'Forchheim, Alemania', d: 'Coronado a los seis años, el último carolingio del este: empiezan las incursiones magiares, los duques toman el poder en silencio — la dinastía muere con él a los diecisiete.' },
  de_conrad_i: { n: 'Conrado I', p: 'Forchheim, Alemania', d: 'El primer rey sin sangre carolingia, elegido por los duques — nueve años luchando contra ellos, y en su lecho de muerte les recomendó elegir a su rival más fuerte: Enrique de Sajonia.' },
  de_henry_i_fowler: { n: 'Enrique I el Pajarero', p: 'Quedlinburgo, Alemania', d: 'Elegido sin unción eclesiástica para conservar el favor de los duques: construyó plazas fortificadas contra los jinetes magiares y los aplastó en Riade (933) — fundador de la dinastía otoniana.' },
  de_otto_i: { n: 'Otón I el Grande', p: 'Magdeburgo, Alemania', d: 'Domó a los duques, aplastó a los magiares en el Lechfeld (955) y fue coronado emperador en Roma (962): nace el Sacro Imperio Romano — con Magdeburgo como su ciudad querida.' },
  de_otto_ii: { n: 'Otón II el Rojo', p: 'Aquisgrán, Alemania', d: 'Se casó con una princesa bizantina y soñó con un imperio romano-mediterráneo — hasta que los sarracenos aniquilaron su ejército en Calabria (982); murió a los veintiocho.' },
  de_otto_iii: { n: 'Otón III — «maravilla del mundo»', p: 'Aquisgrán, Alemania', d: 'El emperador niño de sueños bizantinos: abrió la tumba de Carlomagno en Aquisgrán, tenía un león domesticado, gobernaba desde Roma — muerto a los veintiuno, con él el imperio de la imaginación.' },
  de_henry_ii: { n: 'Enrique II el Santo', p: 'Bamberg, Alemania', d: 'El último otoniano: fundó el obispado de Bamberg, combatió con una lanza santa en la mano — canonizado en 1146, el único rey de Alemania hecho santo.' },
  de_conrad_ii: { n: 'Conrado II', p: 'Espira, Alemania', d: 'Un «pequeño conde» elegido para una mediocridad esperada: en cambio renovó el imperio, tomó Borgoña y comenzó la catedral de Espira como panteón imperial.' },
  de_henry_iii: { n: 'Enrique III el Negro', p: 'Espira, Alemania', d: 'El poder imperial en su cenit: tres papas rivales depuestos en Sutri (1046), un papado reformado bajo vigilancia alemana — una autocracia que su hijo no podrá sostener.' },
  de_henry_iv: { n: 'Enrique IV', p: 'Goslar, Alemania', d: 'Caminó a Canossa (1077) — descalzo en la nieve ante el papa Gregorio VII — y luchó treinta años más de excomuniones, antirreyes y guerra civil; al final depuesto por su propio hijo.' },
  de_henry_v: { n: 'Enrique V', p: 'Espira, Alemania', d: 'Tomó el trono sobre el cuerpo quebrantado de su padre, luego peleó la misma guerra de investiduras — y la cerró con el Concordato de Worms (1122): iglesia e imperio, divorciados.' },
  de_lothar_ii: { n: 'Lotario II de Supplinburgo', p: 'Goslar, Alemania', d: 'Elegido contra los Staufen, llevó un ejército papal a Roma y murió en el camino de regreso de Italia — dejando que güelfos y Hohenstaufen se degollaran por la sucesión una generación.' },
  de_conrad_iii: { n: 'Conrado III', p: 'Núremberg, Alemania', d: 'El primer rey Hohenstaufen: cruzó a un desastre en Dorilea, asedió en casa a sus rivales güelfos — el único rey de su época que nunca alcanzó una coronación imperial en Roma.' },
  de_frederick_barbarossa: { n: 'Federico I Barbarroja', p: 'Núremberg, Alemania', d: 'Barbirrojo e incansable: canonizó a Carlomagno, libró cinco campañas italianas hasta la derrota de Legnano (1176) y se ahogó en el río Salef en la Tercera Cruzada — su barba duerme bajo el Kyffhäuser, el rey que un día volverá.' },
  de_henry_vi: { n: 'Enrique VI', p: 'Worms, Alemania', d: 'Heredero de Barbarroja: tomó Sicilia en una blitzkrieg, retuvo a Ricardo Corazón de León por rescate y casi hizo hereditaria la corona imperial — muerto a los treinta y dos, dejando un bebé de tres años.' },
  de_philip_swabia: { n: 'Felipe de Suabia', p: 'Bamberg, Alemania', d: 'Su doble elección partió Alemania en dos reinos — el bando de Felipe detentaba la riqueza del sur, hasta que un pariente ofendido lo asesinó en un banquete de bodas (1208).' },
  de_otto_iv: { n: 'Otón IV', p: 'Brunswick, Alemania', d: 'El güelfo que al fin venció a Felipe, fue excomulgado igualmente y vio su ejército destrozado por Francia en Bouvines (1214) — el último emperador güelfo, despojado por sus propios electores.' },
  de_frederick_ii: { n: 'Federico II — «stupor mundi»', p: 'Palermo, Italia', d: 'Rey de Sicilia, «maravilla del mundo»: seis lenguas, la primera ciencia de la cetrería, una corte de sabios árabes, griegos y judíos — excomulgado cuatro veces, tomó Jerusalén por tratado (1229) y murió de caza: el último emperador de la edad medieval.' },
  de_conrad_iv: { n: 'Conrado IV', p: 'Núremberg, Alemania', d: 'Elegido en vida de su padre y jamás rey verdadero de nada: luchó por una Alemania y una Sicilia que no pudo retener, murió de malaria a los veintiséis — el fin de su estirpe abre el Gran Interregno.' },
  de_rudolf_i: { n: 'Rodolfo I de Habsburgo', p: 'Castillo de Habsburgo, Suiza', d: 'El conde menor elegido para terminar el Gran Interregno: derrotó a Otakar de Bohemia en el campo de Marchfeld, entregó Austria a sus hijos — e hizo de «Habsburgo» el nombre de los próximos seis siglos de Europa.' },
  de_adolf_nassau: { n: 'Adolfo de Nassau', p: 'Nassau, Alemania', d: 'El rey de los pactos electorales: compró votos con promesas, empeñó ciudades imperiales a Inglaterra por dinero — batido y muerto por Alberto de Habsburgo en Göllheim (1298).' },
  de_albert_i: { n: 'Alberto I', p: 'Viena, Austria', d: 'Heredero de Rodolfo y señor de Austria: un rey duro y capaz — sus impuestos empujaron a los cantones bosques suizos a la revuelta, y su propio sobrino lo apuñaló junto al Reuss (1308).' },
  de_henry_vii: { n: 'Enrique VII', p: 'Luxemburgo', d: 'El luxemburgués que revivió el sueño imperial: cabalgó hacia Italia, coronado en Roma (1312) — el salvador que esperaba Dante — muerto de fiebre en Toscana a los cuarenta, imperio y sueño inacabados.' },
  de_louis_iv_bavaria: { n: 'Luis IV el Bávaro', p: 'Múnich, Alemania', d: 'Excomulgado por desafiar al Papa, respondió con un manifiesto: los emperadores responden solo ante Dios — Marsilio y Ockham escribieron la causa en su corte, las primeras grandes teorías políticas de la época; murió en una cacería de osos.' },
  de_charles_iv: { n: 'Carlos IV', p: 'Praga, Bohemia', d: 'El hijo dorado de los Luxemburgo y rey de Bohemia: hizo de Praga una capital imperial, fundó su universidad (1348), escribió la Bula de Oro (1356) — la constitución de trabajo del imperio por 450 años.' },
  de_wenceslaus: { n: 'Wenceslao IV', p: 'Praga, Bohemia', d: 'Rey de Bohemia y ausente imperial: se adormeció a través del Cisma mientras el imperio se gobernaba solo — el único rey de romanos jamás votado fuera por sus electores (1400).' },
  de_rupert: { n: 'Ruperto del Palatinado', p: 'Heidelberg, Alemania', d: 'El Wittelsbach elegido en lugar de Wenceslao: honesto, pobre y sin dinero — su expedición italiana se deshizo por falta de paga, y lo enterraron en la iglesia de Heidelberg que él mismo había construido.' },
  de_sigismund: { n: 'Segismundo', p: 'Buda, Hungría', d: 'El último Luxemburgo, rey de Hungría: convocó el Concilio de Constanza (1414) que sanó el Cisma — y quemó a Jan Hus, encendiendo las guerras husitas que devoraron cinco cruzadas.' },
  de_frederick_iii: { n: 'Federico III', p: 'Viena, Austria', d: 'El emperador A.E.I.O.U.: cincuenta y tres años en el trono, la mayoría perdiéndolos — sobrevivió a todo rival, movió la corte a Viena y ganó media Europa casando a su hijo con la heredera de Borgoña.' },
  de_maximilian_i: { n: 'Maximiliano I — el último caballero', p: 'Innsbruck, Austria', d: 'Lansquenetes, artillería y autopropaganda: tomó Borgoña por matrimonio y casó a sus nietos con España, Bohemia y Hungría — «Bella gerant alii, tu felix Austria nube.»' },
  de_charles_v: { n: 'Carlos V', p: 'Gante, Flandes', d: 'Un imperio donde nunca se ponía el sol — España, las Américas, los Países Bajos, Alemania: combatió a Francia y a los otomanos, enfrentó a Lutero en Worms (1521) — y se retiró agotado a un monasterio, partiéndolo en dos la herencia Habsburgo.' },
  de_ferdinand_i: { n: 'Fernando I', p: 'Viena, Austria', d: 'Hermano de Carlos y teniente de Austria: tras Mohács (1526) recogió las coronas de Hungría y Bohemia, detuvo a los turcos ante las puertas de Viena — fundador de la línea austriaca de los Habsburgo.' },
  de_maximilian_ii: { n: 'Maximiliano II', p: 'Viena, Austria', d: 'El humanista tolerante: mantuvo las confesiones en paz con vaga deliberación, mantuvo protestantes en su corte vienesa — y casi cerró la escisión austro-española de los Habsburgo con una doble boda que nunca llegó a ser.' },
  de_rudolf_ii: { n: 'Rodolfo II', p: 'Praga, Bohemia', d: 'El emperador alquimista: movió la corte a Praga y coleccionó a Tycho, Kepler, Arcimboldo y la mejor cámara de maravillas de Europa — mientras Hungría ardía y su familia lo cercaba en el Hradčany.' },
  de_matthias: { n: 'Matías', p: 'Viena, Austria', d: 'El hermano que quitó a Rodolfo sus coronas con un golpe familiar: su reinado fue paz — y las concesiones de sus generales en Bohemia, la mecha de la Guerra de los Treinta Años, encendida en Praga en 1618.' },
  de_ferdinand_ii: { n: 'Fernando II', p: 'Graz, Austria', d: 'El celoso estirio educado por jesuitas: rechazó las condiciones bohemias, ganó la Montaña Blanca (1620), lanzó el Edicto de Restitución — una guerra por la confesión, pagada por un tercio de la gente de Alemania.' },
  de_ferdinand_iii: { n: 'Fernando III', p: 'Viena, Austria', d: 'Comandó en el campo por las décadas perdidas, y luego firmó la Paz de Westfalia (1648): los estados alemanes obtienen soberanía, el imperio una cáscara vacía — y Europa el moderno sistema de estados.' },
  de_leopold_i: { n: 'Leopoldo I', p: 'Viena, Austria', d: 'El emperador barroco con la mandíbula Habsburgo: cuarenta y siete años de guerras contra Luis XIV y dos asedios otomanos — Viena salva por Sobieski (1683), Hungría reconquistada, y buena música en la corte compuesta por el propio emperador.' },
  de_joseph_i: { n: 'José I', p: 'Viena, Austria', d: 'El heredero enérgico: aplastó el levantamiento húngaro de Rákóczi, ganó Blenheim (1704) junto a Marlborough — un reinado lleno de promesas, muerto a los treinta y dos de viruela.' },
  de_charles_vi: { n: 'Carlos VI', p: 'Viena, Austria', d: 'El último Habsburgo varón: peleó una década para probar que España no era suya, y luego gastó su reinado en la Pragmática Sanción — la firmaron todos los vecinos, y todos los vecinos rompieron su palabra a los meses de su muerte.' },
  de_charles_vii: { n: 'Carlos VII', p: 'Múnich, Alemania', d: 'El Wittelsbach que tomó la corona mientras María Teresa sostenía las espadas: elegido tras las bayonetas francesas, coronado en Frankfurt — muerto en tres años, su propia Baviera ocupada por tropas austriacas.' },
  de_francis_i_lorraine: { n: 'Francisco I Esteban', p: 'Viena, Austria', d: 'Lorena trocada por Toscana, luego consorte de María Teresa y emperador: agudo en finanzas y monopolios estatales, padre de dieciséis hijos — la sociedad sobre la que corría el Estado Habsburgo.' },
  de_joseph_ii: { n: 'José II', p: 'Viena, Austria', d: 'El revolucionario en el trono: abolió la servidumbre, cerró la mitad de los monasterios, hizo del alemán la lengua del Estado, toleró toda fe — «He hecho de la filosofía el legislador de mi imperio»; diez años de decretos, la mayoría deshechos al final.' },
  de_leopold_ii: { n: 'Leopoldo II', p: 'Florencia, Italia', d: 'El gran duque de Toscana que abolió la pena de muerte — el primer Estado en hacerlo — luego tomó en 1790 un imperio en llamas, apaciguó Hungría y los Países Bajos, y murió mientras se juntaba la tormenta francesa.' },
  de_francis_ii: { n: 'Francisco II / I', p: 'Viena, Austria', d: 'El último emperador del Sacro Imperio — disolvió el imperio milenario en 1806 al aliento de Napoleón — y el primer emperador de Austria: el suegro vencido de Napoleón, el señor reaccionario de Metternich, cuarenta y tres años de orden y policía.' },
  de_wilhelm_i: { n: 'Guillermo I', p: 'Berlín, Alemania', d: 'El rey prusiano que no quería un imperio y lo obtuvo: tres guerras diseñadas por Bismarck — Dinamarca, Austria, Francia — y proclamado emperador alemán en la Sala de los Espejos de Versalles, a los setenta y cuatro.' },
  de_frederick_iii_german: { n: 'Federico III — los noventa y nueve días', p: 'Potsdam, Alemania', d: 'El príncipe heredero liberal, obligado a esperar por la longevidad de su padre: el cáncer de garganta se llevó a «Federico el Bueno» antes de que pudiera liberalizar el Reich — el camino de Alemania que no se tomó.' },
  de_wilhelm_ii: { n: 'Guillermo II', p: 'Potsdam, Alemania', d: 'El káiser con el brazo atrofiado y el sueño naval: destituyó a Bismarck, llevó la «Weltpolitik» al cerco, entregó a Austria el cheque en blanco — y abdicó al exilio holandés mientras se derrumbaba el Reich que había provocado.' },

  at_burkhard: { n: 'Burkhard', p: 'Melk, Austria', d: 'Margrave de la marca del Danubio contra los magiares tras la victoria de Otón en el Lechfeld — desposeído por apoyar una revuelta bávara, su Ostmark entregada a los Babenberg.' },
  at_leopold_i: { n: 'Leopoldo I el Ilustre', p: 'Melk, Austria', d: 'Primer margrave Babenberg: recompensado por su lealtad en la guerra bávara — la familia que gobernará Austria los próximos 270 años, empezando por Melk a orillas del Danubio.' },
  at_henry_i_mg: { n: 'Enrique I', p: 'Melk, Austria', d: 'El segundo margrave, silencioso: treinta y cuatro años de asentamientos, fortificaciones y monasterios entre el Enns y el Bosque de Viena — una marca que se vuelve país.' },
  at_adalbert: { n: 'Adalberto el Victorioso', p: 'Melk, Austria', d: 'Venció a los húngaros en el Morava y empujó la frontera hasta el Leitha — el río que hasta hoy es la frontera oriental de Austria.' },
  at_ernst_mg: { n: 'Ernesto el Valiente', p: 'Melk, Austria', d: 'Cayó en Langensalza (1075) combatiendo por el emperador Enrique IV contra los rebeldes sajones — la leyenda le dio una espada demasiado pesada para hombres comunes: el primer cantar heroico de Austria.' },
  at_leopold_ii_mg: { n: 'Leopoldo II el Hermoso', p: 'Melk, Austria', d: 'Tomó el bando papal en la guerra de investiduras y perdió su marca durante tres años — y fundó la abadía benedictina de Melk (1089), el emblema de la Austria barroca hasta hoy.' },
  at_leopold_iii_mg: { n: 'Leopoldo III el Piadoso', p: 'Klosterneuburgo, Austria', d: 'El pacificador de su época, dos veces hacedor de reyes: fundó la abadía de Klosterneuburgo para su novia Agnes — hija de emperador — y fue canonizado como patrón de Austria.' },
  at_leopold_iv_mg: { n: 'Leopoldo IV', p: 'Klosterneuburgo, Austria', d: 'Recibió Baviera como botín staufen y unió ambas tierras por primera vez — murió a los treinta y tres, dejándolo todo a su hermano Enrique.' },
  at_henry_ii_jasomirgott: { n: 'Enrique II Jasomirgott', p: 'Viena, Austria', d: 'El último margrave, primer duque: el Privilegium Minus (1156) hace de Austria un ducado hereditario — hijas incluidas — libre de Baviera, y Viena se vuelve sede; su juramento «jas mir got» («sí, que Dios me ayude») se volvió su apodo.' },
  at_leopold_v: { n: 'Leopoldo V el Virtuoso', p: 'Viena, Austria', d: 'Dio a Austria la bandera rojo-blanco-roja — según la leyenda, de su túnica empapada de sangre en Acre — y capturó a Ricardo Corazón de León cerca de Viena (1192): el rescate reedificó las murallas vienesas y elevó Wiener Neustadt.' },
  at_friedrich_i_austria: { n: 'Federico I de Austria', p: 'Viena, Austria', d: 'Llevó la culpa cruzada de su padre a Tierra Santa en penitencia por la captura de Ricardo — murió en Acre a los veintitrés; el ducado pasó a su tío.' },
  at_leopold_vi: { n: 'Leopoldo VI el Glorioso', p: 'Viena, Austria', d: 'Viena se vuelve gótica, el minnesang llega a la corte — Walther y Neidhart cantan en sus banquetes — y el duque media entre emperadores y papas: la dorada tarde de la Austria Babenberg.' },
  at_friedrich_ii_austria: { n: 'Federico II el Belicoso', p: 'Wiener Neustadt, Austria', d: 'El último Babenberg: luchó con todos los vecinos a la vez y fue excomulgado una y otra vez — muerto en el Leitha contra los magiares, sin heredero, y los príncipes de Europa empiezan a rondar Austria.' },
  at_gertrude: { n: 'Gertrudis de Babenberg', p: 'Wiener Neustadt, Austria', d: 'La heredera con la que todos querían casarse: un matrimonio anulado, un marido muerto, un príncipe de Galitzia — y nada de eso impidió que Otakar de Bohemia se quedara sencillamente con el ducado.' },
  at_roman_danylovych: { n: 'Román Danílovich de Galitzia', p: 'Hainburgo, Austria', d: 'Hijo del rey Danilo de Galitzia: al casarse con la heredera Babenberg Gertrudis, el príncipe ruteno sostuvo las tierras fronterizas austriacas con la caballería de su padre — el único heredero que Galicia-Volinia puso jamás en un trono occidental — hasta que Bohemia y el Papa desbarataron la unión.' },
  at_ottokar_ii: { n: 'Otakar II de Bohemia', p: 'Viena, Austria', d: 'El «rey de hierro y de oro»: recortó de la herencia Babenberg Austria, Estiria y la costa adriática — hasta que Rodolfo de Habsburgo vino a por ella y lo mató en el campo de Marchfeld (1278).' },
  at_rudolf_iii_austria: { n: 'Rodolfo III el Benigno', p: 'Viena, Austria', d: 'Coduque bajo su padre Alberto I, luego rey de Bohemia por la fuerza de las armas Habsburgo — muerto a los dieciocho, la corona boemia enterrada con él.' },
  at_friedrich_handsome: { n: 'Federico el Hermoso', p: 'Viena, Austria', d: 'El Habsburgo al que negaron el imperio: elegido rey contra Luis el Bávaro, vencido en Mühldorf (1322) y encarcelado — liberado bajo juramento de amistad con su captor, lo que asombró a Alemania; gobernó bien Austria hasta el final.' },
  at_albert_ii_wise: { n: 'Alberto II el Sabio', p: 'Viena, Austria', d: 'El duque cojo y gotoso que rechazó tres veces la corona alemana y protegió a sus judíos durante los pogromos de la peste (1349) — Austria mantuvo su propio consejo, y su prosperidad siguió creciendo.' },
  at_rudolf_iv: { n: 'Rodolfo IV el Fundador', p: 'Viena, Austria', d: 'Una carta falsificada, una universidad y una nave gótica: inventó el título de archiduque (Privilegium Maius), fundó la Universidad de Viena (1365), inició la nave de San Esteban — un Estado mayor que sus papeles; muerto en Milán a los veintiséis.' },
  at_albert_iii: { n: 'Alberto III con la Trenza', p: 'Viena, Austria', d: 'Dividió la Casa de Habsburgo con su hermano en Neuberg (1379): Alberto se quedó con Austria propiamente — la línea albertina que añadirá Hungría, Bohemia y, por un instante, el propio imperio.' },
  at_leopold_iii_leopoldin: { n: 'Leopoldo III de la línea Leopoldina', p: 'Graz, Austria', d: 'Recibió la Austria Interior, el Tirol y las tierras occidentales, y codició Suiza — destrozado en Sempach por los suizos (1386), la batalla del sacrificio de Winkelried: con él murió el sueño suizo de Austria.' },
  at_wilhelm_austria: { n: 'Guillermo de Austria', p: 'Viena, Austria', d: 'Prometido a la joven reina Jadwiga de Polonia — ella recibió su visita de medianoche con un hacha, Polonia eligió a Jagiełło, y la boda que habría unido el Báltico con el Danubio nunca fue; gobernó las tierras occidentales de la casa desde Viena.' },
  at_leopold_iv_leopoldin: { n: 'Leopoldo IV', p: 'Viena, Austria', d: 'El hermano mediano y sobrio: gobernó los dispersos países leopoldinos, mantuvo la tutela del Tirol y los asuntos húngaros — murió en Viena, y las querellas familiares redividieron sus tierras a sus espaldas.' },
  at_albert_iv: { n: 'Alberto IV el Paciente', p: 'Viena, Austria', d: 'Duque a los veintidós, muerto a los veintisiete: se emparentó con los Luxemburgo y mantuvo serena la línea albertina mientras los leopoldinos reñían — su hijo Alberto V obtendrá Hungría, Bohemia y una oportunidad de imperio.' },
  at_albert_v: { n: 'Alberto V — la primera corona Habsburgo', p: 'Viena, Austria', d: 'Casado con la hija de Segismundo, heredó con ella Hungría y Bohemia, y luego fue elegido rey de Alemania (1438) — la primera corona imperial Habsburgo; muerto a los cuarenta y dos en campaña contra los turcos, dejando un hijo aún nonato.' },
  at_ladislaus_posthumous: { n: 'Ladislao el Póstumo', p: 'Viena, Austria', d: 'Nacido cuatro meses después de la muerte de su padre — de ahí el nombre: rey de Hungría y Bohemia siendo niño, pupilo del húngaro Hunyadi y del bohemio Poděbrady — muerto de repente a los diecisiete en Praga, acabando la línea albertina.' },
  at_ernst_iron: { n: 'Ernesto el de Hierro', p: 'Graz, Austria', d: 'Se disputó con su hermano el Tirol y con el emperador Segismundo Hungría — «el de Hierro», cuyo hijo Federico V heredará casi todo y vestirá la corona imperial.' },
  at_friedrich_iv_tyrol: { n: 'Federico IV de la bolsa vacía', p: 'Innsbruck, Austria', d: 'Ayudó al antipapa Juan XXIII a escapar de Constanza y fue por ello proscrito: huyó del Tirol como un hombre común, regresó — y convirtió Innsbruck en una corte pequeña de verdad buena; el apodo se le quedó para siempre.' },
  at_sigismund_tyrol: { n: 'Segismundo del Tirol', p: 'Innsbruck, Austria', d: 'Acuñó los primeros grandes táleros de plata de Europa desde las minas de Schwaz, reñía con todos los vecinos — y entregó el Tirol al final a su primo Maximiliano: la línea Leopoldina termina con él.' },
  at_ferdinand_ii_tyrol: { n: 'Fernando II del Tirol', p: 'Innsbruck, Austria', d: 'Se casó con Philippine Welser, hija de un burgués de Augsburgo, contra todas las reglas de la Casa — y construyó para ella y para su cámara de maravillas el castillo de Ambras, una de las maravillas del Renacimiento; la edad dorada del Tirol termina con él.' },
  at_karl_ii_styria: { n: 'Carlos II de Estiria', p: 'Graz, Austria', d: 'El gobernante pacificador de la Austria Interior: pactos de tolerancia con los estamentos protestantes, una universidad en Graz (1585) — cuyos jesuitas luego educaron a su hijo Fernando II para reconquistar Bohemia para Roma.' },
  at_leopold_v_tyrol: { n: 'Leopoldo V del Austria Anterior', p: 'Innsbruck, Austria', d: 'Obispo de Estrasburgo y Passau que dejó el altar por la corona tirolesa: sostuvo sus pequeñas tierras durante la Guerra de los Treinta Años con ejércitos pequeños y astutos — y casó con Claudia de Médicis para que la línea viviera.' },
  at_ferdinand_karl: { n: 'Fernando Carlos', p: 'Innsbruck, Austria', d: 'El archiduque loco por la ópera: abrió el primer teatro de corte permanente al norte de los Alpes (1654) y empeñó la plata a cantantes italianos — las deudas vaciaron la caja, y el Tirol se deslizó calladamente hacia Viena.' },
  at_sigismund_franz: { n: 'Segismundo Francisco', p: 'Innsbruck, Austria', d: 'Obispo de tres sedes que renunció a todas para casarse y salvar la línea tirolesa — muerto de fiebre días después de su boda a los treinta y nueve: el Tirol vuelve a los Habsburgo de Viena, con él se va su último gobernante independiente.' },
  at_maria_theresa: { n: 'María Teresa', p: 'Viena, Austria', d: 'La única mujer que jamás rigió las tierras Habsburgo: coronada entre los vítores de Hungría a los veintitrés, Silesia perdida ante Federico — luego escuelas, ejército, impuestos y siervos reformados, dieciséis hijos criados: «la suegra de Europa».' },
  at_ferdinand_i_emp: { n: 'Fernando I el Benigno', p: 'Viena, Austria', d: 'El emperador epiléptico que apenas podía firmar su nombre mientras Metternich gobernaba — ambos barridos por las barricadas de Viena en 1848; Fernando abdicó en su sobrino y jardineó felizmente en Praga otros veintisiete años.' },
  at_franz_joseph: { n: 'Francisco José I', p: 'Viena, Austria', d: 'Sesenta y ocho años, el ancla gris de la monarquía: en pie al alba, en el escritorio a las cuatro — perdió toda guerra que libró, una mujer ante la lima de un anarquista, un hermano ante un pelotón mexicano, un heredero en Sarajevo — y siguió reinando: el último monarca premoderno de un imperio moderno.' },
  at_karl_i: { n: 'Carlos I', p: 'Viena, Austria', d: 'El último emperador: heredó la guerra total y probó la paz total — sondeos de paz secretos, un plan federal para sus naciones — demasiado tarde y demasiado débil; exiliado a Madeira, muerto de neumonía a los treinta y cuatro, beatificado por la Iglesia en 2004.' },
});

/* jp translations — Emperors of Japan (added 2026-10-28) */
Object.assign(window.DATA_ES, {
  jp_jimmu: { n: 'Jimmu', p: 'Kashihara, Japón', d: 'Legendario primer emperador, bisnieto de la diosa del sol Amaterasu; Japón fecha su linaje imperial ininterrumpido desde su ascensión — tradicionalmente en el 660 a. C.' },
  jp_suizei: { n: 'Suizei', p: 'Asuka, Japón', d: 'Segundo emperador — el primer príncipe heredero registrado por la tradición; uno de los monarcas tempranos de los que no sobrevive prueba independiente.' },
  jp_annei: { n: 'Annei', p: 'Asuka, Japón', d: 'Tercer emperador legendario; las crónicas solo recuerdan de él su palacio en Kawachi y un reinado de treinta y ocho años.' },
  jp_itoku: { n: 'Itoku', p: 'Asuka, Japón', d: 'Cuarto emperador legendario; recordado sobre todo por su genealogía — su linaje llega ininterrumpido hasta el emperador actual.' },
  jp_kosho: { n: 'Kōshō', p: 'Asuka, Japón', d: 'Quinto emperador legendario; nada de su época puede verificarse — los historiadores sitúan las primeras fechas firmes un milenio después.' },
  jp_koan: { n: 'Kōan', p: 'Asuka, Japón', d: 'Sexto emperador legendario, al que se atribuye un reinado de 101 años — uno de los periodos imposiblemente largos de las primeras listas reales.' },
  jp_korei: { n: 'Kōrei', p: 'Asuka, Japón', d: 'Séptimo emperador legendario; la tradición dice que su madre fue la primera emperatriz consorte nacida fuera del clan real.' },
  jp_kogen: { n: 'Kōgen', p: 'Asuka, Japón', d: 'Octavo de los emperadores “indocumentables”; tras su reinado las crónicas se vuelven notablemente más detalladas.' },
  jp_kaika: { n: 'Kaika', p: 'Asuka, Japón', d: 'Noveno y último de los primeros emperadores cuyos reinados se apoyan solo en la genealogía.' },
  jp_sujin: { n: 'Sujin', p: 'Asuka, Japón', d: 'Semilegendario “primer gobernante del reino”: las crónicas le atribuyen los primeros gobernadores provinciales y la línea del santuario de Ise.' },
  jp_suinin: { n: 'Suinin', p: 'Asuka, Japón', d: 'Bajo él, dice la tradición, el enterramiento de sirvientes vivos fue sustituido por figuras de arcilla haniwa — y se disputó el primer combate de sumo.' },
  jp_keiko: { n: 'Keikō', p: 'Asuka, Japón', d: 'El emperador legendario de la saga de Yamato Takeru — las campañas orientales de su hijo llenan la más antigua epopeya heroica de Japón.' },
  jp_seimu: { n: 'Seimu', p: 'Asuka, Japón', d: 'Emperador legendario al que se atribuye haber organizado por primera vez los grandes clanes de la corte en cargos hereditarios.' },
  jp_chuai: { n: 'Chūai', p: 'Asuka, Japón', d: 'Murió en campaña en Kyūshū; su viuda Jingū condujo luego a la corte por una famosa — y mítica — conquista de Corea.' },
  jp_ojin: { n: 'Ōjin', p: 'Naniwa (Osaka), Japón', d: 'Semilegendario patrón de tejedores, escribas y caballos llegados del continente; tras su muerte fue venerado como Hachiman, dios de la guerra.' },
  jp_nintoku: { n: 'Nintoku', p: 'Naniwa (Osaka), Japón', d: 'Se dice que duerme en el Daisen Kofun — una tumba en forma de cerradura más extensa que la Gran Pirámide de Guiza; la mayor tumba de la Tierra por superficie.' },
  jp_richu: { n: 'Richū', p: 'Kawachi, Japón', d: 'El primero de los magros reinados del siglo V; las crónicas solo conservan de su época disputas sucesorias y emplazamientos de palacios.' },
  jp_hanzei: { n: 'Hanzei', p: 'Kawachi, Japón', d: 'Emperador del siglo V cuyos hermanos lucharon por la sucesión — una ventana a la violenta política cortesana del temprano Yamato.' },
  jp_ingyo: { n: 'Ingyō', p: 'Kawachi, Japón', d: 'Un largo reinado recordado por castigar a los nobles que falsificaron los primeros registros de hogares — y por el caos sucesorio que siguió.' },
  jp_anko: { n: 'Ankō', p: 'Kawachi, Japón', d: 'Asesinado dormido por un noble cuya esposa había reclamado para sí — el primer asesinato imperial registrado de Japón.' },
  jp_yuryaku: { n: 'Yūryaku', p: 'Kawachi, Japón', d: 'Un rey enérgico y temido; los anales chinos quizá lo registran como “rey Bu”, pidiendo respaldo contra sus propios rivales de la corte.' },
  jp_seinei: { n: 'Seinei', p: 'Kawachi, Japón', d: 'Nieto de Yūryaku; cinco años tranquilos — luego el trono pasó a los hijos del tío que Yūryaku había mandado matar.' },
  jp_kenso: { n: 'Kensō', p: 'Kawachi, Japón', d: 'Reinó apenas dos años; los compiladores del siglo VIII solo supieron recordar su palacio y su muerte temprana.' },
  jp_ninken: { n: 'Ninken', p: 'Kawachi, Japón', d: 'Por los matrimonios de sus hijas, su linaje se unió al de Keitai — todo emperador posterior desciende de esa unión.' },
  jp_buretsu: { n: 'Buretsu', p: 'Kawachi, Japón', d: 'Pintado por las crónicas como un cruel rey niño; su muerte sin hijos acabó con la línea directa y llevó a Keitai al trono.' },
  jp_keitai: { n: 'Keitai', p: 'Omi, Japón', d: 'Criado lejos de la corte, en Omi; su ascensión lo convirtió en un segundo fundador de dinastía — todo emperador posterior desciende de él.' },
  jp_ankan: { n: 'Ankan', p: 'Kawachi, Japón', d: 'Reinó cuatro años; los registros se detienen más en sus palacios y obras hidráulicas que en su política.' },
  jp_senka: { n: 'Senka', p: 'Kawachi, Japón', d: 'Su muerte llevó al trono al joven medio hermano Kinmei — el antepasado de todos los emperadores posteriores.' },
  jp_kinmei: { n: 'Kinmei', p: 'Asuka, Japón', d: 'El primer emperador al que los registros permiten fechar con seguridad; el budismo llegó a la corte desde Paekche en su reinado (552).' },
  jp_bidatsu: { n: 'Bidatsu', p: 'Asuka, Japón', d: 'Bajo él se agudizaron las batallas cortesanas por el budismo; la revuelta de Iwai puso a prueba el control de Yamato sobre Kyūshū.' },
  jp_yomei: { n: 'Yōmei', p: 'Asuka, Japón', d: 'Un converso devoto muerto en menos de dos años; la lucha sucesoria que siguió entregó el poder real al clan Soga.' },
  jp_sushun: { n: 'Sushun', p: 'Asuka, Japón', d: 'Puesto en el trono por los Soga y luego muerto por ellos cuando se volvió contra los protectores del budismo.' },
  jp_suiko: { n: 'Suiko', p: 'Asuka, Japón', d: 'La primera emperatriz reinante de Japón; con el regente Shōtoku Taishi envió las primeras embajadas a la China Sui e impulsó el budismo.' },
  jp_jomei: { n: 'Jomei', p: 'Asuka, Japón', d: 'Abrió relaciones oficiales con la China Tang (630) — las primeras misiones kentōshi que remodelarían la diplomacia japonesa.' },
  jp_kogyoku: { n: 'Kōgyoku', p: 'Naniwa (Osaka), Japón', d: 'Segunda emperatriz reinante; su corte fue derrocada por el incidente Isshi de 645, el golpe detrás de las reformas Taika.' },
  jp_kotoku: { n: 'Kōtoku', p: 'Naniwa (Osaka), Japón', d: 'El emperador de la reforma Taika: abolió los estados hereditarios, proclamó un reino centralizado y gobernó desde la nueva capital de Naniwa (Osaka).' },
  jp_saimei: { n: 'Saimei', p: 'Asuka, Japón', d: 'Kōgyoku restaurada bajo un nuevo nombre; murió preparando una flota para rescatar al aliado Paekche de Tang y Silla.' },
  jp_tenji: { n: 'Tenji', p: 'Otsu, Japón', d: 'Tras ser aniquilada la flota japonesa frente a Paekchon (663), ordenó el primer código legal escrito y trasladó la corte a Otsu.' },
  jp_kobun: { n: 'Kōbun', p: 'Otsu, Japón', d: 'Murió en la guerra Jinshin — la pugna sucesoria contra su tío Tenmu que decidió el futuro de la dinastía.' },
  jp_tenmu: { n: 'Tenmu', p: 'Asuka, Japón', d: 'Ganó la guerra Jinshin y reinó con una fuerza sin par; ordenó las primeras historias nacionales y dio al budismo respaldo estatal.' },
  jp_jito: { n: 'Jitō', p: 'Asuka, Japón', d: 'Tercera emperatriz reinante — viuda y heredera política de Tenmu; bajo ella se fundó la capital planificada de Fujiwara-kyō.' },
  jp_monmu: { n: 'Monmu', p: 'Fujiwara-kyō, Japón', d: 'Nieto de Tenmu y Jitō; su reinado lanzó la primera capital planificada al estilo chino y la era del código Taihō.' },
  jp_genmei: { n: 'Genmei', p: 'Nara, Japón', d: 'Cuarta emperatriz reinante; ordenó compilar el Kojiki y trasladó la corte a Heijō-kyō (Nara) en 710.' },
  jp_gensho: { n: 'Genshō', p: 'Nara, Japón', d: 'Quinta emperatriz reinante, una regente estabilizadora entre los reinados de su media hermana y su sobrino; el Estado ritsuryō maduró.' },
  jp_shomu: { n: 'Shōmu', p: 'Nara, Japón', d: 'Ordenó el Buda gigante de bronce del Tōdaiji; su reinado, asolado por la peste, hizo del budismo el escudo del Estado.' },
  jp_koken: { n: 'Kōken', p: 'Nara, Japón', d: 'Sexta emperatriz reinante; consagró el Buda del Tōdaiji y sobrevivió a la revuelta de su primo mientras crecía a su alrededor el poder de un ministro.' },
  jp_junnin: { n: 'Junnin', p: 'Nara, Japón', d: 'Depuesto tras tres años y enviado a morir al exilio en Awaji cuando la emperatriz retirada Kōken recuperó la corte.' },
  jp_shotoku: { n: 'Shōtoku', p: 'Nara, Japón', d: 'El segundo reinado de Kōken; el monje Dōkyō estuvo a una profecía del trono — el gran escándalo del budismo de Nara.' },
  jp_konin: { n: 'Kōnin', p: 'Nara, Japón', d: 'Llevó la línea de Tenji de vuelta al trono; su corte, recelosa de los templos de Nara, comenzó a planear una nueva capital.' },
  jp_kanmu: { n: 'Kanmu', p: 'Kioto, Japón', d: 'Reformador enérgico que trasladó dos veces la capital, hasta acabar en Heian-kyō (794) — comienza la historia de doce siglos de Kioto.' },
  jp_heizei: { n: 'Heizei', p: 'Kioto, Japón', d: 'Abdicó tras tres años e intentó arrastrar la corte de vuelta a Nara — su revuelta fue aplastada por su hermano Saga.' },
  jp_saga: { n: 'Saga', p: 'Kioto, Japón', d: 'Vencedor de la revuelta de 810, emperador poeta y mecenas de Kūkai; su reinado marcó el tono de la refinada cultura Heian.' },
  jp_junna: { n: 'Junna', p: 'Kioto, Japón', d: 'Un emperador frugal y letrado que patrocinó la escuela Shingon de Kūkai y ajustó los presupuestos ritsuryō.' },
  jp_ninmyo: { n: 'Ninmyō', p: 'Kioto, Japón', d: 'El incidente Jōwa (842) de su corte purgó a la vieja guardia — la purga que abrió el camino a la supremacía Fujiwara.' },
  jp_montoku: { n: 'Montoku', p: 'Kioto, Japón', d: 'Un reinado corto y sereno, recordado como el trampolín de Fujiwara Yoshifusa — el siguiente paso: regente de un emperador niño.' },
  jp_seiwa: { n: 'Seiwa', p: 'Kioto, Japón', d: 'Coronado a los ocho años bajo su abuelo Yoshifusa — el primer emperador niño y la primera verdadera regencia Fujiwara.' },
  jp_yozei: { n: 'Yōzei', p: 'Kioto, Japón', d: 'Depuesto a los diecisiete tras una violencia errática; la maniobra necesaria para sustituirlo sacudió las propias reglas de los regentes.' },
  jp_koko: { n: 'Kōkō', p: 'Kioto, Japón', d: 'Elevado a los cincuenta y cinco como un parche dócil; con él el trono se volvió visiblemente botín de Fujiwara Mototsune.' },
  jp_uda: { n: 'Uda', p: 'Kioto, Japón', d: 'Se apoyó en ministros no Fujiwara para contrapesar a los regentes, y luego se retiró pronto a la vida monástica en el Ninna-ji.' },
  jp_daigo: { n: 'Daigo', p: 'Kioto, Japón', d: 'La edad de oro “Engi” — gobierno directo sin regentes; su brillo se agrietó cuando Sugawara Michizane fue desterrado y murió.' },
  jp_suzaku: { n: 'Suzaku', p: 'Kioto, Japón', d: 'Un emperador niño mientras las revueltas de Taira no Masakado y Fujiwara Sumitomo sacudían el reino (era Jōhei–Tengyō).' },
  jp_murakami: { n: 'Murakami', p: 'Kioto, Japón', d: 'El último reinado de gobierno imperial directo — “Tenryaku no chi”, recordado como la cultura Heian en su momento de mayor seguridad.' },
  jp_reizei: { n: 'Reizei', p: 'Kioto, Japón', d: 'Salud quebrantada y furia facciosa: su corto reinado vio el incidente Anna, la purga que fortaleció a Fujiwara Kanemichi.' },
  jp_enyu: { n: 'En’yū', p: 'Kioto, Japón', d: 'Coronado a los once bajo tutela Fujiwara; a su alrededor la regencia se endureció en rutina.' },
  jp_kazan: { n: 'Kazan', p: 'Kioto, Japón', d: 'Capaz y serio, pero superado por Fujiwara Kaneie; abdicó a los diecinueve e hizo votos en el Ninna-ji.' },
  jp_ichijo: { n: 'Ichijō', p: 'Kioto, Japón', d: 'El esplendor Heian en su apogeo: el ascenso de Fujiwara Michinaga, el Libro de la almohada de Sei Shōnagon y el Genji de Murasaki Shikibu en la corte.' },
  jp_sanjo: { n: 'Sanjō', p: 'Kioto, Japón', d: 'Una enfermedad ocular y la presión de Fujiwara Michinaga forzaron su abdicación — sus propios hijos fueron totalmente apartados.' },
  jp_go_ichijo: { n: 'Go-Ichijō', p: 'Kioto, Japón', d: 'Hijo de la hija de Michinaga; con su hermano Go-Suzaku, el trono perteneció a los Fujiwara más que nunca.' },
  jp_go_suzaku: { n: 'Go-Suzaku', p: 'Kioto, Japón', d: 'Un reinado tranquilo bajo Fujiwara Yorimichi; el refinamiento cortesano tocó techo mientras el orden provincial se erosionaba en silencio.' },
  jp_go_reizei: { n: 'Go-Reizei', p: 'Kioto, Japón', d: 'Sin hijos; la disputa sucesoria entre las casas Fujiwara rivales inició el deslizamiento hacia las guerras engendradas en la corte.' },
  jp_go_sanjo: { n: 'Go-Sanjō', p: 'Kioto, Japón', d: 'Primer emperador en 170 años con una madre no Fujiwara; refrenó las fincas que alimentaban la riqueza de los regentes.' },
  jp_shirakawa: { n: 'Shirakawa', p: 'Kioto, Japón', d: 'Abdicó para gobernar por encima de los regentes durante cuatro décadas — su gobierno de claustro (insei) se convirtió en el nuevo centro de poder.' },
  jp_horikawa: { n: 'Horikawa', p: 'Kioto, Japón', d: 'Emperador niño bajo el gobierno de claustro de Shirakawa; la cultura cortesana — poesía, pintura, antologías — siguió floreciendo.' },
  jp_toba: { n: 'Toba', p: 'Kioto, Japón', d: 'Retirado a los dieciséis, dominó durante décadas el insei; sus dos casas armaron las próximas guerras civiles.' },
  jp_sutoku: { n: 'Sutoku', p: 'Kioto, Japón', d: 'Obligado a abdicar; su intento de volver en 1156 desencadenó la guerra Hōgen, y murió desterrado en Sanuki.' },
  jp_konoe: { n: 'Konoe', p: 'Kioto, Japón', d: 'Murió a los veintitrés; la puja por su sucesión encendió al año siguiente la mecha de la guerra Hōgen.' },
  jp_go_shirakawa: { n: 'Go-Shirakawa', p: 'Kioto, Japón', d: 'Ingenió el fatídico compromiso de 1155; como emperador retirado sobrevivió a los Taira y mantuvo en jaque a los primeros shōgun durante décadas.' },
  jp_nijo: { n: 'Nijō', p: 'Kioto, Japón', d: 'Chocó con su padre retirado; la rebelión Heiji (1160) destruyó a Minamoto Yoshitomo y elevó a Taira Kiyomori a la supremacía.' },
  jp_rokujo: { n: 'Rokujō', p: 'Kioto, Japón', d: 'Coronado siendo bebé, depuesto a los tres años por Taira Kiyomori — prueba fehaciente de dónde estaba ya el poder de la corte.' },
  jp_takakura: { n: 'Takakura', p: 'Kioto, Japón', d: 'Yerno de Kiyomori; abdicó para poner en el trono al niño Antoku, de sangre Taira — y el reino se desbordó.' },
  jp_antoku: { n: 'Antoku', p: 'Kioto, Japón', d: 'El emperador niño de los Taira se ahogó en Dan-no-ura (1185) cuando cayó la flota del clan — la leyenda dice que la espada imperial se hundió con él.' },
  jp_go_toba: { n: 'Go-Toba', p: 'Kioto, Japón', d: 'Poeta y mecenas de la segunda antología imperial; luego condujo el último alzamiento armado de la corte contra Kamakura — la guerra Jōkyū (1221) — y murió desterrado en Oki.' },
  jp_tsuchimikado: { n: 'Tsuchimikado', p: 'Kioto, Japón', d: 'Reinó bajo la supervisión de Minamoto y Fujiwara; desterrado tras la fallida guerra Jōkyū de su padre, murió lejos, en Awa.' },
  jp_juntoku: { n: 'Juntoku', p: 'Kioto, Japón', d: 'Se unió a la revuelta de su padre Go-Toba contra los shōgun; desterrado a Sado tras su derrota.' },
  jp_chukyo: { n: 'Chūkyō', p: 'Kioto, Japón', d: 'Entronizado en plena guerra Jōkyū y depuesto en cuestión de meses — la primera destitución de un emperador por los shōgun.' },
  jp_go_horikawa: { n: 'Go-Horikawa', p: 'Kioto, Japón', d: 'Elegido por Kamakura como adulto inofensivo; su reinado asentó el orden cortesano de la posguerra bajo supervisión del bakufu.' },
  jp_shijo: { n: 'Shijō', p: 'Kioto, Japón', d: 'Murió de repente a los diez años; los shōgun aprovecharon la sorpresa para desviar la sucesión hacia la línea Tsuchimikado.' },
  jp_go_saga: { n: 'Go-Saga', p: 'Kioto, Japón', d: 'Sus dos hijos fundaron las líneas rivales Jimyōin y Daikakuji — el pacto de alternancia que luego dividió la corte en dos.' },
  jp_go_fukakusa: { n: 'Go-Fukakusa', p: 'Kioto, Japón', d: 'Emperador de la línea Jimyōin empujado a abdicar joven en favor de su hermano — el resentimiento entre las dos líneas se ahondó.' },
  jp_kameyama: { n: 'Kameyama', p: 'Kioto, Japón', d: 'Emperador Daikakuji durante el primer ataque mongol (1274); las líneas reñían por su heredero y el pacto se endureció.' },
  jp_go_uda: { n: 'Go-Uda', p: 'Kioto, Japón', d: 'Emperador durante la segunda invasión mongol (1281); patriarca de la línea Daikakuji en el pacto de reinados alternos.' },
  jp_fushimi: { n: 'Fushimi', p: 'Kioto, Japón', d: 'Emperador calígrafo de la línea Jimyōin; su linaje cortesano llegó a ser una gran escuela de waka — aun cuando los árbitros del bakufu detentaban el poder real.' },
  jp_go_fushimi: { n: 'Go-Fushimi', p: 'Kioto, Japón', d: 'Reinó tres años bajo el pacto de alternancia; sus protestas airadas por las condiciones ahondaron la querella de las dos líneas.' },
  jp_go_nijo: { n: 'Go-Nijō', p: 'Kioto, Japón', d: 'Intentó el gobierno personal frente a regentes y línea rival por igual; murió joven y de repente a los veintitrés.' },
  jp_hanazono: { n: 'Hanazono', p: 'Kioto, Japón', d: 'Diarista, devoto y artístico; sus memorias sobre su exclusión del poder son un raro autorretrato imperial de la época.' },
  jp_go_daigo: { n: 'Go-Daigo', p: 'Kioto, Japón', d: 'Derrocó el shogunato de Kamakura (1333) y restauró brevemente el gobierno directo; cuando Ashikaga Takauji se volvió en su contra, su resistencia fundó la Corte del Sur.' },
  jp_go_murakami: { n: 'Go-Murakami', p: 'Kioto, Japón', d: 'Emperador de la Corte del Sur, gobernó desde Yoshino y mudó de campamentos; su línea guardó las insignias “verdaderas” a través de décadas de guerra.' },
  jp_chokei: { n: 'Chōkei', p: 'Kioto, Japón', d: 'Emperador del Sur en larga retirada; la causa de Yoshino se apagó cuando las coaliciones guerreras viraron hacia el norte Ashikaga.' },
  jp_go_kameyama: { n: 'Go-Kameyama', p: 'Kioto, Japón', d: 'Último emperador del Sur; entregó las insignias al norte en 1392, “unificando” las cortes en los términos del norte.' },
  jp_kogon: { n: 'Kōgon', p: 'Kioto, Japón', d: 'Instalado por los regentes Hōjō tras el primer alzamiento de Go-Daigo; barrido cuando Go-Daigo volvió en 1333.' },
  jp_komyo: { n: 'Kōmyō', p: 'Kioto, Japón', d: 'Primer emperador del norte de Ashikaga Takauji tras el colapso de la Restauración Kenmu; las insignias legítimas se quedaron en el sur.' },
  jp_suko: { n: 'Sukō', p: 'Kioto, Japón', d: 'Emperador del norte depuesto en pleno Disturbio Kan’ō — la querella de los hermanos Ashikaga que sacudió a ambas cortes.' },
  jp_go_kogon: { n: 'Go-Kōgon', p: 'Kioto, Japón', d: 'Un largo reinado del norte mientras el campo del sur vagaba; la cultura cortesana de Kioto perduró en el bando norteño de la guerra.' },
  jp_go_enyu: { n: 'Go-En’yū', p: 'Kioto, Japón', d: 'Emperador del norte mientras ascendía el shogunato de Yoshimitsu; abdicó en favor del niño Go-Komatsu, cuyo reinado reunificaría las cortes.' },
  jp_go_komatsu: { n: 'Go-Komatsu', p: 'Kioto, Japón', d: 'Último pretendiente del norte y luego emperador único tras la unión de 1392 — primer soberano de la línea imperial reunificada.' },
  jp_shoko: { n: 'Shōkō', p: 'Kioto, Japón', d: 'Murió sin hijos; el trono saltó a una rama colateral, y el pacto de alternancia entre las dos líneas expiró en silencio.' },
  jp_go_hanazono: { n: 'Go-Hanazono', p: 'Kioto, Japón', d: 'Su reinado de treinta y seis años terminó tres años antes de la guerra Ōnin — la última calma antes de que Kioto ardiera.' },
  jp_go_tsuchimikado: { n: 'Go-Tsuchimikado', p: 'Kioto, Japón', d: 'Emperador durante la guerra Ōnin (1467–77) que consumió Kioto; la corte se volvió pobre, provinciana y olvidada.' },
  jp_go_kashiwabara: { n: 'Go-Kashiwabara', p: 'Kioto, Japón', d: 'Tan pobre que su entronización se pospuso veintiún años — el trono imperial en su punto más bajo.' },
  jp_go_nara: { n: 'Go-Nara', p: 'Kioto, Japón', d: 'Reinó a través de las guerras Sengoku; el trono sobrevivió a base de préstamos, regalos y la venta de caligrafía imperial.' },
  jp_ogimachi: { n: 'Ōgimachi', p: 'Kioto, Japón', d: 'Observó a Nobunaga instalarse en Kioto (1568) y sanear las finanzas de la corte; abdicó en favor de Go-Yōzei.' },
  jp_go_yozei: { n: 'Go-Yōzei', p: 'Kioto, Japón', d: 'Entronizado bajo Toyotomi Hideyoshi y apartado por los Tokugawa — su reinado abarca la reunificación de Japón y la conquista de la política por parte de Edo.' },
  jp_go_mizunoo: { n: 'Go-Mizunoo', p: 'Kioto, Japón', d: 'Casado con la hija del shōgun, selló el acuerdo entre corte y bakufu; la disputa de las “túnicas púrpura” por honores de templos lo amargó después.' },
  jp_meisho: { n: 'Meishō', p: 'Kioto, Japón', d: 'Séptima emperatriz reinante — la primera en 850 años; abdicó en favor de su medio hermano Go-Kōmyō.' },
  jp_go_komyo: { n: 'Go-Kōmyō', p: 'Kioto, Japón', d: 'Un joven y fogoso crítico de las pretensiones del shogunato; murió a los veintidós años entre persistentes rumores de envenenamiento.' },
  jp_go_sai: { n: 'Go-Sai', p: 'Kioto, Japón', d: 'Elevado tras la muerte repentina de Go-Kōmyō; abdicó en favor de Reigen, fundando la línea Go-Sai como reserva de la corte.' },
  jp_reigen: { n: 'Reigen', p: 'Kioto, Japón', d: 'Abdicó pronto y pasó treinta años como un formidable emperador retirado — el último en ejercer un peso político real.' },
  jp_higashiyama: { n: 'Higashiyama', p: 'Kioto, Japón', d: 'El esplendor Genroku — las obras de Chikamatsu, los haiku de Bashō — floreció mientras el poder real residía en Edo.' },
  jp_nakamikado: { n: 'Nakamikado', p: 'Kioto, Japón', d: 'Reinó durante las reformas Kyōhō; la dignidad cortesana se recuperó mientras las finanzas del shogunato flaqueaban.' },
  jp_sakuramachi: { n: 'Sakuramachi', p: 'Kioto, Japón', d: 'Con su consejero Kanamori reconstruyó las finanzas de la corte y revivió ceremonias largamente abandonadas — un discreto renacer imperial.' },
  jp_momozono: { n: 'Momozono', p: 'Kioto, Japón', d: 'Murió a los veintiún años; el trono pasó a su hermana — la penúltima emperatriz reinante de Japón.' },
  jp_go_sakuramachi: { n: 'Go-Sakuramachi', p: 'Kioto, Japón', d: 'Décima y última emperatriz reinante; cuidadosa tutora de su joven sobrino y, durante décadas después, sagaz presencia en la corte.' },
  jp_go_momozono: { n: 'Go-Momozono', p: 'Kioto, Japón', d: 'Murió sin hijos a los diecinueve sin designar heredero; la corte improvisó una adopción para mantener la sucesión ininterrumpida.' },
  jp_kokaku: { n: 'Kōkaku', p: 'Kioto, Japón', d: 'Elegido de una rama colateral a los ocho años; un largo reinado vigoroso que reconstruyó el prestigio imperial en vísperas del bakumatsu.' },
  jp_ninko: { n: 'Ninkō', p: 'Kioto, Japón', d: 'Un emperador piadoso y diligente; su reinado vio hambrunas, las reformas Tenpō y los primeros retumbos de la cuestión extranjera.' },
  jp_komei: { n: 'Kōmei', p: 'Kioto, Japón', d: 'Férreamente opuesto a los extranjeros; sus edictos de la corte contra la apertura de Japón avivaron la crisis del bakumatsu — murió de repente a los treinta y seis.' },
  jp_meiji: { n: 'Meiji', p: 'Tokio, Japón', d: 'El emperador restaurado de un milagro modernizador: constitución, ferrocarriles, industria — y victorias sobre China y Rusia.' },
  jp_taisho: { n: 'Taishō', p: 'Tokio, Japón', d: 'Su frágil salud lo mantuvo al margen de la política, desplazando el poder hacia gabinetes de partido — la breve “democracia Taishō” de Japón.' },
  jp_showa: { n: 'Shōwa (Hirohito)', p: 'Tokio, Japón', d: 'Reinó a través de la guerra, la derrota, la ocupación y un milagro económico — sesenta y dos años, el reinado más largo de la historia japonesa.' },
  jp_akihito: { n: 'Akihito', p: 'Tokio, Japón', d: 'El emperador Heisei que hizo del trono una voz para la paz y la memoria; abdicó voluntariamente — el primero en dos siglos.' },
  jp_naruhito: { n: 'Naruhito', p: 'Tokio, Japón', d: 'Emperador de la era Reiwa, historiador de las vías fluviales medievales; la monarquía simbólica avanza hacia una cuarta década de paz.' },
});

/* Roman rulers (189 entries) — 2026-10-29 */
Object.assign(window.DATA_ES, {
  rk_romulus: { n: 'Rómulo', p: 'Roma', d: 'Legendario fundador y primer rey; criado por una loba en el mito romano, dio su nombre a la ciudad, a sus primeras legiones y a sus primeros senadores.' },
  rk_numa: { n: 'Numa Pompilio', p: 'Roma', d: 'El piadoso segundo rey, a quien se atribuyen el calendario de Roma, sus sacerdocios y el templo de Jano cuyas puertas permanecían cerradas en tiempo de paz.' },
  rk_tullus: { n: 'Tulio Hostilio', p: 'Roma', d: 'Belicoso tercer rey que destruyó Alba Longa y trasladó a Roma a su gente — un reinado que las leyendas cierran con peste y rayos.' },
  rk_ancus: { n: 'Anco Marcio', p: 'Roma', d: 'Nieto de Numa; llevó Roma hasta el mar fundando Ostia y tendió sobre el Tíber el primer Puente Sublicio.' },
  rk_tarquinius_priscus: { n: 'Tarquinio Prisco', p: 'Roma', d: 'Quinto rey de origen etrusco; desecó el Foro, inició el Circo Máximo y prometió el gran templo de Júpiter en el Capitolino.' },
  rk_servius_tullius: { n: 'Servio Tulio', p: 'Roma', d: 'Sexto rey y gran reformador — repartió Roma en tribus y centurias, creando el censo, las asambleas y la Muralla Servia.' },
  rk_superbus: { n: 'Tarquinio el Soberbio', p: 'Roma', d: 'El último rey, tiránico; el ultraje de su familia desencadenó la revuelta del 509 a. C. que puso fin a la monarquía y fundó la República.' },
  rr_brutus: { n: 'Lucio Junio Bruto', p: 'Roma', d: 'Primer cónsul de la República; expulsó a los Tarquinios y ejecutó a sus propios hijos por conspirar para su regreso.' },
  rr_publicola: { n: 'Publio Valerio Publícola', p: 'Roma', d: 'Cuatro veces cónsul y amigo del pueblo — sus leyes recortaron las hachas a los lictores y dieron a la joven República su constitución.' },
  rr_cincinnatus: { n: 'Cincinato', p: 'Roma', d: 'Llamado desde el arado para ser dictador, aplastó a los ecuos en dieciséis días y renunció enseguida al poder supremo.' },
  rr_camillus: { n: 'Camilo', p: 'Roma', d: 'Conquistador de Veyes y segundo fundador de Roma — salvó la ciudad después de que los galos la incendiaron en el 390 a. C.' },
  rr_appius_claudius: { n: 'Apio Claudio Ceco', p: 'Roma', d: 'Censor que construyó la Vía Apia y el primer acueducto de Roma; viejo y ciego, convenció al Senado de rechazar la paz con Pirro.' },
  rr_fabius_cunctator: { n: 'Fabio Máximo Cunctator', p: 'Roma', d: 'Dictador después de que Aníbal aplastara a Roma en el Trasimeno; su dilatoria «estrategia fabiana» salvó al Estado — y le atrajo el odio de los audaces.' },
  rr_scipio_africanus: { n: 'Escipión el Africano', p: 'Roma', d: 'El mejor general de Roma; llevó la guerra a África y derrotó a Aníbal en Zama en el 202 a. C., poniendo fin a la Segunda Guerra Púnica.' },
  rr_cato: { n: 'Catón el Viejo', p: 'Roma', d: 'Censor de la severa virtud romana de antaño; cerraba cada discurso con «Cartago debe ser destruida» — y llegó la Tercera Guerra Púnica.' },
  rr_tiberius_gracchus: { n: 'Tiberio Graco', p: 'Roma', d: 'Tribuno que intentó dar tierras públicas a los pobres; apaleado hasta la muerte por los senadores en el Foro — la primera sangre política de la República en generaciones.' },
  rr_gaius_gracchus: { n: 'Gayo Graco', p: 'Roma', d: 'Hermano menor y tribuno radical del trigo público y de la ciudadanía ampliada; perseguido y asesinado cuando el Senato contraatacó.' },
  rr_marius: { n: 'Gayo Mario', p: 'Roma', d: 'Siete veces cónsul; abrió las legiones a los hombres sin tierra y destruyó a cimbrios y teutones — pero su riña con Sila desangró Roma.' },
  rr_sulla: { n: 'Sila', p: 'Roma', d: 'Primer general en marchar sobre la propia Roma; como dictador masacró a enemigos mediante listas de proscripción y luego — asombrosamente — devolvió el poder.' },
  rr_pompey: { n: 'Pompeyo el Grande', p: 'Roma', d: 'Barrió a los piratas y conquistó Oriente, tres veces cónsul, gran rival de César — asesinado en una playa egipcia tras Farsalia.' },
  rr_crassus: { n: 'Marco Licinio Craso', p: 'Roma', d: 'El hombre más rico de Roma y tercero del primer triunvirato; marchó contra Partia en busca de gloria y murió en Carras, con sus legiones perdidas en el desierto.' },
  rr_cicero: { n: 'Cicerón', p: 'Roma', d: 'Cónsul que desenmascaró la conjuración de Catilina con sus discursos; el mayor orador de Roma y una voz perdurable por la libertad constitucional.' },
  rr_m_brutus: { n: 'Marco Junio Bruto', p: 'Roma', d: 'Amigo de César y último defensor de la República — líder de los Liberadores que mataron al dictador, derrotado y muerto en Filipos.' },
  rr_cassius: { n: 'Gayo Casio Longino', p: 'Roma', d: 'El cerebro operativo de los idus de marzo; alzó Oriente contra los triunviros y murió en Filipos, engañado por un falso informe.' },
  rr_lepidus: { n: 'Lépido', p: 'Roma', d: 'Tercero del Segundo Triunvirato, siempre el socio menor; apartado por Octavio y dejado para acabar sus días como Pontífice Máximo.' },
  rr_antony: { n: 'Marco Antonio', p: 'Roma', d: 'Brillante general y triunviro, mano derecha de César; su alianza — y su romance — con Cleopatra acabaron en Accio y en la espada de un suicida.' },
  rr_octavian: { n: 'Octavio', p: 'Roma', d: 'Heredero de César a los dieciocho años que sobrevivió y venció a todos sus rivales; en el 27 a. C. el Senado lo renombró Augusto — una monarquía con ropaje republicano.' },
  re_augustus: { n: 'Augusto', p: 'Roma', d: 'Primer emperador; conservó la cáscara de la República gobernándolo todo él mismo — cuarenta años de paz que encontraron Roma de ladrillo y la dejaron de mármol.' },
  re_tiberius: { n: 'Tiberio', p: 'Roma', d: 'Emperador reticente, brillante y agrio que se retiró a Capri, dejando que el pretoriano Sejano aterrorizara Roma con procesos por traición.' },
  re_caligula: { n: 'Calígula', p: 'Roma', d: 'Joven emperador que empezó adorado y acabó monstruoso — las fuentes le atribuyen crueldad, oro dilapidado y planes de hacer cónsul a su caballo.' },
  re_claudius: { n: 'Claudio', p: 'Roma', d: 'El erudito tartamudo que nadie esperaba; conquistó Britania, desecó el lago Fucino y dirigió el imperio con una competencia inesperada.' },
  re_nero: { n: 'Nerón', p: 'Roma', d: 'Emperador matricida con alma de actor; Roma ardió en el 64, culpó a los cristianos, construyó su Casa Dorada — y el Senado lo declaró enemigo público.' },
  re_galba: { n: 'Galba', p: 'Roma', d: 'Comienza el Año de los Cuatro Emperadores: un austero viejo general, asesinado por los pretorianos tras siete meses de reformas avaras.' },
  re_otho: { n: 'Otón', p: 'Roma', d: 'Favorito de los pretorianos que reinó noventa y cinco días, perdió Bedriaco ante Vitelio — y se mató para que la guerra civil no se agravara.' },
  re_vitellius: { n: 'Vitelio', p: 'Roma', d: 'Glotón vencedor del primer Bedriaco; ocho meses después los ejércitos flavios incendiaron Cremona y lo arrastraron por Roma hasta la muerte.' },
  re_vespasian: { n: 'Vespasiano', p: 'Roma', d: 'El astuto general salido del comercio de mulas que acabó con la guerra civil, inició el Coliseo — e impuso un impuesto a la orina para llenar de nuevo el tesoro.' },
  re_titus: { n: 'Tito', p: 'Roma', d: 'Emperador amado de los desastres: terminó el Coliseo, luego enterró a los muertos del Vesubio, luchó contra el gran incendio del 80 — y murió demasiado pronto.' },
  re_domitian: { n: 'Domiciano', p: 'Roma', d: 'Autócrata eficiente y terror de la aristocracia; reconstruyó Roma, fortificó la línea Rin–Danubio y murió en una conjura de palacio.' },
  re_nerva: { n: 'Nerva', p: 'Roma', d: 'Anciano senador elevado para restaurar la libertad tras Domiciano; sin hijos, adoptó a Trajano y abrió la era de los Cinco Buenos Emperadores.' },
  re_trajan: { n: 'Trajano', p: 'Roma', d: '«El mejor de los príncipes» — bajo él Roma alcanzó su máxima extensión, de las minas de oro de Dacia al golfo Pérsico, y el Foro obtuvo su columna.' },
  re_hadrian: { n: 'Adriano', p: 'Roma', d: 'Emperador viajero y constructor que consolidó las fronteras — muro de Adriano, Panteón — y renombró Judea tras aplastar su revuelta.' },
  re_antoninus_pius: { n: 'Antonino Pío', p: 'Roma', d: 'El reinado más sereno de la historia romana — veintitrés años sin guerra importante, el imperio en su mayor prosperidad, la Muralla de Antonino en su borde.' },
  re_marcus_aurelius: { n: 'Marco Aurelio', p: 'Roma', d: 'El filósofo en el trono; escribió las Meditaciones en el campamento mientras la peste y los invasores marcomanos castigaban la frontera del Danubio.' },
  re_lucius_verus: { n: 'Lucio Vero', p: 'Roma', d: 'Coemperador con Marco Aurelio; ganó la guerra parta mientras sus generales hacían el trabajo, y murió de peste camino a casa.' },
  re_commodus: { n: 'Cómodo', p: 'Roma', d: 'Hijo de Marco Aurelio y pesadilla de Roma; combatía como gladiador en su propia arena, renombró los meses por sí mismo — y lo estranguló un luchador.' },
  re_pertinax: { n: 'Pertinax', p: 'Roma', d: 'Severo hijo de un liberto; los pretorianos — ya vendidos a Didio Juliano — lo mataron tras ochenta y siete días de disciplina.' },
  re_didius_julianus: { n: 'Didio Juliano', p: 'Roma', d: 'Compró el imperio en la subasta de los pretorianos — y lo perdió en nueve semanas a manos de Septimio Severo, que marchaba desde el Danubio.' },
  re_septimius_severus: { n: 'Septimio Severo', p: 'Roma', d: 'Emperador soldado nacido en África, fundador de la dinastía severiana; su consejo en el lecho de muerte — enriqueced a los soldados, despreciad todo lo demás.' },
  re_caracalla: { n: 'Caracalla', p: 'Roma', d: 'Asesino de su hermano Geta y de su propio prefecto del pretorio; su edicto del 212 hizo ciudadanos romanos a todos los habitantes libres del imperio.' },
  re_geta: { n: 'Geta', p: 'Roma', d: 'Hermano de Caracalla y co-Augusto durante dos años; asesinado en brazos de su madre, con la memoria condenada y el nombre cincelado fuera de los monumentos.' },
  re_macrinus: { n: 'Macrino', p: 'Antioquía', d: 'Prefecto del pretorio que tomó la púrpura tras el asesinato de Caracalla — el primer emperador fuera del orden senatorial; catorce meses después estaba muerto.' },
  re_elagabalus: { n: 'Elagábalo', p: 'Roma', d: 'Emperador adolescente, sacerdote del dios solar sirio El-Gabal; sus escándalos disgustaron tanto a los pretorianos que trucidaron a él y a su madre en el campamento.' },
  re_severus_alexander: { n: 'Severo Alejandro', p: 'Roma', d: 'Gobernado por su madre Julia Mamea; dulce, aconsejado por el gran jurista Ulpiano — y asesinado en Maguncia cuando el ejército quiso un hombre más duro.' },
  re_maximinus_thrax: { n: 'Maximino el Tracio', p: 'Roma', d: 'Gigantesco general campesino, primero de los emperadores soldado; tres años de guerra sin fin antes de que sus propias tropas lo mataran a las afueras de Aquileya.' },
  re_gordian_i: { n: 'Gordiano I', p: 'Cartago', d: 'Rico procónsul proclamado emperador en África contra Maximino; tras treinta y seis días, derrotado — se ahorcó con su fajín.' },
  re_gordian_ii: { n: 'Gordiano II', p: 'Cartago', d: 'Hijo y compañero de Gordiano I; cayó en la batalla ante Cartago, y su padre lo siguió a la muerte a las pocas horas.' },
  re_pupienus: { n: 'Pupieno', p: 'Roma', d: 'Emperador senador elegido por el Senado para hacer frente a Maximino; el ejército del tirano ya lo había matado — luego los pretorianos mataron también a Pupieno.' },
  re_balbinus: { n: 'Balbino', p: 'Roma', d: 'El coemperador de Pupieno, siempre en disputas, elegido para apaciguar al pueblo; ambos fueron arrastrados fuera del palacio y matados por los pretorianos.' },
  re_gordian_iii: { n: 'Gordiano III', p: 'Roma', d: 'Nieto de trece años del primer Gordiano; marchó contra Persia y venció en Resaena — y fue apartado por su propio prefecto Filipo.' },
  re_philip_arab: { n: 'Filipo el Árabe', p: 'Roma', d: 'Hizo la paz con Persia y celebró el milésimo cumpleaños de Roma con espléndidos juegos — luego cayó ante Decio cerca de Verona.' },
  re_decius: { n: 'Decio', p: 'Roma', d: 'Ordenó la persecución de los cristianos en todo el imperio; él y su hijo murieron combatiendo a los godos en Abrito, los primeros emperadores muertos a manos de bárbaros.' },
  re_trebonianus_gallus: { n: 'Treboniano Galo', p: 'Roma', d: 'Compró la paz a los godos con oro, la peste llegó igualmente — y sus propios soldados lo entregaron a Emiliano en Interamna.' },
  re_aemilian: { n: 'Emiliano', p: 'Roma', d: 'Tres meses de imperio; proclamado por rechazar a los godos, asesinado por sus propios hombres cuando Valeriano marchó desde el Rin.' },
  re_valerian: { n: 'Valeriano', p: 'Roma', d: 'El único emperador capturado jamás en batalla — tomado vivo en Edesa por el rey persa Sapor I, de quien siguió siendo prisionero hasta su muerte.' },
  re_gallienus: { n: 'Galieno', p: 'Roma', d: 'Corregente mientras su padre era cautivo, convertido en brillante improvisador de destino sellado — sostuvo el núcleo mientras Galia y Palmira se desgajaban, y luego cayó a manos de sus propios oficiales.' },
  re_claudius_gothicus: { n: 'Claudio el Gótico', p: 'Roma', d: 'General de caballería que aplastó a los godos en Naissus; la peste se lo llevó antes de que pudiera reunificar el imperio hecho añicos.' },
  re_quintillus: { n: 'Quintilo', p: 'Roma', d: 'Hermano de Claudio, elegido por el Senado contra la voluntad del ejército; un prudente suicidio a los pocos días resolvió la disputa.' },
  re_aurelian: { n: 'Aureliano', p: 'Roma', d: 'Restaurador del mundo — recuperó a Zenobia de Palmira y el Imperio galo, construyó la última muralla de Roma y murió en la conjura de sus oficiales.' },
  re_tacitus: { n: 'Tacito', p: 'Roma', d: 'Un senador de setenta y cinco años que el ejército eligió tras un interregno; murió en Tiana, camino del este contra godos y persas.' },
  re_florianus: { n: 'Floriano', p: 'Roma', d: 'Hermanastro de Tacito; los ejércitos de Oriente lo rechazaron y proclamaron a Probo — semanas después sus propios hombres lo mataron en Tarso.' },
  re_probus: { n: 'Probo', p: 'Roma', d: 'Restaurador de las fronteras del Rin y del Danubio que plantó viñedos por el valle del Danubio; sus soldados, puestos a trabajos de drenaje, lo mataron en Sirmio.' },
  re_carus: { n: 'Caro', p: 'Roma', d: 'Prefecto del pretorio convertido en emperador; venció a cuados y sármatas y luego murió — la leyenda dice que por un rayo — antes de tomar Ctesifonte.' },
  re_carinus: { n: 'Carino', p: 'Roma', d: 'Hijo mayor de Caro, lujurioso y cruel; ganó la batalla del Margus — y allí lo mató un tribuno cuya esposa había seducido.' },
  re_numerian: { n: 'Numeriano', p: 'Roma', d: 'Hijo menor de Caro, poeta y orador; su suegro Aper fue hallado con el cadáver del joven — Diocleciano lo mató ante el ejército.' },
  re_diocletian: { n: 'Diocleciano', p: 'Nicomedia', d: 'El gran reorganizador: tetrarquía, provincias duplicadas, edictos de precios, la Gran Persecución — y luego el primer emperador en retirarse por voluntad propia, a cultivar coles en Split.' },
  re_maximian: { n: 'Maximiano', p: 'Milán', d: 'El rudo co-Augusto de Diocleciano en Occidente, combatiendo bandidos, britanos y usurpadores; obligado a abdicar con su colega, intrigó hasta el final.' },
  re_constantius_chlorus: { n: 'Constancio Cloro', p: 'Tréveris', d: 'El césar occidental de la tetrarquía, luego augusto; recuperó Britania de manos de Allecto y murió en York tras nombrar heredero a su hijo Constantino.' },
  re_galerius: { n: 'Galerio', p: 'Sirmio', d: 'Arquitecto de la Gran Persecución; murió entre terribles dolores y la terminó por edicto en el 311 — un cambio que los cristianos recordaron con estupor.' },
  re_severus_ii: { n: 'Severo II', p: 'Milán', d: 'El césar de Constancio promovido a augusto; la rebelión de Majencio y la traición de Maximiano lo entregaron para su ejecución a las afueras de Roma.' },
  re_maxentius: { n: 'Majencio', p: 'Roma', d: 'El usurpador del Tíber que se ahogó en él — su ejército se quebró en el Puente Milvio ante el signo de la cruz de Constantino.' },
  re_maximinus_daza: { n: 'Maximino Daya', p: 'Antioquía', d: 'El más feroz de los perseguidores; el sobrino de Galerio combatió a Licinio hasta el Tauro, y luego murió de enfermedad en Tarso con su persecución revocada.' },
  re_constantine_i: { n: 'Constantino el Grande', p: 'Constantinopla', d: 'Hijo de Constancio; unificó el imperio tras el Puente Milvio, legalizó el cristianismo y fundó Constantinopla como una nueva Roma.' },
  re_licinius: { n: 'Licinio', p: 'Sirmio', d: 'Cuñado de Constantino y su último rival; derrotado en Crisópolis, depuesto pese a la promesa de salvamento — y ejecutado en menos de un año.' },
  re_constantine_ii: { n: 'Constantino II', p: 'Tréveris', d: 'Hijo mayor de Constantino; exigió a sus hermanos una parte mayor de Occidente y murió en una emboscada en Aquileya, a los treinta y tres años.' },
  re_constans: { n: 'Constante', p: 'Milán', d: 'Hijo menor de Constantino, vencedor sobre su hermano Constantino II; se enemistó con el ejército por sus favoritos y murió huyendo del golpe de Magnencio.' },
  re_constantius_ii: { n: 'Constancio II', p: 'Constantinopla', d: 'El hijo del medio, suspicaz y de largo reinado, arriano; combatió a Persia y a una docena de usurpadores, y murió de fiebre camino de enfrentarse a Juliano.' },
  re_julian: { n: 'Juliano el Apóstata', p: 'Antioquía', d: 'Emperador filósofo que intentó revivir a los viejos dioses y recortar el despilfarro de la corte; murió de una herida en la campaña persa, a los treinta y un años.' },
  re_jovian: { n: 'Joviano', p: 'Ancira', d: 'Elegido en la retirada de Ctesifonte; compró la salida del ejército con territorio persa y murió ocho meses después en Ancira, en la casa paterna.' },
  re_valentinian_i: { n: 'Valentiniano I', p: 'Tréveris', d: 'Soldado panonio que repartió el imperio con su hermano Valente; defendió el Rin con ferocidad y murió de rabia, gritando a los enviados.' },
  re_valens: { n: 'Valente', p: 'Constantinopla', d: 'Emperador de Oriente bajo su hermano; dejó cruzar el Danubio a los refugiados godos, los combatió medio desarmado — y ardió vivo en Adrianópolis.' },
  re_gratian: { n: 'Graciano', p: 'Tréveris', d: 'Hijo dotado de Valentiniano I, asociado al poder desde la infancia; abandonó el título pagano de Pontifex Maximus — y su ejército lo abandonó por el usurpador Máximo.' },
  re_valentinian_ii: { n: 'Valentiniano II', p: 'Milán', d: 'Emperador niño manejado primero por su madre Justina, luego por Teodosio; apareció ahorcado en Vienne — Ambrosio predicó su funeral.' },
  re_theodosius_i: { n: 'Teodosio el Grande', p: 'Constantinopla', d: 'Último emperador en gobernar ambas mitades; hizo del cristianismo niceno la religión de Estado y dejó a sus hijos Oriente y Occidente — una división que nunca cicatrizó.' },
  re_honorius: { n: 'Honorio', p: 'Rávena', d: 'El emperador que no hacía nada, de Rávena, que mandó matar a Estilicón; Alarico saqueó Roma en el 410 mientras, dice la pulla, cuidaba de sus gallinas.' },
  re_constantius_iii: { n: 'Constancio III', p: 'Rávena', d: 'El general que apartó a Occidente del abismo — usurpadores aplastados, godos asentados en la Galia — coemperador durante siete meses antes de que la pleuresía se lo llevara.' },
  re_joannes: { n: 'Juan', p: 'Rávena', d: 'Primer notario hecho emperador a la muerte de Honorio; Aecio llegó con los hunos demasiado tarde para salvarlo del ejército oriental de Gala Placidia.' },
  re_valentinian_iii: { n: 'Valentiniano III', p: 'Roma', d: 'El niño de Gala Placidia en el trono de Occidente; perdió África ante los vándalos, mató a Aecio con sus propias manos — y fue derribado por los hombres de Aecio.' },
  re_petronius_maximus: { n: 'Petronio Máximo', p: 'Roma', d: 'Senador detrás del asesinato de Aecio y del de Valentiniano; dos meses de poder que acabaron con él apedreado por la multitud romana mientras la flota vándala se cerraba sobre la ciudad.' },
  re_avitus: { n: 'Avito', p: 'Arlés', d: 'Aristócrata galorromano hecho emperador con ayuda visigoda; Ricimero lo depuso, y acabó sus días como obispo de Piacenza.' },
  re_majorian: { n: 'Mayoriano', p: 'Rávena', d: 'El último emperador de Occidente que lo intentó de verdad — leyes contra el abuso fiscal aún citadas, una flota de reconquista perdida en Cartagena; Ricimero mandó despojarlo y decapitarlo.' },
  re_libius_severus: { n: 'Libio Severo', p: 'Rávena', d: 'El emperador sombra de Ricimero, nunca reconocido por Oriente; murió en Roma — envenenado, decía el rumor, por su propio protector.' },
  re_anthemius: { n: 'Antemio', p: 'Roma', d: 'La elección de Oriente, un griego de una gran familia de arquitectos; su campaña contra los vándalos fracasó, y Ricimero lo sitió y lo mató.' },
  re_olybrius: { n: 'Olibrio', p: 'Roma', d: 'Emparentado con la dinastía teodosiana por matrimonio, la elección de Ricimero como emperador; siete meses tranquilos — luego la hidropesía, con el imperio de Occidente a cuatro años de extinguirse.' },
  re_glycerius: { n: 'Glicerio', p: 'Rávena', d: 'El nombrado por Gundebaldo tras la muerte de Ricimero; Julio Nepote desembarcó en Portus, el ejército desertó — y Glicerio acabó como obispo de Salona.' },
  re_julius_nepos: { n: 'Julio Nepote', p: 'Salona', d: 'El emperador de Occidente legítimo a ojos de Oriente; Orestes lo persiguió hasta Dalmacia en el 475 — mantuvo Salona hasta que su propio mayordomo lo apuñaló.' },
  re_romulus_augustulus: { n: 'Rómulo Augústulo', p: 'Rávena', d: 'El niño «pequeño Augusto» — último emperador de Occidente; Odoacro lo pensionó en Campania, y el imperio de Occidente sencillamente se detuvo.' },
  bz_arcadius: { n: 'Arcadio', p: 'Constantinopla', d: 'Primer emperador de la mitad oriental hecha permanente — un joven débil guiado por ministros como Rufino y el eunuco Eutropio mientras Occidente se desmoronaba.' },
  bz_theodosius_ii: { n: 'Teodosio II', p: 'Constantinopla', d: 'Cuarenta y dos años del emperador estudioso, cuyo Código teodosiano de leyes y cuyas Murallas teodosianas de Constantinopla lo sobrevivieron un milenio.' },
  bz_marcian: { n: 'Marciano', p: 'Constantinopla', d: 'Emperador soldado casado con Pulqueria; se negó a pagar tributo a Atila — oro para sus soldados, nada para el enemigo — y bajo él se reunió el Concilio de Calcedonia.' },
  bz_leo_i: { n: 'León I', p: 'Constantinopla', d: 'Primer emperador coronado por el Patriarca; rompió con reclutas isáuricos el dominio de los godos sobre el ejército — y la gran armada contra la Cartago vándala se hundió frente al Cabo Bon.' },
  bz_leo_ii: { n: 'León II', p: 'Constantinopla', d: 'Nieto de León I y Zenón, coronado a los seis años, muerto de fiebre a los siete — el trono pasó a su padre Zenón.' },
  bz_zeno: { n: 'Zenón', p: 'Constantinopla', d: 'Emperador isáurico dos veces al borde de ser derribado — por Basilisco, luego por una revuelta; su Henotikon intentó cerrar la disputa eclesiástica, y el imperio de Occidente se extinguió en su reinado.' },
  bz_basiliscus: { n: 'Basilisco', p: 'Constantinopla', d: 'Usurpador, hermano de la emperatriz Verina — el almirante que perdió la armada del Cabo Bon; sus edictos monofisitas provocaron disturbios y Zenón regresó sin oposición.' },
  bz_anastasius_i: { n: 'Anastasio I', p: 'Constantinopla', d: 'Cuidadoso genio fiscal — 320.000 libras de oro en reserva, el Muro Largo construido, la moneda reformada; las multitudes se amotinaron por sus simpatías monofisitas.' },
  bz_justin_i: { n: 'Justino I', p: 'Constantinopla', d: 'Guardia campesino ilirio elevado por el ejército; sanó el cisma acaciano con Roma y despejó el camino para su sobrino Justiniano.' },
  bz_justinian_i: { n: 'Justiniano I', p: 'Constantinopla', d: 'El último emperador de lengua latina y el más infatigable: reconquista de África e Italia, el Corpus Iuris, Santa Sofía — y sobrevivió al motín de Nika y a la peste.' },
  bz_justin_ii: { n: 'Justino II', p: 'Constantinopla', d: 'Sobrino de Justiniano; sus guerras persa e italiana desangraron el tesoro, su mente se quebró — y nombró heredero a Tiberio para ahorrar al imperio una guerra de sucesión.' },
  bz_tiberius_ii: { n: 'Tiberio II', p: 'Constantinopla', d: 'El emperador generoso — repartió el tesoro acumulado de Justiniano en pagos y socorros a los pobres; Persia y los ávaros tomaron provincias a cambio.' },
  bz_maurice: { n: 'Mauricio', p: 'Constantinopla', d: 'Soldado erudito que ganó la guerra persa respaldando a Cosroes II y escribió el Strategikon — luego fue ejecutado por Focas con sus seis hijos ante sus ojos.' },
  bz_phocas: { n: 'Focas', p: 'Constantinopla', d: 'El centurión cuyo motín abrió el siglo más oscuro del imperio; su reinado de terror terminó cuando la flota de Heraclio apareció frente a Constantinopla.' },
  bz_heraclius: { n: 'Heraclio', p: 'Constantinopla', d: 'Arrancó al imperio de la puerta de la muerte — Ctesifonte tomada, la Vera Cruz restituida — y luego vivió para ver a Siria, Egipto y Armenia caer ante los árabes.' },
  bz_constantine_iii: { n: 'Constantino III', p: 'Constantinopla', d: 'Hijo mayor de Heraclio; reinó cuatro meses, muriendo de tuberculosis — o de veneno, sospechó la chusma — con la facción de Martina al acecho.' },
  bz_heraklonas: { n: 'Heraclonas', p: 'Constantinopla', d: 'Hijo de Heraclio y de su sobrina Martina; el motín de las mutilaciones de septiembre del 641 lo depuso — con la nariz cortada — y la línea terminó.' },
  bz_constans_ii: { n: 'Constante II', p: 'Constantinopla', d: 'Nieto de Heraclio; combatió a las flotas árabes en la batalla de los Mástiles, discutió con la Iglesia, se trasladó a Siracusa — y acabaron con él a golpes en su baño.' },
  bz_constantine_iv: { n: 'Constantino IV', p: 'Constantinopla', d: 'Rompió el primer asedio árabe de Constantinopla con fuego griego en el 678 y cerró la controversia monotelita en el Sexto Concilio Ecuménico.' },
  bz_justinian_ii: { n: 'Justiniano II', p: 'Constantinopla', d: 'Hijo altivo de Constantino IV, derrotado en Sebastópolis y depuesto con la nariz cortada — volvió del exilio en el 705 para un reinado de pura venganza.' },
  bz_leontios: { n: 'Leocio', p: 'Constantinopla', d: 'General convertido en usurpador tras Sebastópolis; tres años de derrotas árabes, luego un golpe, un corte de nariz — y en el 706 el regreso de Justiniano II lo acabó.' },
  bz_tiberios_iii: { n: 'Tiberio III', p: 'Constantinopla', d: 'Almirante de la flota cibirreota que tomó el trono; sostuvo bien la frontera oriental — hasta que Justiniano II navegó de regreso con ayuda búlgara.' },
  bz_philippikos: { n: 'Filípico', p: 'Constantinopla', d: 'Decapitó a Justiniano II en el hipódromo, reavivó la disputa monotelita — y perdió Armenia ante los árabes antes de que un golpe que lo cegara lo apartara.' },
  bz_anastasios_ii: { n: 'Anastasio II', p: 'Constantinopla', d: 'Se preparó con severidad para el inminente asedio árabe — graneros, una flota, hasta una trama de espionaje contra el Califa; sus propias tropas se amotinaron y eligieron a un monje.' },
  bz_theodosios_iii: { n: 'Teodosio III', p: 'Constantinopla', d: 'El reacio funcionario de impuestos que los amotinados coronaron; dos años de avance árabe después renunció y se retiró a un monasterio, dejando a León III pelear el asedio.' },
  bz_leo_iii: { n: 'León III', p: 'Constantinopla', d: 'Quebró el asedio árabe de un año, en 717–718, con fuego griego y aliados búlgaros, recodificó la ley — e inició la iconoclastia.' },
  bz_constantine_v: { n: 'Constantino V', p: 'Constantinopla', d: 'Brillante y brutal soldado que quebró a los búlgaros en Anquialo y reconstruyó los temas — y convirtió la iconoclastia en una purga de los veneradores de iconos.' },
  bz_artabasdos: { n: 'Artabasdo', p: 'Constantinopla', d: 'Cuñado de Constantino V, que sostuvo la capital dieciséis meses y restauró los iconos; cegado junto a sus hijos cuando la guerra civil se le torció.' },
  bz_leo_iv: { n: 'León IV', p: 'Constantinopla', d: 'Hijo de Constantino V y de la hija del jan de los jázaros; moderado con los iconos, frenó a los abasidas y dejó el imperio a su hijo de diez años.' },
  bz_constantine_vi: { n: 'Constantino VI', p: 'Constantinopla', d: 'El emperador niño bajo la regencia de su madre; tras fracasar contra búlgaros y árabes, y volverse contra Irene, sus agentes lo cegaron en su propia alcoba.' },
  bz_irene: { n: 'Irene de Atenas', p: 'Constantinopla', d: 'La primera mujer en gobernar sola el imperio; restauró los iconos en el II Concilio de Nicea y murió exiliada en Lesbos cuando sus ministros coronaron a Nicéforo.' },
  bz_nikephoros_i: { n: 'Nicéforo I', p: 'Constantinopla', d: 'Emperador logoteta de puño apretado; reconstruyó las finanzas, perdió batallas ante los árabes — y ante los búlgaros de Krum, cuyo jan hizo de su cráneo una copa para beber.' },
  bz_staurakios: { n: 'Estauracio', p: 'Constantinopla', d: 'Sacado del desastre de Pliska con una herida mortal; diez semanas de reinado nominal — luego coronó a su cuñado Miguel I y tomó el hábito.' },
  bz_michael_i: { n: 'Miguel I', p: 'Constantinopla', d: 'Pío, fastuoso, infortunado; su ejército huyó de Krum en Versinikia, las tropas aclamaron a León el Armenio — y los hijos de Miguel fueron castrados y encerrados en un monasterio.' },
  bz_leo_v: { n: 'León V', p: 'Constantinopla', d: 'Venció a los búlgaros en Mesembria y compró la paz, luego relanzó la iconoclastia — y fue despedazado en los maitines de Navidad por los hombres en quienes confiaba.' },
  bz_michael_ii: { n: 'Miguel II', p: 'Constantinopla', d: 'El fundador tartamudo de la dinastía amoriana; quemó fuera de la capital el asedio de un año de Tomás el Eslavo, perdió Creta y Sicilia — y dejó el compromiso iconoclasta a su hijo.' },
  bz_theophilos: { n: 'Teófilo', p: 'Constantinopla', d: 'El último iconoclasta — serio, amante de la justicia, constructor de palacios; su Amorio cayó ante los ejércitos del Califa en el 838, la herida de la década.' },
  bz_michael_iii: { n: 'Miguel III', p: 'Constantinopla', d: 'La iconoclastia terminó bajo su madre Teodora; combatió a los abasidas, envió a Cirilo y Metodio a los eslavos — y crió al macedonio Basilio que lo mató.' },
  bz_basil_i: { n: 'Basilio I', p: 'Constantinopla', d: 'Campesino, domador de caballos, asesino de su protector; recodificó la ley en la Basilika y murió en una cacería — posiblemente asesinado por la gente de León VI.' },
  bz_leo_vi: { n: 'León VI', p: 'Constantinopla', d: 'El Sabio — cuatro matrimonios por un hijo hicieron escándalo de la Tetragamia; perdió la guerra búlgara ante Simeón, escribió homilías y manuales, y coronó el siglo macedonio.' },
  bz_alexander: { n: 'Alejandro', p: 'Constantinopla', d: 'El ocioso coemperador de León durante un año; derribó los monumentos de su hermano, sacrificó a una estatua de Zeus — y murió de disentería tras un partido de tzykanion.' },
  bz_constantine_vii: { n: 'Constantino VII', p: 'Constantinopla', d: 'El emperador erudito, nacido en la púrpura; las regencias lo hicieron esperar treinta y dos años, pero su De Administrando y su De Ceremoniis se volvieron la memoria de Bizancio.' },
  bz_romanos_i: { n: 'Romano I', p: 'Constantinopla', d: 'Almirante que se hizo emperador sénior sobre el joven Constantino VII — veinticuatro años de buen juicio, derrotas de Simeón, leyes agrarias — hasta que sus hijos lo traicionaron.' },
  bz_romanos_ii: { n: 'Romano II', p: 'Constantinopla', d: 'El hijo hermoso y amante del placer del erudito; Nicéforo Focas le tomó Creta, y murió a los veinticuatro años — se sospecha veneno.' },
  bz_nikephoros_ii: { n: 'Nicéforo II', p: 'Constantinopla', d: 'El pálido conquistador de rostro de monje, de Creta y Antioquía; se casó con Teófano y tasó a la Iglesia — y fue asesinado en su propia alcoba por Tzimisces y la emperatriz.' },
  bz_john_i_tzimiskes: { n: 'Juan I Tzimisces', p: 'Constantinopla', d: 'El bellísimo general de pequeña estatura; aplastó a los rus de Sviatoslav en Silistra y marchó hasta las murallas de Bagdad — muriendo de tifo en la marcha oriental.' },
  bz_basil_ii: { n: 'Basilio II el Matabúlgaros', p: 'Constantinopla', d: 'Los cuarenta y nueve años del Matabúlgaros fueron la cúspide del imperio: Bulgaria anexionada, los temas fuertes, 200.000 libras en reserva — y ningún heredero, la catástrofe silenciosa.' },
  bz_constantine_viii: { n: 'Constantino VIII', p: 'Constantinopla', d: 'El hermano que esperó sesenta y tres años para reinar en solitario; tres años de favoritos y mutilaciones — luego el trono pasó a sus hijas Zoe y Teodora.' },
  bz_zoe: { n: 'Zoe', p: 'Constantinopla', d: 'Con cincuenta años y adiestrada para casarse con quien la corte eligiera — Romano III, Miguel IV, Constantino IX; la ceca acuñó su rostro junto al de cada marido.' },
  bz_romanos_iii: { n: 'Romano III', p: 'Constantinopla', d: 'Primer marido de Zoe, un intelectual haciendo de emperador; subieron los impuestos, fracasó una incursión siria — y se ahogó en su baño, con las fuentes encogiéndose de hombros ante la emperatriz.' },
  bz_michael_iv: { n: 'Miguel IV', p: 'Constantinopla', d: 'El apuesto amante de Zoe, hecho emperador por su hermano el eunuco Juan; la epilepsia lo devoró mientras se alzaban los búlgaros — murió monje, con la guerra ganada en Ostrovo.' },
  bz_michael_v: { n: 'Miguel V', p: 'Constantinopla', d: 'Sobrino adoptivo de Miguel IV; exilió a su protectora Zoe por arrogancia — el pueblo se amotinó durante cuatro días, y salió cegado hacia un monasterio.' },
  bz_theodora: { n: 'Teodora', p: 'Constantinopla', d: 'Hermana menor de Zoe, coemperatriz en el motín de 1042, por fin soberana única en 1055 — severa, casta, setenta y cuatro años, la última de la casa macedonia.' },
  bz_constantine_ix: { n: 'Constantino IX', p: 'Constantinopla', d: 'Tercer marido de Zoe; su corte fue la tarde dorada de Constantinopla — escuela de derecho, filosofía — pero la moneda se degradó y quedaron sembradas las semillas de Manzikert.' },
  bz_michael_vi: { n: 'Miguel VI', p: 'Constantinopla', d: 'El anciano civil elegido por Teodora; desairó a los generales de Oriente, Isaac Comneno marchó — y la abdicación le compró un retiro honroso.' },
  bz_isaac_i: { n: 'Isaac I', p: 'Constantinopla', d: 'Primer emperador Comneno; recuperó las tierras de la Iglesia y las concesiones a la aristocracia, cogió un catarro en una tormenta — y entregó el trono a Constantino X Ducas.' },
  bz_constantine_x: { n: 'Constantino X', p: 'Constantinopla', d: 'Otra vez gobierno civil — el ejército sin paga, las fronteras adelgazando; los normandos acabaron con Italia, los turcos asaltaban Armenia, y su viuda pronto volvió a casarse.' },
  bz_romanos_iv: { n: 'Romano IV', p: 'Constantinopla', d: 'Emperador soldado que marchó para detener las razias turcomanas; traicionado en Manzikert — capturado por Alp Arslan, rescatado, cegado, muerto.' },
  bz_michael_vii: { n: 'Miguel VII', p: 'Constantinopla', d: '«Parapinakios» — el emperador del pan caro; alumno de Psellos, vio a los normandos tomar Bari y al tesoro derrumbarse bajo la guerra contra los pechenegos.' },
  bz_nikephoros_iii: { n: 'Nicéforo III', p: 'Constantinopla', d: 'El anciano general que Anatolia alzó contra Miguel VII; tres años de caos — luego la usurpación de Alejo Comneno lo acabó en un monasterio.' },
  bz_alexios_i: { n: 'Alejo I', p: 'Constantinopla', d: 'Reconstruyó desde el abismo — comercio veneciano a cambio de oro, pechenegos quebrados en Levounion, y la Primera Cruzada escoltada hasta hacer provechoso su tratado.' },
  bz_john_ii: { n: 'Juan II', p: 'Constantinopla', d: '«Juan el Bueno», el más apacible de un linaje fiero; campañas del Danubio, Hungría domada, Antioquía intimidada — murió de una herida de caza, llorado por los pobres.' },
  bz_manuel_i: { n: 'Manuel I', p: 'Constantinopla', d: 'El emperador caballero occidentalizador; torneos, diplomacia de Hungría a Ultramar, Myriokephalon superado — y el imperio relució hasta que ya no.' },
  bz_alexios_ii: { n: 'Alejo II', p: 'Constantinopla', d: 'Heredero de once años bajo su madre regente; Andrónico entró al galope, la chusma asesinó a María de Antioquía — y el niño fue estrangulado con una cuerda de arco.' },
  bz_andronikos_i: { n: 'Andrónico I', p: 'Constantinopla', d: 'Brillante y brutal azote de la aristocracia; dos años de terror — luego el golpe de Isaac Ángelo y una chusma del hipódromo lo hicieron pedazos.' },
  bz_isaac_ii: { n: 'Isaac II', p: 'Constantinopla', d: 'Venció a los normandos, malgastó el tesoro en banquetes, perdió Bulgaria ante los Asen — y fue cegado y luego restaurado por su propio hermano e hijo.' },
  bz_alexios_iii: { n: 'Alejo III', p: 'Constantinopla', d: 'Cegó a Isaac y llevó al Estado a la bancarrota; cuando la flota de la Cuarta Cruzada alcanzó el Cuerno de Oro en 1203, huyó con las joyas en una barca de pesca.' },
  bz_alexios_iv: { n: 'Alejo IV', p: 'Constantinopla', d: 'Les prometió a los cruzados la luna por el trono de su padre — no pudo pagar, y la facción de Murtzuflo lo estranguló mientras la ciudad pasaba hambre.' },
  bz_alexios_v: { n: 'Alejo V', p: 'Constantinopla', d: 'Dos meses de heroica defensa — la flota veneciana ardió frente a las murallas; luego huyó, y los cruzados lo ejecutaron en la Columna de Teodosio.' },
  bz_theodore_i: { n: 'Teodoro I Láscaris', p: 'Nicea', d: 'El superviviente del imperio residual: desde Nicea venció a los latinos, tomó una corona confirmada por el patriarca y se emparentó con las grandes familias para retener la Asia griega.' },
  bz_john_iii: { n: 'Juan III Ducas Vatatzés', p: 'Nicea', d: 'El mayor de los emperadores de Nicea — ganado el Rhyndakos, tomada Creta, frenada Bulgaria, bloqueada Constantinopla; los griegos lo canonizaron como Juan el Misericordioso.' },
  bz_theodore_ii: { n: 'Teodoro II Láscaris', p: 'Nicea', d: 'Erudito en el trono — correspondencia, filosofía, un cuadro de hombres nuevos educados; la epilepsia y las muertes familiares ensombrecieron cuatro breves años.' },
  bz_john_iv: { n: 'Juan IV Láscaris', p: 'Nicea', d: 'Coronado a los siete años, cegado a los once — por orden navideña de Miguel Paleólogo, el mismo día en que se reconquistó Constantinopla; el niño siguió viviendo en una fortaleza.' },
  bz_michael_viii: { n: 'Miguel VIII Paleólogo', p: 'Constantinopla', d: 'Tomó Constantinopla a los latinos en 1261 y reunió la Iglesia en Lyon para mantener a raya a Carlos de Anjou — odiado, temido, eficaz hasta el final.' },
  bz_andronikos_ii: { n: 'Andrónico II', p: 'Constantinopla', d: 'Piadoso y ahorrativo en daño del imperio — impuestos recortados, flota desguazada, la Compañía Catalana suelta y sin pagar; la guerra civil de su nieto acabó con sus cuarenta y seis años.' },
  bz_andronikos_iii: { n: 'Andrónico III', p: 'Constantinopla', d: 'Un joven de escándalos que gobernó sorprendentemente bien — codificación legal, Lesbos retomada, Epiro recuperado — mientras los otomanos tomaban su primer enclave en Galípoli.' },
  bz_john_v: { n: 'Juan V', p: 'Constantinopla', d: 'Medio siglo de guerras civiles, vasallaje otomano y una gira de conversión ante el papa; murió vasallo de Bayezid, con su imperio reducido a una ciudad más puertos dispersos.' },
  bz_john_vi: { n: 'Juan VI', p: 'Constantinopla', d: 'Gran doméstico convertido en coemperador a través de la guerra civil; dio su hija a un bey otomano, se retiró a un monasterio — y escribió su propia defensa en la historia.' },
  bz_andronikos_iv: { n: 'Andrónico IV', p: 'Constantinopla', d: 'Se apoderó del trono de su padre Juan V con ayuda otomana y genovesa — y lo perdió del mismo modo; Galípoli siguió turca de todas formas.' },
  bz_john_vii: { n: 'Juan VII', p: 'Constantinopla', d: 'Cinco meses de usurpación entre abuelo y tío; después sostuvo Constantinopla para Manuel II frente a Bayezid y negoció con la tormenta de Timur.' },
  bz_manuel_ii: { n: 'Manuel II', p: 'Constantinopla', d: 'Emperador erudito de la larga retirada — el famoso diálogo sobre la fe con un persa, las giras de súplica a las cortes occidentales que trajeron poca ayuda.' },
  bz_john_viii: { n: 'Juan VIII', p: 'Constantinopla', d: 'Buscó la unión de la Iglesia en Florencia y la ayuda occidental en Varna — ninguna se sostuvo; Pisanello y Benozzo Gozzoli pintaron para siempre su extraño sombrero.' },
  bz_constantine_xi: { n: 'Constantino XI Paleólogo', p: 'Constantinopla', d: 'El último emperador romano; murió con la espada en la mano en la brecha junto a la puerta de San Romano mientras el ejército de Mehmed II tomaba Constantinopla el 29 de mayo de 1453.' },
});

/* pharaohs of Egypt - 143 entries (2026-10-29) */
Object.assign(window.DATA_ES, {
  ph_narmer: { n: 'Narmer', p: 'Hieracómpolis, Egipto', d: 'El unificador que reunió el Alto y el Bajo Egipto bajo una sola corona — su paleta tallada lo muestra como el primer rey del primer gran Estado territorial de la Tierra.' },
  ph_aha: { n: 'Hor-Aha', p: 'Menfis, Egipto', d: 'El fundador de Menfis según la tradición, cuya tumba en Abidos albergaba sirvientes enterrados para servir a su rey en la otra vida.' },
  ph_djer: { n: 'Dyer', p: 'Abidos, Egipto', d: 'Los egipcios de siglos posteriores veneraron su tumba de Abidos como la sepultura del propio dios Osiris.' },
  ph_djet: { n: 'Dyet', p: 'Abidos, Egipto', d: 'Su estela funeraria, tallada con un glifo de serpiente, es una de las mejores obras conservadas del arte del período Dinástico Temprano.' },
  ph_merneith: { n: 'Merneit', p: 'Abidos, Egipto', d: 'Reina y regente del rey niño Den, figura en las listas tanto de reyes como de reinas — bien podría haber sido la primera gobernante de Egipto.' },
  ph_den: { n: 'Den', p: 'Abidos, Egipto', d: 'El primero en adoptar el título de Rey del Alto y del Bajo Egipto con la doble corona; su largo reinado fijó el patrón del joven Estado.' },
  ph_anedjib: { n: 'Anedjib', p: 'Menfis, Egipto', d: 'Un reinado turbulento recordado por la rebelión en el Alto Egipto y por testimonios casi contemporáneos que afirman que usurpó el trono.' },
  ph_semerket: { n: 'Semerjet', p: 'Abidos, Egipto', d: 'La tradición posterior, a través de Manetón, llamó al suyo un reinado de calamidades — y sin embargo recibió un entierro real completo en Abidos.' },
  ph_qaa: { n: 'Qa’a', p: 'Abidos, Egipto', d: 'Último rey de la Dinastía I, enterrado con una rica corte a su alrededor; su muerte abrió una lucha sucesoria.' },
  ph_hotepsekhemwy: { n: 'Hotepsekhemwy', p: 'Menfis, Egipto', d: 'Fundador de la Dinastía II; su nombre — «las dos potencias están en paz» — promete la reconciliación tras la crisis dinástica que cerró la Dinastía I.' },
  ph_raneb: { n: 'Raneb', p: 'Menfis, Egipto', d: 'Primer rey que colocó al dios solar Ra en su nombre, temprano indicio de la fe solar que dominaría el Imperio Antiguo.' },
  ph_nynetjer: { n: 'Nynetjer', p: 'Menfis, Egipto', d: 'Un reinado de casi cuarenta años registrado en los anales reales; tras él, la dinastía resbaló hacia décadas de sucesión disputada.' },
  ph_peribsen: { n: 'Peribsen', p: 'Abidos, Egipto', d: 'El único rey que puso al dios Seth, y no a Horus, sobre su nombre — una elección religiosa sobre la que los estudiosos aún discuten.' },
  ph_khasekhemwy: { n: 'Jasejemuy', p: 'Hieracómpolis, Egipto', d: 'Último rey del período Dinástico Temprano y reconciliador de Horus y Seth; su gigantesco recinto de adobe en Abidos es la mayor construcción de adobe de la Tierra.' },
  ph_sanakht: { n: 'Sanajt', p: 'Menfis, Egipto', d: 'Posible fundador de la Dinastía III; un fragmento de relieve muestra a un rey alto y corpulento cuya identidad aún debaten los expertos.' },
  ph_djoser: { n: 'Dyeser', p: 'Menfis, Egipto', d: 'Su arquitecto Imhotep erigió la pirámide escalonada de Saqqara — el primer gran edificio de piedra del mundo — y ambos fueron venerados como dioses durante 2.000 años.' },
  ph_sekhemkhet: { n: 'Sejemjet', p: 'Menfis, Egipto', d: 'Comenzó una segunda pirámide escalonada junto a la de Dyeser, pero la muerte tras seis años la dejó enterrada e inacabada — hallada intacta en 1952.' },
  ph_khaba: { n: 'Jaba', p: 'Menfis, Egipto', d: 'Probable constructor de la pirámide estratificada de Zawyet el-Aryan, otro temprano experimento de tumba real en piedra.' },
  ph_huni: { n: 'Huni', p: 'Menfis, Egipto', d: 'Último rey de la Dinastía III, probablemente el soberano que inició la pirámide de Meidum en vísperas de la gran época del Imperio Antiguo.' },
  ph_sneferu: { n: 'Seneferu', p: 'Menfis, Egipto', d: 'El mayor constructor de pirámides de Egipto — levantó tres, incluida la primera pirámide verdadera y de caras lisas, en Dahshur —, y las generaciones lo recordaron como un rey ideal y benéfico.' },
  ph_khufu: { n: 'Keops', p: 'Menfis, Egipto', d: 'Constructor de la Gran Pirámide de Guiza, la única maravilla superviviente del mundo antiguo — 146 metros de piedra alineados con el norte verdadero dentro de una fracción de grado.' },
  ph_djedefre: { n: 'Dyedefre', p: 'Menfis, Egipto', d: 'Trasladó la necrópolis real a Abu Rawash, el emplazamiento piramidal más alto de Egipto, y se le atribuye la primera esfinge real colosal.' },
  ph_khafre: { n: 'Kefrén', p: 'Menfis, Egipto', d: 'Constructor de la segunda pirámide de Guiza y de la Gran Esfinge que la guarda; su tumba parece más alta que la de Keops porque se alza en un terreno más elevado.' },
  ph_menkaure: { n: 'Micerinos', p: 'Menfis, Egipto', d: 'Su pirámide de Guiza pasó a revestirse de costoso granito, y las serenas estatuas triádicas en que aparece con la diosa Hathor fijaron el ideal del retrato real.' },
  ph_shepseskaf: { n: 'Shepseskaf', p: 'Menfis, Egipto', d: 'El último rey de la Dinastía IV abandonó las pirámides por una gigantesca mastaba con forma de sarcófago en Saqqara, cerrando la mayor época constructora de tumbas de Egipto.' },
  ph_userkaf: { n: 'Userkaf', p: 'Menfis, Egipto', d: 'Fundador de la Dinastía V; construyó el primer templo solar — un enorme obelisco en un patio abierto — e hizo del culto solar la ideología del Estado.' },
  ph_sahure: { n: 'Sahure', p: 'Menfis, Egipto', d: 'Sus relieves registran la primera travesía marítima egipcia hasta Punt y las escenas de flotas navales más antiguas; su complejo de Abusir fijó el canon artístico por generaciones.' },
  ph_neferirkare: { n: 'Neferirkare Kakai', p: 'Menfis, Egipto', d: 'Su archivo del templo en Abusir conservó los papiros administrativos y médicos más antiguos que se conocen de Egipto.' },
  ph_shepseskare: { n: 'Shepseskare', p: 'Menfis, Egipto', d: 'Un reinado oscuro atrapado entre dos más largos, marcado tan solo por un templo solar inacabado en Abusir.' },
  ph_neferefre: { n: 'Neferefre', p: 'Menfis, Egipto', d: 'Murió hacia los veinte años; su pirámide inacabada fue convertida apresuradamente en una baja mastaba en Abusir, donde fueron enterradas sus estatuas.' },
  ph_nyuserre: { n: 'Nyuserre Ini', p: 'Menfis, Egipto', d: 'Un reinado de treinta años que colmó Abusir de monumentos, entre ellos el templo solar cuyos relieves de las estaciones acompañan las cuentas de templo más antiguas de Egipto.' },
  ph_menkauhor: { n: 'Menkauhor Kaiu', p: 'Menfis, Egipto', d: 'Su pirámide, «la estrella de Ra es perfecta», estuvo perdida durante más de un siglo y solo fue identificada en 2008.' },
  ph_djedkare: { n: 'Djedkare Isesi', p: 'Menfis, Egipto', d: 'Un reinado de cuarenta años de reforma administrativa, al cabo del cual aparecieron los primeros hechizos protectores en las pirámides reales — semillas de los Textos de las Pirámides.' },
  ph_unas: { n: 'Unas', p: 'Menfis, Egipto', d: 'Último rey de la Dinastía V; su pirámide de Saqqara lleva los primeros Textos de las Pirámides tallados, la literatura religiosa más antigua de la humanidad, que prometen al rey la vida eterna entre las estrellas.' },
  ph_teti: { n: 'Teti', p: 'Menfis, Egipto', d: 'Fundador de la Dinastía VI, del que luego se dijo que fue asesinado por sus propios guardaespalda; las ricas tumbas de sus funcionarios son una fuente principal de la época.' },
  ph_userkare: { n: 'Userkare', p: 'Menfis, Egipto', d: 'Ocupó el trono entre Teti y Pepi I, y la memoria egipcia posterior lo tuvo por sospechoso del asesinato de Teti.' },
  ph_pepi_i: { n: 'Pepi I', p: 'Menfis, Egipto', d: 'Sobrevivió a una conspiración de harén, reinó cuatro décadas y dejó una imponente estatua de cobre — la mayor figura metálica del antiguo Cercano Oriente.' },
  ph_merenre_i: { n: 'Merenre Nemtyemsaf I', p: 'Menfis, Egipto', d: 'Envió al famoso gobernador Harkhuf a lo profundo de Nubia y murió joven, dejando el trono a un niño pequeño.' },
  ph_pepi_ii: { n: 'Pepi II', p: 'Menfis, Egipto', d: 'Un reinado de unos noventa años — probablemente el más largo de la historia — que abrió con una carta que prometía un pigmeo danzante y cerró con el Imperio Antiguo en decadencia.' },
  ph_merenre_ii: { n: 'Merenre Nemtyemsaf II', p: 'Menfis, Egipto', d: 'Un rey de un solo año, conocido casi únicamente a través de la reina que le sucedió.' },
  ph_nitocris: { n: 'Nitocris', p: 'Menfis, Egipto', d: 'La última gobernante de la Dinastía VI según Heródoto y Manetón, la primera faraona con nombre de la historia — que reinara o no de verdad una reina con ese nombre.' },
  ph_khety_i: { n: 'Meryibre Jety', p: 'Heracleópolis, Egipto', d: 'Fundador de la dinastía heracleopolitana que reclamó el norte mientras los príncipes tebanos acumulaban poder en el sur — el pulso entre dos poderes del Primer Período Intermedio.' },
  ph_intef_i: { n: 'Intef I', p: 'Tebas, Egipto', d: 'El primer gobernante tebano de su linaje en adoptar el cartucho real, mientras Tebas se alzaba contra la Egipto heracleopolitana.' },
  ph_intef_ii: { n: 'Intef II', p: 'Tebas, Egipto', d: '«El portador de la belleza», cuyo reinado de cincuenta años empujó la frontera tebana hacia el norte, más allá de Abidos, y puso en marcha la reunificación.' },
  ph_intef_iii: { n: 'Intef III', p: 'Tebas, Egipto', d: 'Completó el fortalecimiento tebano, y su yerno Mentuhotep II recogería el reino reunificado; siglos después aún se le veneraba en Coptos.' },
  ph_mentuhotep_ii: { n: 'Mentuhotep II', p: 'Tebas, Egipto', d: 'El reunificador — aplastó al norte heracleopolitano e inauguró el Imperio Medio; su templo de terrazas en Deir el-Bahari se convirtió en un modelo imitado durante milenios.' },
  ph_mentuhotep_iii: { n: 'Mentuhotep III', p: 'Tebas, Egipto', d: 'Envió la primera expedición registrada a la tierra de Punt, reabriendo el comercio del mar Rojo tras las guerras civiles.' },
  ph_mentuhotep_iv: { n: 'Mentuhotep IV', p: 'Tebas, Egipto', d: 'Una figura oscura al final — el supervisor real Amenemhat, que extrajo la tapa de su sarcófago, probablemente ocupó él mismo el trono como Amenemhat I.' },
  ph_amenemhat_i: { n: 'Amenemhat I', p: 'Itytauy, Egipto', d: 'Fundador de la Dinastía XII: trasladó la capital a la recién construida Itytauy y elevó a su hijo a corregente — una prudente precaución, pues fue asesinado en su trigésimo año.' },
  ph_senusret_i: { n: 'Sesostris I', p: 'Itytauy, Egipto', d: 'El corregente que asumió el poder sin sobresaltos; bajo él se puso por escrito la Historia de Sinuhé, y su obelisco en Heliópolis sigue en pie.' },
  ph_amenemhat_ii: { n: 'Amenemhat II', p: 'Itytauy, Egipto', d: 'Sus anales registran flotas mineras hacia Nubia y misiones comerciales hacia el Líbano — el Imperio Medio en su cima comercial.' },
  ph_senusret_ii: { n: 'Sesostris II', p: 'Itytauy, Egipto', d: 'Drenó los pantanos del Fayum para cultivarlos y llevó su pirámide a El-Lahun, cuyo pueblo de trabajadores conserva la vida cotidiana del antiguo Egipto.' },
  ph_senusret_iii: { n: 'Sesostris III', p: 'Itytauy, Egipto', d: 'El administrador guerrero cuyos fuertes encadenaron la Segunda Catarata de Nubia, cuyos canales la atravesaron y cuyas estatuas de rostro adusto inventaron un nuevo realismo en el arte real.' },
  ph_amenemhat_iii: { n: 'Amenemhat III', p: 'Itytauy, Egipto', d: 'La cima económica del Imperio Medio — su laberinto de Hawara asombró a los visitantes griegos, y sus obras en el Fayum convirtieron el pantano en el granero de Egipto.' },
  ph_amenemhat_iv: { n: 'Amenemhat IV', p: 'Itytauy, Egipto', d: 'El último rey varón de la Dinastía XII, posiblemente el pupilo y consorte de la reina que le sucedió.' },
  ph_sobekneferu: { n: 'Sobekneferu', p: 'Itytauy, Egipto', d: 'La primera mujer de la que consta que gobernó Egipto como rey; con ella terminaron la gran Dinastía XII — y la estabilidad del Imperio Medio.' },
  ph_khendjer: { n: 'Khendjer', p: 'Itytauy, Egipto', d: 'Un rey de nombre semita de la menguante Dinastía XIII — el único faraón del Imperio Medio del que se sepa que construyó una pirámide, en Saqqara sur.' },
  ph_khyan: { n: 'Khyan', p: 'Aváris, Egipto', d: 'Un gobernante hicsos de Aváris cuyos escarabeos van desde Creta hasta Mesopotamia — el reino de los extranjeros se asentaba dentro de un mundo comercial más amplio.' },
  ph_apepi: { n: 'Apepi', p: 'Aváris, Egipto', d: 'El rey hicsos de la leyenda posterior que se enemistó con Tebas — su ciudad de Aváris retuvo el Delta durante un siglo antes de que los tebanos contratacaran.' },
  ph_seqenenre_tao: { n: 'Seqenenre Tao', p: 'Tebas, Egipto', d: 'El tebano cuya momia muestra terribles heridas de hacha — probablemente cayó en batalla al abrir la guerra de liberación de Egipto contra los hicsos.' },
  ph_kamose: { n: 'Kamose', p: 'Tebas, Egipto', d: 'El último rey de la Dinastía XVII; las palabras de su estela — «quiero salvar Egipto y golpear a los asiáticos» — lanzaron la guerra que su hermano Ahmose concluyó.' },
  ph_ahmose_i: { n: 'Ahmose I', p: 'Tebas, Egipto', d: 'Expulsó a los hicsos de Egipto y los persiguió hasta Canaán, fundando la Dinastía XVIII y el imperio del Imperio Nuevo.' },
  ph_amenhotep_i: { n: 'Amenhotep I', p: 'Tebas, Egipto', d: 'Junto a su madre Ahmose-Nefertari fue venerado durante siglos como la divinidad protectora de los obreros reales de Tebas.' },
  ph_thutmose_i: { n: 'Tutmosis I', p: 'Tebas, Egipto', d: 'Primer faraón enterrado en el Valle de los Reyes; su ejército marchó hasta el Éufrates, el punto más lejano al que Egipto había llegado jamás.' },
  ph_thutmose_ii: { n: 'Tutmosis II', p: 'Tebas, Egipto', d: 'Su breve reinado fue dirigido por su gran esposa real Hatshepsut; en 2025 su tumba perdida se convirtió en el primer sepulcro real hallado desde el de Tutankamón.' },
  ph_hatshepsut: { n: 'Hatshepsut', p: 'Tebas, Egipto', d: 'La reina que gobernó como faraón pleno durante dos décadas — la expedición comercial a Punt, el templo de terrazas de Deir el-Bahari, obeliscos más altos que ningún otro anterior — hasta que reyes posteriores destrozaron sus imágenes.' },
  ph_thutmose_iii: { n: 'Tutmosis III', p: 'Tebas, Egipto', d: 'El «faraón soldado»: diecisiete campañas desde Meguido hasta el Éufrates forjaron el mayor imperio asiático de Egipto, largo tiempo oscurecido en la historia por la tía que reinó antes que él.' },
  ph_amenhotep_ii: { n: 'Amenhotep II', p: 'Tebas, Egipto', d: 'Un rey atleta y jactancioso que atravesó dianas de cobre con sus flechas — y una vez colgó de la proa de su nave a siete rebeldes muertos para aterrorizar a Siria.' },
  ph_thutmose_iv: { n: 'Tutmosis IV', p: 'Tebas, Egipto', d: 'Limpio la Gran Esfinge de la arena arrastrada por el viento y levantó la estela del sueño entre sus garras — la primera restauración registrada del monumento.' },
  ph_amenhotep_iii: { n: 'Amenhotep III', p: 'Tebas, Egipto', d: '«El Magnífico»: se casó con princesas desde Babilonia hasta Mitanni, erigió los Colosos de Memnón y gobernó un imperio en paz y en su momento de mayor riqueza.' },
  ph_akhenaten: { n: 'Akenatón', p: 'Ajetatón, Egipto', d: 'El rey hereje — cerró los viejos templos, veneró solo al disco solar Atón, construyó una nueva capital en Amarna e impuso una revolución en el arte y la fe que murió con él.' },
  ph_tutankhamun: { n: 'Tutankamón', p: 'Tebas, Egipto', d: 'El rey niño que restauró a los viejos dioses y murió hacia los dieciocho años; su tumba intacta, hallada en 1922, lo convirtió en el egipcio más famoso de todos los tiempos.' },
  ph_ay: { n: 'Ay', p: 'Tebas, Egipto', d: 'Un cortesano anciano que se casó con la viuda de Tutankamón para tomar el trono; su heredero designado murió joven, y el ejército tomó el poder a continuación.' },
  ph_horemheb: { n: 'Horemheb', p: 'Tebas, Egipto', d: 'El general que cerró el capítulo de Amarna — borró la memoria de Akenatón, reformó los tribunales contra la corrupción y eligió a un soldado como sucesor.' },
  ph_ramses_i: { n: 'Ramsés I', p: 'Pi-Ramsés, Egipto', d: 'Un soldado de carrera y heredero escogido por Horemheb, que reinó apenas año y medio y fundó una dinastía casi por accidente.' },
  ph_seti_i: { n: 'Seti I', p: 'Pi-Ramsés, Egipto', d: 'El restaurador del imperio — sus guerras recuperaron territorio sirio perdido, y su templo en Abidos y su tumba KV17 figuran entre los edificios mejor decorados de Egipto.' },
  ph_merneptah: { n: 'Merneptah', p: 'Pi-Ramsés, Egipto', d: 'Aplastó una gran invasión libia en su quinto año, y su himno de la victoria contiene la primera mención escrita de Israel fuera de la Biblia.' },
  ph_seti_ii: { n: 'Seti II', p: 'Pi-Ramsés, Egipto', d: 'Su reinado fue disputado por un rey rival, Amenmeses, en Tebas — la intriga cortesana había reemplazado a la gloria militar del imperio.' },
  ph_siptah: { n: 'Siptah', p: 'Pi-Ramsés, Egipto', d: 'Un rey niño lisiado — su pie zambo se aprecia en su momia — dirigido por el poderoso canciller Bay, nacido en Siria.' },
  ph_twosret: { n: 'Tausert', p: 'Pi-Ramsés, Egipto', d: 'La segunda faraona verificada de Egipto; su breve gobierno terminó con la Dinastía XIX en medio de la agitación que llevó al poder a una nueva dinastía.' },
  ph_setnakhte: { n: 'Setnajt', p: 'Pi-Ramsés, Egipto', d: 'Un forastero que se apoderó del trono vacante y restableció el orden, fundando la Dinastía XX y dejándosela a su famoso hijo Ramsés III.' },
  ph_ramses_iii: { n: 'Ramsés III', p: 'Pi-Ramsés, Egipto', d: 'El último gran faraón de Egipto — derrotó a los Pueblos del Mar en tierra y mar en una guerra que salvó el Mediterráneo oriental, y murió en una conspiración de harén cuyo acta del juicio se conserva.' },
  ph_ramses_iv: { n: 'Ramsés IV', p: 'Pi-Ramsés, Egipto', d: 'Su papiro de las canteras muestra los proyectos constructivos reales con un detalle excepcional; las raciones de grano dobladas para los obreros delatan una economía bajo tensión.' },
  ph_ramses_v: { n: 'Ramsés V', p: 'Pi-Ramsés, Egipto', d: 'Su momia presenta el caso de viruela más antiguo conocido; su tío le arrebató tanto el trono como la tumba.' },
  ph_ramses_vi: { n: 'Ramsés VI', p: 'Pi-Ramsés, Egipto', d: 'Se apropió de la tumba de su sobrino; la cámara sepulcral de la KV9 guarda los textos cósmicos más bellos — el viaje nocturno del dios sol — del Valle de los Reyes.' },
  ph_ramses_vii: { n: 'Ramsés VII', p: 'Pi-Ramsés, Egipto', d: 'Los precios del grano se dispararon y los obreros tebanos volvieron a la huelga durante su reinado — el Estado empezaba a quedarse sin plata y sin pan.' },
  ph_ramses_viii: { n: 'Ramsés VIII', p: 'Pi-Ramsés, Egipto', d: 'Un fantasma de las listas reales — apenas un año en el trono, sin monumentos, sin tumba conocida, sin momia.' },
  ph_ramses_ix: { n: 'Ramsés IX', p: 'Pi-Ramsés, Egipto', d: 'Bajo su reinado los funcionarios investigaron los robos de tumbas cuyos papiros del juicio se conservan — el Estado devoraba a sus propios reyes muertos.' },
  ph_ramses_x: { n: 'Ramsés X', p: 'Pi-Ramsés, Egipto', d: 'Un reinado final y sombrío: sus obreros se quedaron en casa por miedo a los asaltantes libios, y su tumba quedó apenas iniciada.' },
  ph_ramses_xi: { n: 'Ramsés XI', p: 'Pi-Ramsés, Egipto', d: 'El último Ramsés reinó solo de nombre mientras la guerra civil dividía Egipto entre generales y sumos sacerdotes de Amón — su muerte cerró el Imperio Nuevo.' },
  ph_smendes: { n: 'Smendes', p: 'Tanis, Egipto', d: 'Fundador de la Dinastía XXI, gobernando desde Tanis mientras los sumos sacerdotes de Amón dominaban Tebas — dos Egiptos en una inquieta asociación.' },
  ph_amenemnisu: { n: 'Amenemnisu', p: 'Tanis, Egipto', d: 'Un breve y oscuro reinado entre Smendes y el longevo Psusennes I, en una era cuyos registros casi han desaparecido.' },
  ph_psusennes_i: { n: 'Psusennes I', p: 'Tanis, Egipto', d: 'Su sarcófago de plata intacto y su máscara de oro, hallados en 1940, probaron que los reyes tanitas aún atesoraban riquezas — en plata, donde los faraones de antaño habían usado oro.' },
  ph_amenemopet: { n: 'Amenemopet', p: 'Tanis, Egipto', d: 'Una década tranquila en Tanis; su entierro fue apretujado en una cámara reutilizada mientras menguaban los recursos del reino.' },
  ph_siamun: { n: 'Siamón', p: 'Tanis, Egipto', d: 'Un rey tanita más enérgico, recordado por la construcción de templos en Tanis y más allá y vinculado por los estudiosos posteriores al Egipto de la época de Salomón.' },
  ph_psusennes_ii: { n: 'Psusennes II', p: 'Tanis, Egipto', d: 'El último rey de la Dinastía XXI; el matrimonio de su hija con la poderosa familia libia de Sheshonq allanó el camino al trono de la dinastía siguiente.' },
  ph_shoshenq_i: { n: 'Sheshonq I', p: 'Bubastis, Egipto', d: 'El descendiente del caudillo libio que reunificó Egipto y marchó sobre Israel y Judá — el «Sisac» bíblico que se llevó los tesoros del templo de Jerusalén hacia 925 a. C.' },
  ph_osorkon_i: { n: 'Osorkon I', p: 'Bubastis, Egipto', d: 'Heredó el imperio y gastó la riqueza de sus campañas en templos — solo sus regalos a Bubastis ascendieron a toneladas de oro y plata.' },
  ph_takelot_i: { n: 'Takelot I', p: 'Bubastis, Egipto', d: 'Su reinado mantuvo la estabilidad del norte, pero Tebas se deslizaba del control real hacia sus propios reyes-sacerdotes — la fragmentación del siglo siguiente ya era visible.' },
  ph_osorkon_ii: { n: 'Osorkon II', p: 'Bubastis, Egipto', d: 'Sus espléndidos relieves de la fiesta Sed enmascaran la primera gran crisis: derrotado en la batalla de Karkar, vio a Tebas coronar a un faraón rival.' },
  ph_takelot_ii: { n: 'Takelot II', p: 'Bubastis, Egipto', d: 'Su reinado coincidió con una revuelta tebana que dividió la tierra en reinos rivales — la crónica de su hijo Osorkon data cada año de la larga guerra civil.' },
  ph_shoshenq_iii: { n: 'Sheshonq III', p: 'Bubastis, Egipto', d: 'Reinó 52 años sobre un norte reducido mientras Tebas obedecía a otras dinastías — la realeza en Egipto se había vuelto un asunto regional.' },
  ph_pedubast_i: { n: 'Pedubast I', p: 'Tebas, Egipto', d: 'El general tebano que fundó la Dinastía XXIII desafiando abiertamente a Tanis — durante décadas tres faraones reinaron a la vez en una tierra dividida.' },
  ph_tefnakht: { n: 'Tefnajt', p: 'Sais, Egipto', d: 'El príncipe del Delta occidental que forjó una coalición contra los kushitas — vencido por Piye, aun así se proclamó faraón del norte, fundando la Dinastía XXIV.' },
  ph_bakenranef: { n: 'Bakenrenef', p: 'Sais, Egipto', d: '«Boccoris» para los griegos, recordado como un rey legislador — hasta que Shabaka lo mandó quemar vivo y tomó Egipto para Kush.' },
  ph_piye: { n: 'Piye', p: 'Napata, Nubia', d: 'El rey nubio que navegó hacia el norte y hizo de Egipto cosa suya; su estela de la victoria ordenaba a sus generales bañarse y orar antes de la batalla, y las pirámides reales volvieron a alzarse en El-Kurru.' },
  ph_shabaka: { n: 'Shabaka', p: 'Menfis, Egipto', d: 'Consolidó el dominio kushita desde Menfis, restauró viejos monumentos y mandó tallar en piedra la teología memfita de la creación — la Piedra de Shabaka que la preservó para nosotros.' },
  ph_shebitku: { n: 'Shebitku', p: 'Menfis, Egipto', d: 'Envió ejércitos kushitas a frenar el avance asirio en el Levante — el primer choque que atrajo la venganza de Asiria sobre Egipto.' },
  ph_taharqa: { n: 'Taharqa', p: 'Menfis, Egipto', d: 'El Tirhaca de la Biblia, un rey constructor cuyos monumentos se extendían de Nubia al Delta — hasta que Asiria saqueó Menfis y Tebas y acabó con el poder kushita en Egipto.' },
  ph_tantamani: { n: 'Tantamani', p: 'Menfis, Egipto', d: 'El último faraón kushita: recuperó Egipto brevemente, pero el contragolpe asirio incendió Tebas con tal crudeza que la ciudad nunca recuperó su antigua preeminencia.' },
  ph_psamtik_i: { n: 'Psamético I', p: 'Sais, Egipto', d: 'Un vasallo asirio que sobrevivió al poder de sus amos y devolvió la independencia a Egipto — sus mercenarios griegos iniciaron la edad griega del Delta.' },
  ph_necho_ii: { n: 'Necao II', p: 'Sais, Egipto', d: 'El rey que abrió un canal y construyó una flota, que mató a Josías de Judá en Meguido — y envió a los fenicios al primer viaje registrado alrededor de África.' },
  ph_psamtik_ii: { n: 'Psamético II', p: 'Sais, Egipto', d: 'Condujo una marcha punitiva hasta lo hondo de Kush; los grafitis de sus mercenarios griegos en Abu Simbel son la escritura griega datada más antigua conocida de Egipto.' },
  ph_apries: { n: 'Apries', p: 'Sais, Egipto', d: 'El «Hofra» de la Biblia, cuyo ejército no logró salvar Jerusalén de Babilonia; su favoritismo hacia las tropas griegas encendió la revuelta nativa que elevó al trono a Amasis.' },
  ph_amasis_ii: { n: 'Amasis II', p: 'Sais, Egipto', d: 'El usurpador que se convirtió en el modelo de rey sabio y afable según Heródoto — fundó la ciudad comercial griega de Naucratis y llovió regalos sobre los templos.' },
  ph_psamtik_iii: { n: 'Psamético III', p: 'Sais, Egipto', d: 'Rey durante unos seis meses; los persas de Cambises invadieron Egipto, y su ejecución tras una revuelta condenada al fracaso cerró por un siglo la era del gobierno nativo.' },
  ph_cambyses_ii: { n: 'Cambises II', p: 'Menfis, Egipto', d: 'El conquistador persa de Egipto, coronado faraón en un abrazo deliberado de la tradición egipcia — aunque los escritores griegos lo pintaron como un loco por matar al toro Apis.' },
  ph_darius_i: { n: 'Darío I', p: 'Menfis, Egipto', d: 'Un rey mejor de lo que la tradición griega admite: codificó la ley egipcia, terminó el canal hacia el mar Rojo y reparó templos, haciendo de Egipto la provincia más rica del imperio.' },
  ph_xerxes_i: { n: 'Jerjes I', p: 'Menfis, Egipto', d: 'El Gran Rey, célebre por su guerra contra Grecia, gobernó Egipto con mayor dureza, y sus exigencias pesadas engendraron la revuelta que su sucesor hubo de aplastar.' },
  ph_artaxerxes_i: { n: 'Artajerjes I', p: 'Menfis, Egipto', d: 'Egipto se separó bajo Inaros con ayuda ateniense, y a Persia le llevó seis años y una gran flota recuperar la rica provincia.' },
  ph_darius_ii: { n: 'Darío II', p: 'Menfis, Egipto', d: 'El control persa se fue decayendo a lo largo de su reinado; dentro del año siguiente a su muerte, un príncipe egipcio, Amirteo, volvió a dominar el Delta.' },
  ph_amyrtaeus: { n: 'Amirteo', p: 'Sais, Egipto', d: 'El príncipe rebelde de Sais que expulsó a las guarniciones persas y reinó como el único rey de la Dinastía XXVIII.' },
  ph_nefaarud_i: { n: 'Nefaarud I', p: 'Mendes, Egipto', d: 'Fundador de la Dinastía XXIX en Mendes y aliado de Esparta en la guerra de Grecia contra Persia.' },
  ph_achoris: { n: 'Acoris', p: 'Mendes, Egipto', d: 'Un gobernante enérgico que financió a Chipre y Atenas contra Persia y estampó su cartucho en monumentos por doquier — la vigorosa floración tardía del Egipto nativo.' },
  ph_nectanebo_i: { n: 'Nectanebo I', p: 'Sebennitos, Egipto', d: 'Un general de la línea mendesia que se apoderó del trono, rechazó el gran intento persa de regreso y comenzó el templo de Isis en File.' },
  ph_teos: { n: 'Teos', p: 'Sebennitos, Egipto', d: 'Condujo la última guerra ofensiva de Egipto hasta Siria — luego su sobrino usurpó el trono con apoyo mercenario y la campaña se derrumbó.' },
  ph_nectanebo_ii: { n: 'Nectanebo II', p: 'Sebennitos, Egipto', d: 'El último faraón nativo de Egipto, espléndido mecenas de templos — hasta que la gran invasión de Artajerjes III acabó para siempre con el gobierno nativo; la leyenda lo hizo luego padre secreto de Alejandro.' },
  ph_artaxerxes_iii: { n: 'Artajerjes III', p: 'Menfis, Egipto', d: 'El reconquistador persa, cuya reconquista de Egipto fue brutal; una década después Alejandro destruyó el imperio, y Egipto cambió de manos otra vez.' },
  ph_ptol_i: { n: 'Ptolomeo I Sóter', p: 'Alejandría, Egipto', d: 'El general de Alejandro que hizo de Egipto su propio reino — se apoderó del cuerpo de Alejandro para Alejandría, fundó la Biblioteca y el Museo, y escribió la primera historia de las guerras.' },
  ph_ptol_ii: { n: 'Ptolomeo II Filadelfo', p: 'Alejandría, Egipto', d: '«El que ama a su hermana», se casó con su hermana carnal Arsínoe II, llevó a su apogeo el faro de Pharos y la Biblioteca, y llevó a Egipto a su máxima extensión.' },
  ph_ptol_iii: { n: 'Ptolomeo III Evergetes', p: 'Alejandría, Egipto', d: '«El Benefactor» vengó a su hermana invadiendo Siria y trayendo de vuelta a casa las estatuas de los dioses de Egipto; su reinado fue la mayor extensión del imperio ptolemaico.' },
  ph_ptol_iv: { n: 'Ptolomeo IV Filopátor', p: 'Alejandría, Egipto', d: 'Venció a Antíoco III en Rafia — una batalla de 100.000 hombres y elefantes de guerra — apoyándose en tropas egipcias nativas cuyo nuevo poder inició la caída de la dinastía.' },
  ph_ptol_v: { n: 'Ptolomeo V Epífanes', p: 'Alejandría, Egipto', d: 'Un rey niño cuyo decreto de la Piedra de Rosetta — la llave de la historia para los jeroglíficos — recompensó la lealtad de los sacerdotes mientras el imperio se le escapaba.' },
  ph_ptol_vi: { n: 'Ptolomeo VI Filométor', p: 'Alejandría, Egipto', d: 'Treinta y cinco años de guerra civil familiar con su hermano y con la reina que reinaba junto a él; murió por las lesiones de una caída tras una victoria siria, dejando ardiendo la disputa.' },
  ph_ptol_viii: { n: 'Ptolomeo VIII Evergetes II', p: 'Alejandría, Egipto', d: 'El superviviente abotagado y despiadado: mató a su sobrino rey, se casó con su hermana y luego con la hija de esta, y legó Egipto a la reina que le sobreviviera.' },
  ph_ptol_ix: { n: 'Ptolomeo IX Sóter II', p: 'Alejandría, Egipto', d: '«Látiro», el rey garbanzo — dos veces expulsado por la facción de su propia madre y dos veces repuesto; sus rencillas vaciaron Alejandría de sus sabios griegos.' },
  ph_ptol_x: { n: 'Ptolomeo X Alejandro I', p: 'Alejandría, Egipto', d: 'Robó el trono a su hermano y legó Egipto a Roma en su testamento — una reclamación en papel que Augusto cobró un siglo después.' },
  ph_ptol_xi: { n: 'Ptolomeo XI Alejandro II', p: 'Alejandría, Egipto', d: 'Diecinueve días después de casarse con su madrastra como corregente, la asesinó — y la chusma de Alejandría lo despedazó en venganza.' },
  ph_ptol_xii: { n: 'Ptolomeo XII Auletes', p: 'Alejandría, Egipto', d: '«El flautista» compró el reconocimiento romano con sobornos ruinosos, huyó de una revuelta nativa en 58 a. C. y volvió tras las legiones romanas; su hija mayor fue Cleopatra VII.' },
  ph_berenice_iv: { n: 'Berenice IV', p: 'Alejandría, Egipto', d: 'Reinó durante los años de exilio de su padre y murió por ello — el Ptolomeo XII que regresó ejecutó a su propia hija.' },
  ph_ptol_xiii: { n: 'Ptolomeo XIII', p: 'Alejandría, Egipto', d: 'El hermano-esposo cuyos regentes expulsaron a Cleopatra y sitiaron a César en Alejandría; se ahogó en el Nilo, con la armadura puesta, tras su derrota final.' },
  ph_ptol_xiv: { n: 'Ptolomeo XIV', p: 'Alejandría, Egipto', d: 'El hermano menor instalado como consorte de Cleopatra — muerto antes de tres años, supuestamente por órdenes de su hermana-esposa.' },
  ph_caesarion: { n: 'Ptolomeo XV Cesarion', p: 'Alejandría, Egipto', d: '«Pequeño César», hijo de Cleopatra y Julio César y último de los Ptolomeos — Octavio mandó matar al joven de diecisiete años tras Accio, observando que demasiados Césares no era bueno.' },
});

/* Mesopotamian rulers - 45 entries (2026-10-30) */
Object.assign(window.DATA_ES, {
  me_enmebaragesi: { n: 'Enmebaragesi', p: 'Kish, Mesopotamia', d: 'El primer gobernante mesopotámico que la arqueología puede probar — atestiguado en un jarrón hecho añicos procedente de Nippur, y recordado por la tradición como el padre del rey al que se enfrentó Gilgamesh.' },
  me_gilgamesh: { n: 'Gilgamesh', p: 'Uruk, Mesopotamia', d: 'Un rey verdadero de Uruk hacia el 2700 a. C., luego héroe de la primera gran epopeya del mundo — su muralla urbana, dice la Lista Real Sumeria, se extendía a lo largo de cinco kilómetros.' },
  me_mesannepada: { n: 'Mesannepada', p: 'Ur, Mesopotamia', d: 'Fundador de la Primera Dinastía de Ur, cuyo cementerio real deparó los yelmos de oro y las liras de cabeza de toro que definen la edad de esplendor de Sumer.' },
  me_eannatum: { n: 'Eannatum', p: 'Lagash, Mesopotamia', d: 'Mandó tallar la Estela de los Buitres, que celebra su victoria sobre Umma — la primera imagen detallada de una batalla en la historia, con muro de escudos, lanceros y un rey sobre un carro de guerra.' },
  me_lugalzagesi: { n: 'Lugalzagesi', p: 'Uruk, Mesopotamia', d: 'El último soberano sumerio nativo: unió el sur desde Uruk y luego lo perdió todo ante Sargón de Acad, que según la leyenda lo paseó con un collar de perro hasta las puertas de Nippur.' },
  me_sargon: { n: 'Sargón de Acad', p: 'Acad, Mesopotamia', d: 'El copero que se apoderó del trono y forjó desde su ciudad de Agadé el primer imperio multiétnico de la historia — su emplazamiento sigue siendo un enigma; las leyendas contaban cómo el bebé en una cesta de juncos bajó flotando por el Éufrates.' },
  me_naram_sin: { n: 'Naram-Sin', p: 'Acad, Mesopotamia', d: 'Primer rey mesopotámico en proclamarse dios — su relieve de la victoria en la montaña muestra al rey-dios marchando sobre los Zagros, y bajo su mandato el imperio alcanzó su máxima extensión antes de empezar a agrietarse.' },
  me_sharkalisharri: { n: 'Shar-Kali-Sharri', p: 'Acad, Mesopotamia', d: '«Rey de las cuatro regiones»: un reinado de campañas sin fin que mantuvo unido el imperio — tras él, Acad se disolvió en manos de los gutas en el plazo de una generación.' },
  me_utuhegal: { n: 'Utu-Hegal', p: 'Uruk, Mesopotamia', d: 'El rey de Uruk que expulsó a los montañeses gutas y restauró la realeza sumeria — su estela de la victoria figura entre los últimos grandes monumentos del antiguo Sumer.' },
  me_gudea: { n: 'Gudea', p: 'Lagash, Mesopotamia', d: 'El gobernante de Lagash que dejó más de dos docenas de serenas estatuas de diorita — y el relato en cilindros de arcilla de un sueño ordenado por un dios que lo llevó a construir el templo de Ningirsu.' },
  me_urnammu: { n: 'Ur-Nammu', p: 'Ur, Mesopotamia', d: 'Fundador del imperio de Ur III: su gran zigurat de Ur aún sigue en pie, y su código de leyes — siglos anterior al de Hammurabi — es el más antiguo hallado hasta ahora.' },
  me_shulgi: { n: 'Shulgi', p: 'Ur, Mesopotamia', d: 'Un reinado de 48 años de postas en los caminos, escuelas de escribas normalizadas y leyes para todo el imperio — coronado por un himno autografiado que se jactaba de haber corrido 320 kilómetros en un solo día.' },
  me_ibbisin: { n: 'Ibbi-Sin', p: 'Ur, Mesopotamia', d: 'El último rey de Ur, rendido por el hambre ante las incursiones amorritas y los ejércitos elamitas — el Lamento por la caída de Ur se convirtió en el poema más copiado de su tiempo.' },
  me_ishbierra: { n: 'Ishbi-Erra', p: 'Isin, Mesopotamia', d: 'Un oficial amorrita al servicio de Ur que expulsó a los elamitas y fundó la dinastía de Isin, reclamando la herencia escrita y sagrada del imperio caído.' },
  me_lipitishtar: { n: 'Lipit-Ishtar', p: 'Isin, Mesopotamia', d: 'Su código de leyes, grabado un siglo y medio antes que el de Hammurabi, protegía a viudas y huérfanos — y sus himnos escolares lo elevaron después a dios de los escribas.' },
  me_rimsin: { n: 'Rim-Sin I', p: 'Larsa, Mesopotamia', d: 'Reinó sesenta años en Larsa — más que cualquier rey documentado antes de la época moderna — y luego perdió su capital en una sola campaña ante Hammurabi de Babilonia.' },
  me_sumuabum: { n: 'Sumu-abum', p: 'Babilonia, Mesopotamia', d: 'El caudillo amorrita que hizo de Babilonia la sede de una dinastía — una modesta ciudad ribereña que su casa elevaría hasta convertirla en el centro del mundo.' },
  me_hammurabi: { n: 'Hammurabi', p: 'Babilonia, Mesopotamia', d: 'El artífice del imperio de Babilonia — sometió sucesivamente Larsa, Mari y Asiria, y su estela de leyes, alzada «para que el fuerte no oprimiera al débil», se convirtió durante siglos en sinónimo de justicia.' },
  me_samsuiluna: { n: 'Samsu-iluna', p: 'Babilonia, Mesopotamia', d: 'Heredó el imperio de su padre, rechazó una invasión casita y contempló cómo el extremo sur se separaba como la dinastía del País del Mar — los bordes del imperio ya se deshilachaban.' },
  me_burnaburiash: { n: 'Burna-Buriash II', p: 'Babilonia, Mesopotamia', d: 'El rey casita cuyas cartas a los faraones de Egipto, halladas en Amarna, regatean por oro y novias reales — la diplomacia de superpotencias de la Edad del Bronce en su mejor momento.' },
  me_kurigalzu_ii: { n: 'Kurigalzu II', p: 'Babilonia, Mesopotamia', d: 'Un rey casita batallador que frenó en seco el ascenso de Asiria y engalanó Dur-Kurigalzu con un zigurat cuyo resto aún se alza al oeste de Bagdad.' },
  me_nebuchadnezzar_i: { n: 'Nabucodonosor I', p: 'Babilonia, Mesopotamia', d: 'Vengó la humillación de Babilonia: lanzó incursiones hasta el corazón de Elam y trajo en triunfo a casa la estatua robada del dios Marduk — la gesta que los reyes babilonios posteriores no dejaron de celebrar.' },
  me_mardukaplaiddina: { n: 'Marduk-apla-iddina II', p: 'Babilonia, Mesopotamia', d: 'El «Merodac-Baladán» de la Biblia: un jefe caldeo que se apoderó dos veces de Babilonia y desafió durante dos décadas a Sargón II y a Senaquerib, buscando aliados hasta en Judá.' },
  me_shamashshumukin: { n: 'Shamash-shum-ukin', p: 'Babilonia, Mesopotamia', d: 'Hermano de Asurbanipal, instalado como rey de Babilonia bajo la soberanía asiria — su revuelta de seis años por la libertad de Babilonia terminó en un asedio donde, según una versión, ardió en su propio palacio.' },
  me_nabopolassar: { n: 'Nabopolasar', p: 'Babilonia, Mesopotamia', d: 'El caldeo que devolvió la libertad a Babilonia y dio sepultura a Asiria — con aliados medos asaltó Nínive en el 612 a. C. y dejó las últimas campañas occidentales a su hijo.' },
  me_nebuchadnezzar_ii: { n: 'Nabucodonosor II', p: 'Babilonia, Mesopotamia', d: 'El mayor rey de Babilonia: venció a Egipto en Carquemis, tomó Jerusalén y la incendió en el 586 a. C., y construyó la Puerta de Ishtar y el zigurat que la memoria guarda como la Torre de Babel.' },
  me_amelmarduk: { n: 'Amel-Marduk', p: 'Babilonia, Mesopotamia', d: 'El «Evil-Merodac» de la Biblia, que liberó de la prisión al rey cautivo de Judá — dos años después su cuñado Neriglissar lo asesinó.' },
  me_neriglissar: { n: 'Neriglissar', p: 'Babilonia, Mesopotamia', d: 'Un general babilonio que alcanzó el trono mediante un asesinato, hizo campaña en Cilicia y murió a los cuatro años, dejando un heredero niño a la merced de los conspiradores.' },
  me_labashimarduk: { n: 'Labashi-Marduk', p: 'Babilonia, Mesopotamia', d: 'Un rey niño de nueve meses, asesinado por los conspiradores que entregaron la corona a Nabónido — el último espasmo de la dinastía antes de su caída.' },
  me_nabonidus: { n: 'Nabónido', p: 'Babilonia, Mesopotamia', d: 'El último rey de Babilonia: un devoto del dios lunar Sin que se enemistó con los sacerdotes de Marduk, pasó una década en el oasis de Teima y perdió su ciudad ante Ciro de Persia sin batalla alguna en el 539 a. C.' },
  me_shamshiadad: { n: 'Shamshi-Adad I', p: 'Shubat-Enlil, Asiria', d: 'El amorrita que talló un imperio en la Alta Mesopotamia desde Asur hasta el Mediterráneo, colocando a sus hijos como gobernadores — sus cartas reprendiendo a un heredero díscolo se conservan en los archivos de Mari.' },
  me_zimrilim: { n: 'Zimri-Lim', p: 'Mari, Mesopotamia', d: 'El rey de Mari cuyos archivos palaciegos — miles de cartas, pleitos y profecías — son nuestra ventana a la vida babilónica antigua; Hammurabi tomó su ciudad y la incendió.' },
  me_ashuruballit_i: { n: 'Asur-ubalit I', p: 'Asur, Asiria', d: 'Sacudió el yugo de Mitanni e hizo de Asiria una gran potencia — el primer asirio que escribió a Egipto como un igual entre los «grandes reyes».' },
  me_tukultininurta_i: { n: 'Tukulti-Ninurta I', p: 'Asur, Asiria', d: 'Aplastó a los casitas y tomó Babilonia, llevándose la estatua de Marduk — luego fundó una nueva capital, Kar-Tukulti-Ninurta, y murió asesinado por sus propios hijos.' },
  me_tiglathpileser_i: { n: 'Tiglatpileser I', p: 'Asur, Asiria', d: 'Un guerrero y cazador de la Edad del Bronce que marchó hasta el Mediterráneo y alardeó de haber abatido 920 leones desde su carro; tras él, Asiria se replegó a su tierra natal durante dos siglos.' },
  me_adadnirari_ii: { n: 'Adad-nirari II', p: 'Asur, Asiria', d: 'El restaurador: rompió el cerco arameo en torno a Asur, recuperó las tierras del Habur y puso a Asiria en el camino de doscientos años hacia el imperio.' },
  me_ashurnasirpal_ii: { n: 'Asurnasirpal II', p: 'Nimrud, Asiria', d: 'El terror del Levante que trasladó la capital a Nimrud — relieves de rebeldes desollados y un banquete para 69.574 invitados muestran los dos rostros de la realeza asiria.' },
  me_shalmaneser_iii: { n: 'Salmanasar III', p: 'Nimrud, Asiria', d: 'Sus 34 años de campañas se toparon con la primera gran coalición del Levante en Karkar en el 853 a. C. — y el Obelisco Negro muestra a Jehú de Israel inclinándose para pagar tributo.' },
  me_tiglathpileser_iii: { n: 'Tiglatpileser III', p: 'Asur, Asiria', d: 'El emperador reformador: un ejército profesional, la deportación en masa como política, Babilonia tomada como «Pulu», y Judá e Israel convertidos en tributarios — el «Pul» de la Biblia.' },
  me_sargon_ii: { n: 'Sargón II', p: 'Dur-Sharrukin, Asiria', d: 'Tomó Samaria y acabó con el reino de Israel, levantó una nueva capital de muralla cuadrada en Dur-Sharrukin y cayó en batalla contra los cimerios — su cuerpo jamás fue recuperado.' },
  me_sennacherib: { n: 'Senaquerib', p: 'Nínive, Asiria', d: 'Hizo de Nínive una maravilla de canales y murallas, incendió Babilonia en el 689 a. C. y sitió Jerusalén en el 701 a. C. — y fue asesinado por sus propios hijos en un templo.' },
  me_esarhaddon: { n: 'Asarhaddón', p: 'Nínive, Asiria', d: 'Reconstruyó la Babilonia que su padre arrasó, conquistó Egipto y tomó Menfis en el 671 a. C., y luego murió camino de Egipto otra vez, dejando una doble sucesión cuidadosamente pactada.' },
  me_ashurbanipal: { n: 'Asurbanipal', p: 'Nínive, Asiria', d: 'El rey erudito: su biblioteca de Nínive nos preservó la Epopeya de Gilgamesh, sus relieves lo muestran banqueteando bajo la cabeza de un enemigo muerto — y a una generación de su muerte, el imperio ya se había esfumado.' },
  me_sinsharishkun: { n: 'Sin-shar-ishkun', p: 'Nínive, Asiria', d: 'Su reinado se consumió en la guerra civil — luego llegaron medos y babilonios: Nínive cayó en el 612 a. C. de forma tan completa que su emplazamiento quedó olvidado en pocos siglos.' },
  me_ashuruballit_ii: { n: 'Asur-ubalit II', p: 'Harrán, Asiria', d: 'El último rey de Asiria, coronado en Harrán sobre los restos del imperio; el socorro egipcio fracasó, y con su derrota Asiria desapareció de la historia durante dos mil años.' },
});
/* es translations — Napoleonic Wars battles (2026-10-30) */
Object.assign(window.DATA_ES, {
  nb_toulon: { n: 'Sitio de Tolón', p: 'Tolón, Francia', d: 'Un joven capitán de artillería llamado Napoleón Bonaparte planea la toma de la base naval en poder británico: es su primer mando y el trampolín hacia todo lo que viene después.' },
  nb_lodi: { n: 'Batalla de Lodi', p: 'Lodi, Italia', d: 'El asalto al puente sobre el Adda convierte al joven general en héroe ante sus propios soldados: nace «el pequeño cabo» e Italia se vuelve su laboratorio.' },
  nb_arcole: { n: 'Batalla de Arcole', p: 'Arcole, Italia', d: 'Tres días de combates en los pantanos del Alpone: Napoleón se apodera en persona del famoso puente bajo el fuego y finalmente hace retroceder a los austriacos de Alvinczi.' },
  nb_rivoli: { n: 'Batalla de Rivoli', p: 'Rivoli, Italia', d: 'La obra maestra con que se cierra la primera campaña de Italia: los ataques concéntricos hacen añicos cuatro columnas austriacas y Mantua finalmente se rinde.' },
  nb_pyramids: { n: 'Batalla de las Pirámides', p: 'Guiza, Egipto', d: '«Soldados, desde lo alto de esas pirámides os contemplan cuarenta siglos»: los cuadros de infantería quebrantan la caballería mameluca ante El Cairo.' },
  nb_nile: { n: 'Batalla del Nilo', p: 'Bahía de Abukir, Egipto', d: 'Nelson fondea junto a la flota francesa y la destruye de noche: el ejército queda varado en Egipto y Gran Bretaña domina el Mediterráneo.' },
  nb_novi: { n: 'Batalla de Novi', p: 'Novi Ligure, Italia', d: 'El ejército austro-ruso de Suvórov destroza a los franceses en las estribaciones de los Apeninos; el joven general Joubert cae con la primera descarga.' },
  nb_marengo: { n: 'Batalla de Marengo', p: 'Marengo, Italia', d: 'Una batalla perdida, luego salvada por la columna que Desaix trae de regreso y por una carga de caballería en masa: Napoleón la recontará desde entonces como la leyenda fundacional del Consulado.' },
  nb_hohenlinden: { n: 'Batalla de Hohenlinden', p: 'Hohenlinden, Alemania', d: 'La emboscada de Moreau en los bosques helados al oeste de Múnich destroza un ejército austriaco y fuerza a Viena a firmar la Paz de Lunéville.' },
  nb_copenhagen: { n: 'Batalla de Copenhague', p: 'Copenhague, Dinamarca', d: 'Nelson lleva el anteojo al ojo ciego, ignora la señal de retirada y destruye la flota danesa: la respuesta de Gran Bretaña a la neutralidad armada del norte.' },
  nb_ulm: { n: 'Batalla de Ulm', p: 'Ulm, Alemania', d: 'Siete cuerpos franceses giran en un arco gigantesco alrededor de la Selva Negra y se tragan al ejército austriaco entero de Mack: 60 000 prisioneros por apenas 500 muertos franceses.' },
  nb_trafalgar: { n: 'Batalla de Trafalgar', p: 'Cabo Trafalgar, España', d: 'Nelson rompe la línea franco-española frente al cabo Trafalgar y logra la victoria naval más decisiva de la historia británica, muriendo en el momento del triunfo: una invasión de Inglaterra se vuelve imposible.' },
  nb_austerlitz: { n: 'Batalla de Austerlitz', p: 'Austerlitz, Moravia', d: 'La obra maestra de Napoleón: atrae a los aliados hasta que abandonan las alturas de Pratzen y parte su centro entre la niebla; «el sol de Austerlitz» pone fin a la Tercera Coalición.' },
  nb_jena_auerstedt: { n: 'Batalla de Jena y Auerstedt', p: 'Jena, Alemania', d: 'Dos batallas en una misma mañana: Napoleón aplasta a un ejército prusiano en Jena mientras Davout vence a otro mayor en Auerstedt; Prusia colapsa en tres semanas.' },
  nb_eylau: { n: 'Batalla de Eylau', p: 'Eylau, Prusia', d: 'Una carnicería helada e inconclusa en la nieve: el primer gran revés de Napoleón, frente a los rusos de Bennigsen; Ney cabalga por el campo: «¡Qué carnicería! Y sin resultado».' },
  nb_friedland: { n: 'Batalla de Friedland', p: 'Friedland, Prusia', d: 'Lannes sujeta a los rusos de espaldas al río Alle y Napoleón remata la faena: se abre el camino a Tilsit, donde dos emperadores se reparten Europa.' },
  nb_bailen: { n: 'Batalla de Bailén', p: 'Bailén, España', d: 'Todo un cuerpo francés al mando del general Dupont se rinde a las tropas regulares españolas: la primera gran derrota de las armas napoleónicas, cuya noticia enciende la revuelta por toda Europa.' },
  nb_vimeiro: { n: 'Batalla de Vimeiro', p: 'Vimeiro, Portugal', d: 'La línea de Wellesley, oculta tras la ladera, deshace los asaltos de Junot: la primera batalla del ejército peninsular británico abre seis años de éxitos casi ininterrumpidos.' },
  nb_zaragoza: { n: 'Sitio de Zaragoza', p: 'Zaragoza, España', d: 'Dos sitios y combates casa por casa convierten la ciudad de Palafox en sinónimo de resistencia popular: unos 50 000 muertos españoles en pocos meses.' },
  nb_somosierra: { n: 'Batalla de Somosierra', p: 'Puerto de Somosierra, España', d: 'La caballería ligera polaca galopa cuesta arriba, entre el humo que vela el puerto, directo contra los cañones españoles y abre el camino a Madrid: la hazaña de caballería más célebre de la época.' },
  nb_corunna: { n: 'Batalla de Elviña', p: 'La Coruña, España', d: 'La angustiosa retirada hacia la costa le cuesta al ejército británico su comandante: Sir John Moore cae como vencedor mientras la flota lleva las tropas de vuelta a casa.' },
  nb_talavera: { n: 'Batalla de Talavera', p: 'Talavera, España', d: 'Una noche de combates confusos y un duro asalto al mediodía se estrellan contra la línea de Wellesley: un vizcondado para Wellington y la prueba de que la guerra en España se puede ganar.' },
  nb_eckmuhl: { n: 'Batalla de Eckmühl', p: 'Eckmühl, Alemania', d: 'El cuerpo de Davout resiste solo y después Napoleón en persona envuelve el flanco austriaco: el archiduque Carlos escapa al norte del Danubio, derrotado.' },
  nb_aspern_essling: { n: 'Batalla de Aspern-Essling', p: 'Viena, Austria', d: 'La primera gran derrota de Napoleón: las crecidas del Danubio rompen los puentes de barcas y Lannes muere defendiendo el granero de Essling; Europa descubre que el Emperador puede ser vencido.' },
  nb_wagram: { n: 'Batalla de Wagram', p: 'Wagram, Austria', d: '300 000 hombres y la mayor batalla vista hasta entonces en Europa: un desgaste frontal a través del Marchfeld, con grandes baterías disparando a tiro directo, pone fin a la Quinta Coalición.' },
  nb_busaco: { n: 'Batalla de Buçaco', p: 'Buçaco, Portugal', d: 'Masséna lanza su ejército cuesta arriba entre la niebla del amanecer y es sangrientamente rechazado en la Serra: Wellington se desliza entonces tras las Líneas de Torres Vedras.' },
  nb_torres_vedras: { n: 'Líneas de Torres Vedras', p: 'Torres Vedras, Portugal', d: '152 fuertes y reductos ocultan el ejército de Wellington a un invierno francés de hambre: «la campaña más desagradable» que Masséna haya librado, sin una sola batalla campal.' },
  nb_fuentes_onoro: { n: 'Batalla de Fuentes de Oñoro', p: 'Fuentes de Oñoro, España', d: 'Tres días alrededor de una aldea en llamas: «Si Boney hubiera estado aquí, habríamos sido derrotados»; Wellington resiste y la última ofensiva de Masséna en Portugal llega a su fin.' },
  nb_albuera: { n: 'Batalla de La Albuera', p: 'La Albuera, España', d: 'La marcha envolvente de Soult se topa con el ejército políglota de Beresford: la brigada británica de fusileros decide la tarde más sangrienta de toda la guerra.' },
  nb_ciudad_rodrigo: { n: 'Sitio de Ciudad Rodrigo', p: 'Ciudad Rodrigo, España', d: 'Wellington asalta en doce días de invierno la plaza fronteriza y su tropa de choque se apodera de la gran brecha: la puerta a la campaña de 1812.' },
  nb_badajoz: { n: 'Sitio de Badajoz', p: 'Badajoz, España', d: 'El asalto más sangriento de la guerra: tres brechas conquistadas en una noche de furia y un saqueo que queda como una mancha en la memoria del ejército.' },
  nb_salamanca: { n: 'Batalla de los Arapiles', p: 'Salamanca, España', d: 'Wellington ve extenderse en exceso al ejército de Marmont y golpea en los cuarenta minutos que lo arruinan: «la más hábil de mis victorias», en sus propias palabras.' },
  nb_smolensk: { n: 'Batalla de Smolensk', p: 'Smolensk, Rusia', d: 'La Grande Armée toma una ciudad en llamas sin encontrar la decisión: el ejército de Kutúzov escapa al este y atrae a los franceses cada vez más hondo en Rusia.' },
  nb_borodino: { n: 'Batalla de Borodinó', p: 'Borodino, Rusia', d: 'El día más sangriento de las guerras napoleónicas: el Gran Reducto se toma y se retoma, caen 70 000 hombres, y el ejército de Kutúzov se retira intacto para volver a luchar.' },
  nb_maloyaroslavets: { n: 'Batalla de Máloyaroslávets', p: 'Máloyaroslávets, Rusia', d: 'Una pequeña ciudad cambia de manos ocho veces; cuando se disipa el polvo, Napoleón renuncia al nuevo camino del sur y regresa a la calzada calcinada que viene de Moscú: la retirada queda sellada.' },
  nb_berezina: { n: 'Batalla del Berezina', p: 'Berezina, Rusia', d: 'Los pontoneros de Éblé construyen puentes sobre un río helado mientras ambas orillas arden: la Grande Armée escapa de una trampa fatal y en francés «Bérézina» se convierte en sinónimo de desastre sobrevivido.' },
  nb_lutzen: { n: 'Batalla de Lützen', p: 'Lützen, Alemania', d: 'Napoleón, de regreso de Rusia con un ejército de reclutas bisoños, sorprende a los aliados en los campos de girasoles donde cayó Gustavo Adolfo 180 años antes: estos vuelven a escabullirse de noche.' },
  nb_bautzen: { n: 'Batalla de Bautzen', p: 'Bautzen, Alemania', d: 'Una victoria de dos días sin su trampa: una orden perdida permite a los aliados escapar al este; ambos bandos aceptan el Armisticio de Pläswitz y se ponen a contar reclutas.' },
  nb_grossbeeren: { n: 'Batalla de Grossbeeren', p: 'Grossbeeren, Alemania', d: 'La marcha de Oudinot sobre Berlín se detiene en plena tormenta ante los prusianos de Bülow, muchos de ellos Landwehr bisoños, y la capital queda fuera del alcance francés para siempre.' },
  nb_dresden: { n: 'Batalla de Dresde', p: 'Dresde, Alemania', d: 'La última gran victoria de Napoleón en suelo alemán: un contraataque de la guarnición, en inferioridad numérica, se traga 35 000 prisioneros aliados; los aliados cobran la revancha a los pocos días en Kulm.' },
  nb_kulm: { n: 'Batalla de Kulm', p: 'Kulm, Bohemia', d: 'Vandamme persigue por los pasos de montaña y queda atrapado en la boca del valle: 13 000 prisioneros franceses equilibran las cuentas de Dresde.' },
  nb_dennewitz: { n: 'Batalla de Dennewitz', p: 'Dennewitz, Alemania', d: 'Una segunda marcha sobre Berlín muere ante un contragolpe prusiano que hace añicos el cuerpo de Ney: los suecos de Bernadotte cierran el flanco.' },
  nb_leipzig: { n: 'Batalla de Leipzig', p: 'Leipzig, Alemania', d: 'La Batalla de las Naciones: 600 000 hombres durante cuatro días, la mayor batalla de Europa hasta la Guerra Mundial; el cuerpo sajón deserta en pleno combate y el Imperio al este del Rin queda acabado.' },
  nb_hanau: { n: 'Batalla de Hanau', p: 'Hanau, Alemania', d: 'Wrede intenta cerrar tras el Kinzig el camino de vuelta a los franceses; la Grande Armée en retirada lo arrolla de todos modos y llega al Rin.' },
  nb_victoria: { n: 'Batalla de Vitoria', p: 'Vitoria, España', d: 'El ejército francés se disuelve en un atasco de carromatos de botín en el camino a Francia: José Bonaparte pierde España, su trono y su vajilla de plata.' },
  nb_la_rothiere: { n: 'Batalla de La Rothière', p: 'La Rothière, Francia', d: 'Napoleón ataca a las columnas aliadas en las nieves de Champaña y, por primera vez, la batalla se le cuenta en contra.' },
  nb_montmirail: { n: 'Batalla de Montmirail', p: 'Montmirail, Francia', d: 'La Campaña de los Seis Días en su apogeo: dos ejércitos aliados derrotados uno tras otro por la misma fuerza francesa en dos días; la vieja magia regresa por un instante.' },
  nb_craonne: { n: 'Batalla de Craonne', p: 'Craonne, Francia', d: 'La Guardia joven se desangra asaltando la meseta sobre el Chemin des Dames: una victoria comprada a un precio que estremece incluso a los mariscales; el camino a Laón sigue cerrado.' },
  nb_paris_battle: { n: 'Batalla de París (1814)', p: 'París, Francia', d: 'Seis días de asalto aliado; los mariscales entregan la capital y Napoleón, abandonado por su propio Senado, abdica en Fontainebleau antes de que acabe la semana.' },
  nb_toulouse: { n: 'Batalla de Toulouse', p: 'Toulouse, Francia', d: 'Las trincheras de Soult cuestan al ejército peninsular su tarde más sangrienta en suelo francés: ambos bandos siguen peleando una guerra que terminó cuando París cayó y Napoleón abdicó.' },
  nb_ligny: { n: 'Batalla de Ligny', p: 'Ligny, Bélgica', d: 'La última victoria de Napoleón: los prusianos son rechazados más allá del arroyo de Ligny y el viejo Blücher es derribado de su caballo en una carga de caballería; aun así el ejército no se rompe, y marchará.' },
  nb_quatre_bras: { n: 'Batalla de Quatre Bras', p: 'Quatre Bras, Bélgica', d: 'El lento asalto de Ney se estrella contra la línea de Wellington, llegada justamente a tiempo, entre el centeno: el cruce resiste y los dos ejércitos de la Coalición convergen en Waterloo dos días después.' },
  nb_wavre: { n: 'Batalla de Wavre', p: 'Wavre, Bélgica', d: 'Grouchy pelea un combate secundario en Wavre mientras retumban los cañones de Waterloo: 33 000 hombres y la campaña dependen de una marcha que nunca llega a hacer.' },
});

/* es translations — la ruta de Alejandro Magno (2026-10-30) */
Object.assign(window.DATA_ES, {
  aw_granicus: { n: 'Batalla del Gránico', p: 'Río Gránico, Anatolia', d: 'En su primera gran batalla en Asia, Alejandro carga por el río casi contra el centro persa y roza la muerte — pero la caballería de los hetairoi dispersa la línea de los sátrapas; el camino hacia el imperio de Darío queda abierto.' },
  aw_issus: { n: 'Batalla de Issos', p: 'Issos, Cilicia', d: 'Darío III se cuela por la retaguardia de Alejandro en Cilicia — y lo espera en una llanura costera demasiado estrecha para su número; el Gran Rey huye abandonando a su madre, a su esposa y su tienda dorada, y Alejandro rechaza todas las ofertas de paz.' },
  aw_tyre: { n: 'Sitio de Tiro', p: 'Tiro, Fenicia', d: 'Tiro se niega a recibir a Alejandro y resiste siete meses desde su isla, a media milla de la costa; él construye un malecón a través del mar — el gran sitio de ingeniería de la Antigüedad, que acaba con asalto, matanza y 30.000 habitantes vendidos como esclavos.' },
  aw_alexandria_found: { n: 'Fundación de Alejandría', p: 'Delta del Nilo, Egipto', d: 'De regreso del oráculo de Amón en Siwa, Alejandro traza Alejandría junto a la isla de Faros cantada por Homero — la ciudad que será capital de los Ptolomeos y sede de la Biblioteca, el Museo y el faro de Pharos.' },
  aw_gaugamela: { n: 'Batalla de Gaugamela', p: 'Gaugamela, Asiria', d: 'Darío allana el terreno para sus carros de guadañas y un ejército inmenso; Alejandro desliza su línea a la derecha y clava la cuña en el centro persa — el Gran Rey huye a Ecbatana, y Babilonia, Susa y Persépolis abren sus puertas.' },
  aw_persian_gate: { n: 'Batalla de la Puerta Persa', p: 'Montes Zagros, Persia', d: 'Ariobarzanes cierra el paso estrecho con unos miles de hombres y detiene semanas al ejército entero — las Termópilas al revés; Alejandro divide sus tropas y lo flanquea entre nieves, con Persépolis y su tesoro a la vuelta del desfiladero.' },
  aw_alexandria_eschate: { n: 'Fundación de Alejandría Eschate', p: 'Yaxartes, Sogdiana', d: 'En el Yaxartes — para los griegos el confín del mundo — Alejandro funda «Alejandría la Extrema», la actual Juyand, y derrota a los jinetes escitas que cruzan el río para enfrentarlo.' },
  aw_hydaspes: { n: 'Batalla del Hídaspes', p: 'Río Hídaspes, India', d: 'Bajo la lluvia monzónica Alejandro cruza de noche el río desbordado con parte del ejército y vence a los 200 elefantes de Poros — su victoria más costosa; en el Hífasis los veteranos se niegan a seguir hacia el este, y Alejandro regresa.' },
  ww_sarajevo: { n: 'El atentado de Sarajevo', p: 'Sarajevo, Bosnia', d: 'Gavrilo Princip dispara contra el archiduque Francisco Fernando en la esquina del puente Latino — la chispa que el ultimátum de Viena convierte en una guerra europea general en apenas cinco semanas.' },
  ww_july_crisis: { n: 'La Crisis de Julio', p: 'Viena, Austria', d: 'Un mes de ultimátums y de relojes de movilización: Viena castiga a Serbia, Berlín extiende el “cheque en blanco”, Rusia moviliza — y los plazos de cada estado mayor encienden una guerra que nadie puede detener.' },
  ww_frontiers: { n: 'Batalla de las Fronteras', p: 'Charleroi, Bélgica', d: 'El Plan XVII francés marcha contra los cañones alemanes en Lorena y las Ardenas; en Mons la pequeña Fuerza Expedicionaria Británica dispara sus primeros tiros — y luego todos los Aliados retroceden ante el avance Schlieffen.' },
  ww_tannenberg: { n: 'Batalla de Tannenberg', p: 'Stębark (Tannenberg), Prusia Oriental', d: 'Hindenburg y Ludendorff cercan al Segundo Ejército de Samsónov en los lagos de Prusia Oriental — 90.000 prisioneros, el general se quita la vida de un disparo, y nace la leyenda alemana del Frente Oriental.' },
  ww_galicia_1914: { n: 'Batalla de Galitzia', p: 'Leópolis, Galitzia', d: 'La mayor batalla de 1914: los ejércitos rusos rompen el frente austrohúngaro, toman Leópolis y llegan a los Cárpatos — el imperio pierde su mejor ejército de campaña, y la guerra llega a suelo ucraniano.' },
  ww_marne_1: { n: 'Primera batalla del Marne', p: 'el Marne, Francia', d: 'El contragolpe de Joffre — los taxis de París llevando reservas al frente — quiebra el empuje alemán sobre París; la guerra de movimiento acaba en líneas de trincheras que apenas se moverán en cuatro años.' },
  ww_masurian_1: { n: 'Primera batalla de los Lagos Mázures', p: 'Lagos Mázures, Prusia Oriental', d: 'Una segunda victoria alemana expulsa de Prusia al Primer Ejército de Rennenkampf — y el Frente Oriental se estabiliza en el saliente polaco durante el invierno.' },
  ww_antwerp: { n: 'Sitio de Amberes', p: 'Amberes, Bélgica', d: 'Los obuses pesados de Alemania revientan en diez días la última fortaleza de Bélgica; el ejército belga escapa por la costa — y el Frente Occidental se estira hasta el mar del Norte.' },
  ww_ypres_1: { n: 'Primera batalla de Ypres', p: 'Ypres, Bélgica', d: 'Alrededor de la ciudad textil flamenca, el ejército regular británico de preguerra se consume defendiendo el último rincón libre de Bélgica — aquí mueren los “Old Contemptibles”, y nace el saliente de Ypres.' },
  ww_kolubara: { n: 'Batalla de Kolubara', p: 'Kolubara, Serbia', d: 'Serbia contraataca a través del barro invernal y recupera Belgrado — la primera victoria clara de la Entente sobre Austria-Hungría, ganada por veteranos de dos guerras balcánicas.' },
  ww_coronel: { n: 'Batalla de Coronel', p: 'Frente a Coronel, Chile', d: 'La escuadra del Asia Oriental del conde von Spee hunde dos cruceros acorazados británicos frente a Chile — la primera derrota naval de Gran Bretaña en un siglo — y la Royal Navy sale a darle caza por medio mundo.' },
  ww_falkland_battle: { n: 'Batalla de las Islas Malvinas (1914)', p: 'Islas Malvinas', d: 'Cinco semanas después de Coronel, los cruceros de batalla de Sturdee lo vengan: la escuadra de von Spee es destruida en el Atlántico Sur, y la guerra naval alemana de ultramar ha terminado.' },
  ww_tsingtao: { n: 'Sitio de Tsingtao', p: 'Tsingtao (Qingdao), China', d: 'Japón, aliado de Gran Bretaña, asalta el puerto fortificado alemán en China — la única gran batalla de la guerra en Asia Oriental, y la baza de Japón para reclamar un asiento de gran potencia en la paz.' },
  ww_christmas_truce: { n: 'La Tregua de Navidad', p: 'Ploegsteert, Bélgica', d: 'A lo largo de tramos del Frente Occidental, soldados alemanes y británicos se encuentran en tierra de nadie — villancicos, cigarrillos, fútbol — algo tan alarmante para los altos mandos que jamás se volverá a permitir.' },
  ww_east_africa: { n: 'Campaña de África Oriental', p: 'Dar es Salaam, África Oriental Alemana', d: 'El general von Lettow-Vorbeck fija a cientos de miles de tropas aliadas en cuatro años de guerra en la maleza — y se rinde en Rodesia del Norte, invicto, once días después del Armisticio.' },
  ww_sarikamish: { n: 'Batalla de Sarikamish', p: 'Sarikamish, Cáucaso', d: 'La ofensiva invernal de Enver Pachá hacia el Cáucaso se desploma en la nieve — un ejército de 90.000 hombres queda destrozado, y la propaganda de guerra busca un culpable: los armenios.' },
  ww_dogger_bank: { n: 'Batalla del Banco Dogger', p: 'Mar del Norte', d: 'Los cruceros de batalla británicos interceptan una incursión alemana contra la costa de Yorkshire y hunden el crucero acorazado Blücher — la primera señal de que la Flota de Alta Mar prefiere el puerto al combate.' },
  ww_przemysl: { n: 'Sitio de Przemyśl', p: 'Przemyśl, Galitzia', d: 'La gran fortaleza galitziana de Austria-Hungría cae en marzo tras seis meses — 120.000 prisioneros, el mayor asedio de la guerra — y sus cañones apenas se han enfriado cuando Gorlice abre la retirada rusa.' },
  ww_ypres_2: { n: 'Segunda batalla de Ypres', p: 'Ypres, Bélgica', d: 'El gas de cloro deriva sobre las trincheras por primera vez en la historia; los canadienses cierran la línea rota — y la guerra química se convierte en un hecho del siglo XX.' },
  ww_gallipoli: { n: 'Campaña de Gallípoli', p: 'Península de Gallípoli, Imperio otomano', d: 'El intento de la Entente de forzar los Dardanelos muere en los acantilados: el desembarco del ANZAC, nueve meses de estancamiento, un cuarto de millón de bajas — y una evacuación secreta que se convierte en el recuerdo fundacional de Australia, Nueva Zelanda y Turquía.' },
  ww_armenian: { n: 'Genocidio armenio', p: 'Constantinopla, Imperio otomano', d: 'El 24 de abril el gobierno otomano detiene a la élite armenia de Constantinopla y comienza las deportaciones hacia el desierto sirio — alrededor de un millón de personas mueren en el camino: el primer genocidio del siglo XX.' },
  ww_gorlice: { n: 'Ofensiva de Gorlice-Tarnów', p: 'Gorlice, Galitzia', d: 'La ruptura germano-austriaca de Mackensen desgarra el frente ruso en Galitzia — Przemyśl y Leópolis recuperadas en semanas, y los ejércitos del zar inician la “Gran Retirada”.' },
  ww_lusitania: { n: 'Hundimiento del Lusitania', p: 'Frente a Kinsale, Irlanda', d: 'Un solo torpedo manda al fondo al gran transatlántico en dieciocho minutos — 1.198 muertos, 128 de ellos estadounidenses — y la primera campaña de guerra submarina indiscriminada de Alemania se suspende ante la protesta estadounidense.' },
  ww_italy_enters: { n: 'Italia entra en la guerra', p: 'Roma, Italia', d: 'Gran Bretaña se gana a Roma con el secreto Tratado de Londres: Italia declara la guerra a Austria-Hungría “por Trento y Trieste” — y abre un frente de montaña que costará un millón de bajas.' },
  ww_isonzo: { n: 'Once batallas del Isonzo', p: 'Gorizia, Italia', d: 'Los ejércitos de Cadorna se lanzan once veces en dos años contra el karst sobre el Isonzo por unos pocos kilómetros de valle pedregoso — el duodécimo intento, en Caporetto, romperá en la dirección contraria.' },
  ww_warsaw_1915: { n: 'Caída de Varsovia', p: 'Varsovia, Polonia', d: 'Para agosto los ejércitos del zar abandonan Varsovia, Vilna y la mayor parte de Polonia — el frente se estabiliza a un año de marcha hacia el este, y Rusia se convierte en la gran potencia menos fiable de la guerra.' },
  ww_serbia_1915: { n: 'Caída de Serbia', p: 'Belgrado, Serbia', d: 'Bulgaria se suma a las Potencias Centrales y tres ejércitos aplastan a Serbia en seis semanas; el ejército derrotado se retira por las montañas albanesas hasta Corfú — y nace el frente aliado de Salónica.' },
  ww_kut: { n: 'Sitio de Kut', p: 'Kut, Mesopotamia', d: 'La división angloindia de Townshend queda sitiada en el barro mesopotámico durante 147 días; todo intento de socorro fracasa — la peor humillación de Gran Bretaña en la guerra, y la mitad de los prisioneros muere en cautiverio.' },
  ww_verdun: { n: 'Batalla de Verdún', p: 'Verdún, Francia', d: '“No pasarán”: la máquina de Falkenhayn para desangrar a Francia machaca durante diez meses en las colinas del Mosa — 700.000 bajas, la batalla más larga de la historia, la epopeya nacional de Francia.' },
  ww_sykes_picot: { n: 'Acuerdo Sykes-Picot', p: 'Londres', d: 'Un diplomático británico y otro francés reparten el Oriente Medio de la posguerra con un lápiz — Siria para París, Mesopotamia para Londres — un mapa tan secreto que su publicación por los bolcheviques en 1917 hace añicos la confianza árabe.' },
  ww_jutland: { n: 'Batalla de Jutlandia', p: 'Mar del Norte, frente a Jutlandia', d: 'El único choque de las grandes flotas de acorazados dreadnought: 250 barcos, 8.600 muertos — Alemania hunde más tonelaje, Gran Bretaña mantiene el bloqueo, y ambos bandos reclaman el mar.' },
  ww_brusilov: { n: 'Ofensiva Brusilov', p: 'Luck, Volinia', d: 'La última gran victoria de Rusia: ataques por sorpresa en un frente de 500 km en Volinia y Galitzia destrozan a los ejércitos de Austria-Hungría — 400.000 prisioneros — pero las pérdidas quiebran al ejército del zar, y la revolución está a un año.' },
  ww_arab_revolt: { n: 'Revolución árabe', p: 'Medina, Hiyaz', d: 'El jerife de La Meca se alza contra los otomanos con oro y fusiles británicos: las razias del desierto y Lawrence cabalgan hacia la leyenda — y a Damasco le prometen un reino hachemita.' },
  ww_somme: { n: 'Batalla del Somme', p: 'el Somme, Francia', d: '57.470 bajas británicas la primera mañana; los tanques aparecen en septiembre; cuando la lluvia de noviembre la acaba, medio millón de hombres yacen muertos por diez kilómetros de Picardía — la imagen perdurable del despilfarro de la guerra.' },
  ww_bucharest: { n: 'Rumanía entra en la guerra', p: 'Bucarest, Rumanía', d: 'Bucarest apuesta por la Entente mientras Brusílov avanza — y lo pierde todo en cuatro meses: Transilvania invadida, la capital tomada en diciembre, el gobierno en el exilio en Iaşi.' },
  ww_zimmermann: { n: 'El telegrama Zimmermann', p: 'Ciudad de México, México', d: 'Los descifradores de Londres entregan a Washington la oferta de Berlín a México — Texas, Arizona, Nuevo México por una alianza; publicada en la prensa estadounidense, hace más que ningún U-Boot para acabar con la neutralidad de Estados Unidos.' },
  ww_unrestricted: { n: 'Guerra submarina indiscriminada', p: 'Berlín, Alemania', d: 'Los almirantes alemanes prometen hacer rendir a Gran Bretaña por hambre en cinco meses — y cada barco mercante del Atlántico se convierte en objetivo, con consecuencias en Washington que no habían contado.' },
  ww_us_enters: { n: 'Estados Unidos entra en la guerra', p: 'Washington, EE. UU.', d: '“El mundo debe hacerse seguro para la democracia”: Wilson pide al Congreso la guerra en abril de 1917 — dos millones de estadounidenses cruzan el Atlántico, y la Entente gana un arsenal que no puede agotarse.' },
  ww_nivelle: { n: 'Ofensiva Nivelle y los motines', p: 'Chemin des Dames, Francia', d: 'Nivelle promete la ruptura en 48 horas; cuando el milagro fracasa, la mitad del ejército francés se niega a seguir atacando — 68 divisiones amotinadas, sofocadas discretamente por las reformas de Pétain.' },
  ww_kerensky: { n: 'Ofensiva Kerensky', p: 'Ternópil, Galitzia', d: 'La última apuesta del Gobierno Provisional — un ataque en Galitzia para demostrar que la Rusia revolucionaria sigue peleando; se derrumba en días, y cientos de miles de desertores llevan sus fusiles a casa, a los sóviets.' },
  ww_riga_1917: { n: 'Caída de Riga', p: 'Riga, Letonia', d: 'Las nuevas tácticas alemanas de tropas de asalto conquistan Riga y luego las islas estonias (Operación Albion) — un ensayo para 1918 en un frente que ya se está deshaciendo.' },
  ww_passchendaele: { n: 'Tercera batalla de Ypres', p: 'Passchendaele, Bélgica', d: 'La ofensiva de Haig en Flandes se ahoga en el otoño más lluvioso en treinta años — medio millón de bajas entre ambos bandos por ocho kilómetros de barro; Passchendaele se convierte en el sinónimo de futilidad de la guerra.' },
  ww_caporetto: { n: 'Batalla de Caporetto', p: 'Caporetto (Kobarid), Eslovenia', d: 'Las tropas de montaña alemanas y el gas lanzan al Segundo Ejército italiano a una fuga de 100 km — 265.000 prisioneros; Cadorna es destituido, y Italia solo conserva la línea del Piave.' },
  ww_balfour: { n: 'La Declaración Balfour', p: 'Londres', d: 'Una carta de 67 palabras del ministro de Exteriores británico respalda “un hogar nacional para el pueblo judío” en Palestina — una frase de la diplomacia en tiempos de guerra cuyas consecuencias se discuten un siglo después.' },
  ww_cambrai: { n: 'Batalla de Cambrai', p: 'Cambrai, Francia', d: 'Casi 400 tanques y ningún bombardeo preliminar: el 20 de noviembre el primer ataque masivo de tanques agrieta la Línea Hindenburg — y el contraataque alemán diez días después enseña a ambos bandos las reglas de la nueva guerra.' },
  ww_jerusalem: { n: 'Gran Bretaña toma Jerusalén', p: 'Jerusalén, Palestina', d: 'Allenby entra a pie — no a caballo — en la Ciudad Santa el 11 de diciembre, poniendo fin a cuatro siglos de dominio otomano; Gaza y Berseba ya han caído en el camino que terminará en Damasco.' },
  ww_brest_litovsk: { n: 'Tratado de Brest-Litovsk', p: 'Brest-Litovsk, Bielorrusia', d: 'En la fortaleza de Brest las Potencias Centrales hacen primero la paz con la República Popular Ucraniana (9 de febrero, reconociendo su independencia) y después con la Rusia soviética — Alemania se lleva un cuarto del viejo imperio, y lo pierde antes de que acabe el año.' },
  ww_spring_offensive: { n: 'Ofensiva alemana de primavera', p: 'el Somme, Francia', d: 'Los cinco grandes asaltos de Ludendorff — tropas de asalto, gas, y ningún objetivo más allá de la ruptura: los alemanes avanzan más que en ningún momento desde 1914 y se agotan contra una defensa que no se rompe.' },
  ww_czechoslovak_legion: { n: 'La Legión Checoslovaca', p: 'Cheliábinsk, Rusia', d: 'Cincuenta mil ex prisioneros de guerra se abren paso a través de Siberia cuando los soviéticos intentan desarmarlos — se apoderan del ferrocarril Transiberiano — y obligan a los Aliados a reconocer una Checoslovaquia independiente.' },
  ww_marne_2: { n: 'Segunda batalla del Marne', p: 'el Marne, Francia', d: 'La última ofensiva alemana vuelve a agotarse en el Marne — y el contragolpe aliado trae 85.000 estadounidenses recién llegados y cientos de tanques ligeros; desde julio de 1918 la Entente no deja de avanzar.' },
  ww_amiens: { n: 'Batalla de Amiens', p: 'Amiens, Francia', d: 'Tanques, aviación y un barrage silencioso avanzan once kilómetros el 8 de agosto — el “día negro del ejército alemán” de Ludendorff: los Cien Días siguen su marcha hasta la frontera belga.' },
  ww_meuse_argonne: { n: 'Ofensiva de Meuse-Argonne', p: 'Bosque de Argona, Francia', d: 'Un millón y cuarto de tropas estadounidenses se abren paso por la Argona durante 47 días — la mayor batalla de la historia de Estados Unidos — para cortar la última línea férrea del ejército alemán fuera de Francia.' },
  ww_megiddo: { n: 'Batalla de Meguido', p: 'Meguido, Palestina', d: 'La obra maestra de armas combinadas de Allenby captura a todo el ejército otomano de Palestina en 38 días — Lawrence cabalga por delante hacia Damasco — y la guerra de Oriente Medio termina dos meses antes del Armisticio.' },
  ww_vittorio_veneto: { n: 'Batalla de Vittorio Veneto', p: 'Vittorio Veneto, Italia', d: 'La revancha de Italia por Caporetto: el frente de los Habsburgo se desintegra en una semana y 400.000 se rinden — Austria-Hungría, en armas desde hacía cuatro años, firma un armisticio que es en realidad una disolución.' },
  ww_mudros: { n: 'Armisticio de Mudros', p: 'Moudros, Lemnos', d: 'En Lemnos el Imperio otomano firma su salida de la guerra el 30 de octubre — los Estrechos se abren, y la flota británica surca los Dardanelos que no pudo tomar en 1915.' },
  ww_villa_giusti: { n: 'Armisticio de Villa Giusti', p: 'Padua, Italia', d: 'La monarquía de los Habsburgo firma su armisticio en Padua el 3 de noviembre — pero el imperio ya se ha disuelto en estados sucesores checoslovaco, polaco, yugoslavo, húngaro y austríaco.' },
  ww_kiel_mutiny: { n: 'Motín de Kiel y Revolución de Noviembre', p: 'Kiel, Alemania', d: 'Los marineros se niegan a una última salida suicida, la bandera roja ondea sobre la flota, los consejos toman cada ciudad alemana — el 9 de noviembre se proclama la República y el káiser huye a Holanda.' },
  ww_armistice: { n: 'Armisticio del 11 de noviembre de 1918', p: 'Rethondes, Francia', d: 'En un vagón de ferrocarril del bosque de Compiègne las delegaciones firman a las 5:10 de la madrugada, y los cañones callan a las once — veinte millones de muertos — “un armisticio para veinte años”, dirá Foch, y se equivocará por solo dos meses.' },
  ww_poland_1918: { n: 'Polonia restaurada', p: 'Varsovia, Polonia', d: 'El día que termina la guerra, Piłsudski toma el mando en Varsovia: tras 123 años de particiones, Polonia vuelve al mapa — con fronteras todavía por pelear.' },
  ww_czechoslovakia: { n: 'Fundación de Checoslovaquia', p: 'Praga, República Checa', d: 'El 28 de octubre el Comité Nacional toma el poder en Praga: una república de checos y eslovacos, construida por Masaryk desde el Acuerdo de Pittsburgh hasta el reconocimiento de París — la única democracia nueva estable de la Europa de entreguerras.' },
  ww_habsburg_end: { n: 'Austria-Hungría se disuelve', p: 'Viena, Austria', d: 'En las últimas semanas de octubre de 1918 las naciones del imperio simplemente lo abandonan — Praga, Zagreb, Budapest y Viena proclaman sus propios estados; la monarquía de los Habsburgo no acaba por tratado, sino por vacío.' },
  ww_yugoslavia: { n: 'Yugoslavia proclamada', p: 'Belgrado, Serbia', d: 'El Estado de los Eslovenos, Croatas y Serbios se fusiona con Serbia el 1 de diciembre — un reino de tres nombres, dos alfabetos y cuatro religiones, ensamblado con los restos de Austria-Hungría.' },
  ww_russian_civil_war: { n: 'Guerra civil rusa', p: 'Tsaritsyn, Rusia', d: 'Rojos contra Blancos del Báltico al Pacífico, con una docena de ejércitos extranjeros y la Legión Checa en medio — tres años, diez millones de muertos, y el Estado de partido único: la URSS se proclama en 1922.' },
  ww_saint_germain: { n: 'Tratado de Saint-Germain', p: 'Saint-Germain-en-Laye, Francia', d: 'Austria se firma a sí misma hasta quedar reducida a una república residual de siete millones — el Tirol del Sur para Italia, Galitzia para Polonia, los Sudetes para Checoslovaquia — y hasta la palabra “Anschluss” queda prohibida.' },
  ww_weimar: { n: 'República de Weimar', p: 'Weimar, Alemania', d: 'La primera democracia alemana nace de la revolución y la derrota — una constitución de maravillas, sufragio femenino incluido — pero sus enemigos la culpan de Versalles y sus amigos no la defienden hasta que ya es demasiado tarde.' },
  ww_neuilly: { n: 'Tratado de Neuilly', p: 'Neuilly, Francia', d: 'Bulgaria, la primera en quebrarse, pierde la costa del Egeo y paga reparaciones — el mapa balcánico retocado, y nada resuelto.' },
  ww_league: { n: 'Fundación de la Sociedad de Naciones', p: 'Ginebra, Suiza', d: 'El Pacto entra en vigor en enero de 1920: la primera organización mundial por la paz, el Premio Nobel de Wilson — y, sin Estados Unidos, un guardián demasiado débil para los años treinta.' },
  ww_trianon: { n: 'Tratado de Trianon', p: 'Versalles, Francia', d: 'Hungría pierde dos tercios de su territorio y el sesenta por ciento de su población ante Rumanía, Checoslovaquia y Yugoslavia — una herida que organiza la política húngara hasta hoy.' },
  ww_sevres: { n: 'Tratado de Sèvres', p: 'Sèvres, Francia', d: 'El tratado que repartiría Anatolia — Esmirna para Grecia, los Estrechos internacionalizados — lo firma un sultán que ya no controla el país: la Ankara de Kemal lo rechaza, y la lucha vuelve a empezar.' },
  ww_turkish_war: { n: 'Guerra de Independencia Turca', p: 'Ankara, Turquía', d: 'Desde Ankara, Mustafa Kemal lucha contra el sultán, los griegos y la Entente hasta una victoria que nadie esperaba: la República de Turquía se proclama en 1923, y el Sultanato queda abolido.' },
  ww_lausanne: { n: 'Tratado de Lausana', p: 'Lausana, Suiza', d: 'El tratado que sustituye a Sèvres reconoce la nueva Turquía, ratifica un intercambio greco-turco de 1,6 millones de personas, y cierra la Cuestión de Oriente que había empezado con el Enfermo de Europa.' },
});

/* ww2 translations — World War II batch (79 entries, 2026-10-31) */
Object.assign(window.DATA_ES, {
  ww2_unit_731: { n: 'Unidad 731', p: 'Pingfang, Manchuria', d: 'En un recinto secreto cerca de Harbin, la «unidad de purificación de agua» de Shiro Ishii convierte en armas la peste, el ántrax y el cólera y los prueba con miles de prisioneros —y luego canjea todos sus datos con los estadounidenses a cambio de la impunidad.' },
  ww2_marco_polo: { n: 'Segunda guerra sino-japonesa', p: 'Wanping, China', d: 'Una escaramuza nocturna en el puente Marco Polo el 7 de julio de 1937 deriva en la invasión total de China por Japón: Shanghái y Nankín arden y los nacionalistas se repliegan por el Yangtsé hacia Chongqing —una guerra de desgaste de ocho años que se funde con la segunda guerra mundial.' },
  ww2_nanjing: { n: 'Masacre de Nankín', p: 'Nankín, China', d: 'Las tropas japonesas asaltan la capital china y matan durante seis semanas: hasta 300.000 soldados y civiles muertos, decenas de miles de mujeres violadas —«la violación de Nankín» conmociona al mundo.' },
  ww2_anschluss: { n: 'Anschluss', p: 'Viena, Austria', d: 'Las tropas alemanas entran en Austria sin oposición y son recibidas con flores; los judíos de Viena son obligados a fregar las calles. El mapa de Europa se redibuja sin disparar un tiro.' },
  ww2_munich: { n: 'Acuerdo de Múnich', p: 'Múnich, Alemania', d: 'Reino Unido y Francia entregan a Hitler los Sudetes para comprar «la paz de nuestro tiempo». Seis meses después se traga el resto de Checoslovaquia —el emblema del apaciguamiento, y el camino hacia Polonia.' },
  ww2_kristallnacht: { n: 'Noche de los Cristales Rotos', p: 'Berlín, Alemania', d: 'Por todo el Reich arden sinagogas y unas 7.500 tiendas judías quedan destrozadas en una sola noche coordinada; 30.000 hombres judíos son enviados a campos —el crescendo inicial del Holocausto.' },
  ww2_khalkhin_gol: { n: 'Batallas de Jaljin Gol', p: 'Jaljin Gol, Mongolia', d: 'Los tanques y la artillería de Zhúkov aniquilan al Ejército de Kwantung en la estepa mongola; Tokio gira hacia el sur, hacia el Pacífico, y no hacia el norte —una decisión que configura 1941.' },
  ww2_molotov_ribbentrop: { n: 'Pacto Molotov–Ribbentrop', p: 'Moscú, URSS', d: 'Los dos grandes enemigos firman un tratado de no agresión con un protocolo secreto que divide la Europa oriental en esferas de influencia —Polonia, el Báltico, Besarabia y Finlandia asignadas de la noche a la mañana.' },
  ww2_poland_invasion: { n: 'Invasión de Polonia', p: 'Westerplatte, Danzig, Polonia', d: 'Al amanecer, el viejo acorazado Schleswig-Holstein abre fuego contra Westerplatte —los primeros disparos de la segunda guerra mundial. Guerra relámpago, Stukas y un millón y medio de hombres aplastan Polonia en cinco semanas.' },
  ww2_anglo_french_decl: { n: 'Reino Unido y Francia declaran la guerra', p: 'Londres, Reino Unido', d: 'Dos días después de la invasión de Polonia, Chamberlain comunica por radio que Reino Unido está en guerra con Alemania; Francia le sigue horas más tarde. Ha comenzado el conflicto más mortífero de la historia.' },
  ww2_soviet_poland: { n: 'Invasión soviética de Polonia', p: 'Brest, Polonia', d: 'Stalin cobra su parte del protocolo secreto: el 17 de septiembre el Ejército Rojo entra en el este de Polonia, y un desfile conjunto germano-soviético marca la nueva frontera en Brest.' },
  ww2_enigma: { n: 'Bletchley Park — descifrar Enigma', p: 'Bletchley Park, Reino Unido', d: 'Una finca secreta de matemáticos, campeones de crucigramas y los primeros ordenadores electrónicos del mundo descifra las máquinas cifradoras alemanas; los convoyes esquivan a las manadas de submarinos y la guerra se acorta en años.' },
  ww2_atlantic: { n: 'Batalla del Atlántico', p: 'Atlántico norte', d: 'La campaña más larga de la guerra: manadas de submarinos contra convoyes, portaviones de escolta y descifradores de códigos por la línea de vida que mantiene a Reino Unido alimentado y al Ejército Rojo abastecido —3.500 barcos mercantes y 783 submarinos perdidos.' },
  ww2_katyn: { n: 'Masacre de Katyn', p: 'Katyn, URSS', d: 'Por orden de Stalin, el NKVD fusila a 22.000 oficiales, policías e intelectuales polacos —del bosque de Katyn a los campos de Starobilsk y Ostashkov— y culpa a los alemanes durante cincuenta años.' },
  ww2_dunkirk: { n: 'Evacuación de Dunkerque', p: 'Dunkerque, Francia', d: 'Atrapados contra el Canal, 338.000 soldados británicos y franceses son llevados a casa por destructores, barcos pesqueros y vapores de placer —«el milagro de la liberación» que mantiene a Reino Unido en la guerra.' },
  ww2_france_falls: { n: 'Caída de Francia', p: 'Compiègne, Francia', d: 'El ejército que resistió en 1918 se derrumba en seis semanas; Hitler hace firmar a los franceses en el mismo vagón de ferrocarril donde Alemania capituló en 1918. La mitad del país cae bajo el dominio de Vichy.' },
  ww2_vichy: { n: 'Francia de Vichy', p: 'Vichy, Francia', d: 'El Estado colaboracionista del mariscal Pétain sustituye a la República y deporta al este a judíos y disidentes, mientras de Gaulle jura desde Londres que Francia ha «perdido una batalla, no la guerra».' },
  ww2_battle_of_britain: { n: 'Batalla de Inglaterra', p: 'Sur de Inglaterra, Reino Unido', d: '«Nunca tantos debieron tanto a tan pocos»: los Spitfire, los Hurricane y la cadena de radares derrotan a la Luftwaffe en los cielos de Inglaterra —la primera derrota estratégica de la Alemania nazi.' },
  ww2_blitz: { n: 'El Blitz', p: 'Londres, Reino Unido', d: 'Durante 57 noches consecutivas Londres arde bajo las bombas alemanas, y 43.000 civiles mueren en toda Gran Bretaña; los londinenses duermen en las estaciones del metro —y la ciudad sigue funcionando.' },
  ww2_greco_italian: { n: 'Guerra greco-italiana', p: 'Pindo, Grecia', d: 'Mussolini invade Grecia desde Albania el 28 de octubre «para igualar las hazañas de Hitler» —y el ejército griego empuja a los italianos de regreso a las montañas, obligando a Alemania a rescatar a su aliado.' },
  ww2_lend_lease: { n: 'Lend-Lease', p: 'Washington, Estados Unidos', d: 'Roosevelt convierte a Estados Unidos en «el arsenal de la democracia»: unos 50.000 millones de dólares en tanques, camiones, alimentos y combustible de aviación —400.000 camiones y jeeps solo para el Ejército Rojo.' },
  ww2_balkans: { n: 'Invasión de Yugoslavia y Grecia', p: 'Belgrado, Yugoslavia', d: 'Tras un golpe de Estado en Belgrado que rompe el pacto del Eje, la Luftwaffe de Hitler arrasa la ciudad; la Wehrmacht barre los Balcanes en tres semanas —y comienza la mayor guerra partisana de Europa.' },
  ww2_tobruk: { n: 'Asedio de Tobruk', p: 'Tobruk, Libia', d: 'Las «ratas de Tobruk» australianas resisten 241 días en el puerto fortaleza contra el Afrika Korps de Rommel —el primer freno a la marcha del Zorro del Desierto hacia Egipto.' },
  ww2_crete: { n: 'Batalla de Creta', p: 'Creta, Grecia', d: 'El mayor asalto aerotransportado visto hasta entonces: los paracaidistas alemanes toman Creta a un coste tal que Hitler prohíbe para siempre cualquier lanzamiento en masa —pero la isla cae, y el Egeo se convierte en un lago del Eje.' },
  ww2_barbarossa: { n: 'Operación Barbarroja', p: 'Brest, URSS', d: 'Tres millones de soldados del Eje invaden la Unión Soviética en un frente de 2.900 km —la mayor invasión de la historia. Cuatro años y 27 millones de muertos soviéticos después, el Ejército Rojo está en Berlín.' },
  ww2_continuation_war: { n: 'Guerra de Continuación', p: 'Carelia, Finlandia', d: 'Finlandia vuelve a luchar junto a Alemania para recuperar la Carelia perdida, avanza y luego aguanta tres años de guerra de trincheras —y detiene la gran ofensiva soviética de 1944, preservando su independencia.' },
  ww2_leningrad: { n: 'Sitio de Leningrado', p: 'Leningrado, URSS', d: 'Durante 872 días la ciudad sufre bombardeos y hambre: pan racionado a 125 gramos al día, más de un millón de civiles muertos, la Carretera de la Vida sobre el lago Ládoga helado como único hilo —y la ciudad jamás se rinde.' },
  ww2_kyiv_1941: { n: 'Batalla de Kiev (1941)', p: 'Kiev, Ucrania', d: 'El mayor cerco de la historia: cuatro ejércitos soviéticos quedan embolsados al este del Dniéper y más de 600.000 prisioneros marchan hacia los campamentos alemanes. La Kiev ocupada sufre una masacre —y el giro de Guderian hacia el sur retrasa el empuje sobre Moscú.' },
  ww2_moscow: { n: 'Batalla de Moscú', p: 'Moscú, URSS', d: 'Las puntas de lanza alemanas alcanzan las afueras de la capital, el pánico recorre Moscú —entonces llegan en tren divisiones siberianas frescas y Zhúkov contraataca. La guerra relámpago muere en la nieve.' },
  ww2_sevastopol: { n: 'Sitio de Sebastopol', p: 'Sebastopol, Crimea', d: 'La fortaleza naval resiste 250 días contra el 11.º Ejército de Manstein, con el cañón Dora de 80 cm incluido, antes de caer —y la ciudad heroica de la Flota del Mar Negro lo paga en sangre.' },
  ww2_pearl_harbor: { n: 'Ataque a Pearl Harbor', p: 'Pearl Harbor, Hawái, Estados Unidos', d: '«Una fecha que vivirá en la infamia»: 353 aviones embarcados japoneses atacan la Flota del Pacífico estadounidense fondeada —2.400 muertos, ocho acorazados tocados— y Estados Unidos entra en la guerra.' },
  ww2_wannsee: { n: 'Conferencia de Wannsee', p: 'Wannsee, Berlín, Alemania', d: 'Quince funcionarios se reúnen noventa minutos en una villa a orillas del lago para coordinar «la solución final»: los once millones de judíos de Europa quedan programados para la deportación y el asesinato.' },
  ww2_singapore: { n: 'Caída de Singapur', p: 'Singapur', d: '«El peor desastre y la mayor capitulación de la historia británica»: 80.000 soldados de la Commonwealth se rinden ante una fuerza japonesa menor que avanzó en bicicleta por Malasia —el prestigio del imperio nunca se recupera.' },
  ww2_bataan: { n: 'Marcha de la Muerte de Bataán', p: 'Bataán, Filipinas', d: 'Tras la rendición de Bataán, 75.000 prisioneros estadounidenses y filipinos son obligados a marchar 106 km bajo el calor tropical —miles mueren en el camino, y la liberación está a tres años de distancia.' },
  ww2_coral_sea: { n: 'Batalla del Mar del Coral', p: 'Mar del Coral', d: 'La primera batalla naval en la que las flotas nunca llegan a verse —los aviones de los portaaviones golpean tras el horizonte. El empuje japonés hacia Port Moresby es rechazado por primera vez.' },
  ww2_kharkiv_1942: { n: 'Segunda batalla de Járkov', p: 'Járkov, Ucrania', d: 'La ofensiva de primavera de Timoshenko para retomar la ciudad cae en una contratrampa: un cuarto de millón de soldados soviéticos se pierden en la bolsa de Barvenkovo —la catástrofe que abre el camino al Don y a Stalingrado.' },
  ww2_heydrich: { n: 'Asesinato de Heydrich — Lidice', p: 'Praga, Checoslovaquia', d: 'Los paracaidistas checos de la Operación Anthropoid arrojan granadas al coche descubierto del «Verdugo»; las SS arrasan en represalia los pueblos de Lidice y Ležáky y deportan a sus niños.' },
  ww2_midway: { n: 'Batalla de Midway', p: 'Atolón Midway, Pacífico', d: 'Advertidos por los descifradores de códigos, los portaaviones estadounidenses tienden una emboscada a la flota japonesa: en cinco minutos de bombardeo en picado arden cuatro portaaviones —y la balanza de la guerra del Pacífico se decanta el 4 de junio de 1942.' },
  ww2_guadalcanal: { n: 'Campaña de Guadalcanal', p: 'Guadalcanal, Islas Salomón', d: 'Seis meses de jungla, malaria y duelos navales nocturnos en torno a una isla infestada de moscas —la primera ofensiva terrestre estadounidense, donde el avance japonés en el Pacífico se quiebra por fin.' },
  ww2_stalingrad: { n: 'Batalla de Stalingrado', p: 'Stalingrado, URSS', d: 'Cada casa una fortaleza, cada calle una batalla: cinco meses de matanza urbana terminan con 91.000 supervivientes del Sexto Ejército marchando hacia el cautiverio —el punto de inflexión de la guerra en Europa.' },
  ww2_el_alamein: { n: 'Batalla de El Alamein', p: 'El Alamein, Egipto', d: 'El Octavo Ejército de Montgomery rompe la línea de Rommel a cien kilómetros de Alejandría —«antes de Alamein nunca tuvimos una victoria; después de Alamein nunca tuvimos una derrota».' },
  ww2_torch: { n: 'Operación Torch', p: 'Argel, Argelia', d: 'Los desembarcos angloestadounidenses atrapan al ejército de Rommel por la espalda; en mayo de 1943 un cuarto de millón de soldados del Eje se rinde en Túnez, y el Mediterráneo se convierte en un lago aliado.' },
  ww2_manhattan: { n: 'Proyecto Manhattan', p: 'Los Álamos, Estados Unidos', d: 'En laboratorios secretos de Nuevo México, el equipo de Oppenheimer construye la primera bomba atómica —un esfuerzo de 2.000 millones de dólares y 130.000 personas que acabará con la guerra y abrirá la era nuclear.' },
  ww2_bengal_famine: { n: 'Hambruna de Bengala', p: 'Bengala, India británica', d: 'La política bélica de denegación de embarcaciones, el acaparamiento y la negativa del Gabinete de Churchill a los envíos de emergencia abandonan a Bengala a la hambruna mientras la guerra arrasa Birmania —tres millones de personas mueren.' },
  ww2_koriukivka: { n: 'Tragedia de Koriukivka', p: 'Koriukivka, Ucrania', d: 'En represalia por las emboscadas partisanas, unidades alemanas de las SS y húngaras asesinan a unos 6.700 residentes y queman el pueblo de Koriukivka —la mayor matanza aislada de civiles en la Ucrania en guerra.' },
  ww2_khatyn: { n: 'Masacre de Jatyn', p: 'Jatyn, Bielorrusia', d: 'Un batallón punitivo de policía auxiliar bajo supervisión de las SS encierra a los vecinos de una aldea bielorrusa en un granero y los quema vivos —149 personas, 75 de ellas niños; un destino compartido por unas 9.200 aldeas bielorrusas.' },
  ww2_warsaw_ghetto: { n: 'Levantamiento del Gueto de Varsovia', p: 'Varsovia, Polonia', d: 'La mayor revuelta judía de la guerra: combatientes ligeramente armados aguantan casi un mes a los blindados de las SS antes de que el gueto arda —lucharon, como dijeron los supervivientes, para morir a su manera.' },
  ww2_kursk: { n: 'Batalla de Kursk', p: 'Kursk, URSS', d: 'La mayor batalla de blindados de la historia: 6.000 tanques chocan en la estepa mientras la última ofensiva alemana en el este se estrella contra defensas de ocho cinturones de profundidad —a partir de aquí el Ejército Rojo avanza definitivamente.' },
  ww2_dnipro: { n: 'Batalla del Dniéper', p: 'Río Dniéper, Ucrania', d: 'Cinco frentes soviéticos asaltan el gran río en un frente de 1.400 km —pontón tras pontón, exploradores que conquistan cabezas de puente de noche. El «Muro del Este» de la Wehrmacht se rompe, y el camino hacia Kiev y el oeste queda abierto.' },
  ww2_italy_armistice: { n: 'Italia se rinde', p: 'Roma, Italia', d: 'Mussolini es depuesto y encarcelado; Badoglio firma un armisticio con los Aliados —y Alemania desarma a un millón de soldados italianos en cuestión de días y se apodera de la mitad del país.' },
  ww2_kyiv_1943: { n: 'Liberación de Kiev', p: 'Kiev, Ucrania', d: 'El 6 de noviembre de 1943 el Ejército Rojo toma Kiev desde la cabeza de puente de Liutezh —la primera capital republicana ocupada que se recupera; la ciudad emerge de 778 días de ocupación y masacre.' },
  ww2_tehran: { n: 'Conferencia de Teherán', p: 'Teherán, Irán', d: 'Stalin, Roosevelt y Churchill se reúnen por primera vez: el segundo frente queda fijado para mayo de 1944, las fronteras de Polonia esbozadas en la cena —la Gran Alianza en su apogeo.' },
  ww2_monte_cassino: { n: 'Batalla de Monte Cassino', p: 'Monte Cassino, Italia', d: 'Cuatro asaltos en cuatro meses, una abadía del siglo VI reducida a escombros y, al final, tropas polacas izan su bandera sobre las ruinas —la Línea Gustav se rompe y el camino a Roma queda abierto.' },
  ww2_deportations: { n: 'Deportaciones punitivas soviéticas', p: 'Crimea y Cáucaso Norte', d: 'Stalin suprime pueblos enteros declarados «desleales»: la población chechena e ingusha es deportada en vagones de ganado en febrero de 1944, los tártaros de Crimea el 18 de mayo —casi la mitad muere en el camino; solo volverán a casa décadas después.' },
  ww2_bagration: { n: 'Operación Bagration', p: 'Minsk, Bielorrusia', d: 'Tres años exactos después de Barbarroja, el Ejército Rojo destruye el Grupo de Ejércitos Centro —28 divisiones borradas en cinco semanas, la peor derrota de la Wehrmacht, y el frente avanza 600 km hacia el oeste.' },
  ww2_bretton_woods: { n: 'Conferencia de Bretton Woods', p: 'Bretton Woods, Estados Unidos', d: 'Mientras la guerra hace furor, 44 naciones diseñan la paz: nacen el FMI y el Banco Mundial y el dólar se convierte en la divisa ancla del mundo —el esqueleto económico del orden de posguerra.' },
  ww2_lviv_1944: { n: 'Ofensiva Leópolis–Sandomierz', p: 'Leópolis, Ucrania', d: 'En julio de 1944 los ejércitos soviéticos rompen la bolsa de Brody y toman Leópolis, llegando al Vístula en un mes —el Grupo de Ejércitos Norte de Ucrania queda destrozado y el frente cruza a la Polonia ocupada.' },
  ww2_wallenberg: { n: 'Raoul Wallenberg en Budapest', p: 'Budapest, Hungría', d: 'Mientras los transportes de Eichmann llevan 437.000 judíos húngaros a Auschwitz en ocho semanas, un diplomático sueco emite pasaportes de protección y acoge a miles en «casas suecas» —decenas de miles sobreviven.' },
  ww2_warsaw_uprising: { n: 'Levantamiento de Varsovia', p: 'Varsovia, Polonia', d: 'El Ejército Nacional (Armia Krajowa) se alza el 1 de agosto para liberar la ciudad antes de que lleguen los soviéticos; tras 63 días de combates callejeros, Varsovia queda arrasada y unos 200.000 polacos han muerto —mientras el Ejército Rojo observa al otro lado del Vístula.' },
  ww2_paris: { n: 'Liberación de París', p: 'París, Francia', d: 'La división de la Francia Libre de Leclerc y las barricadas de la Resistencia liberan la capital tras cuatro años de ocupación; Choltitz se rinde sin quemar los puentes, y de Gaulle camina por los Campos Elíseos.' },
  ww2_slovak_uprising: { n: 'Levantamiento Nacional Eslovaco', p: 'Banská Bystrica, Eslovaquia', d: 'El ejército eslovaco vuelve sus armas contra el régimen de Tiso y su patrón alemán; dos meses de combates en la montaña acaban en derrota —pero Eslovaquia entra en el haber de los Aliados.' },
  ww2_v2: { n: 'V-2 — la era del cohete', p: 'Peenemünde, Alemania', d: 'Desde laboratorios secretos del Báltico, el primer misil balístico del mundo cae sobre Londres y Amberes a más velocidad que el sonido; el «arma de la venganza» de Hitler no logra salvarlo —y funda la era espacial.' },
  ww2_market_garden: { n: 'Operación Market Garden', p: 'Arnhem, Países Bajos', d: 'Un puente demasiado lejano: el mayor despliegue aerotransportado jamás montado se lanza a saltar el Rin —y los panzer están en Arnhem. La guerra aún deberá desgastarse un invierno más.' },
  ww2_percentages: { n: 'El acuerdo de porcentajes', p: 'Moscú, URSS', d: 'En media hoja de papel, Churchill y Stalin reparten los Balcanes: Rumanía noventa por ciento soviética, Grecia noventa por ciento británica, Yugoslavia al cincuenta por ciento —«¿no podría pensarse que es más bien cínico?»' },
  ww2_leyte: { n: 'Batalla del Golfo de Leyte', p: 'Golfo de Leyte, Filipinas', d: 'La mayor batalla naval jamás librada: cuatro combates separados, los primeros ataques kamikaze y la última salida de la flota japonesa —la Armada Imperial deja de ser una fuerza de combate.' },
  ww2_bulge: { n: 'Batalla de las Ardenas', p: 'Ardenas, Bélgica', d: 'La última apuesta de Hitler en el oeste: los panzer irrumpen por las Ardenas nevadas para partir a los Aliados en dos; Bastogne resiste —«¡Nuts!»— y la Wehrmacht quema sus últimas reservas.' },
  ww2_vistula_oder: { n: 'Ofensiva del Vístula–Óder', p: 'Poznan, Polonia', d: 'En tres semanas de invierno el Ejército Rojo avanza 500 km desde el Vístula hasta a 70 km de Berlín —Silesia tomada, Varsovia rebasada— y el frente alemán del este nunca se recupera.' },
  ww2_yalta: { n: 'Conferencia de Yalta', p: 'Yalta, Crimea', d: 'Los Tres Grandes diseñan el mundo de la posguerra en un palacio de Crimea: zonas de ocupación para Alemania, la ONU, elecciones libres para Polonia prometidas —y jamás celebradas. El mapa de la Guerra Fría se dibuja aquí.' },
  ww2_dresden: { n: 'Bombardeo de Dresde', p: 'Dresde, Alemania', d: 'Cuatro ataques en 36 horas encienden una tormenta de fuego en la «Florencia del Elba», atestada de refugiados; unos 25.000 mueren —y queda acuñado el símbolo de la polémica sobre el bombardeo de área.' },
  ww2_iwo_jima: { n: 'Batalla de Iwo Jima', p: 'Iwo Jima, Japón', d: 'Ocho millas cuadradas de ceniza volcánica cuestan 26.000 bajas estadounidenses frente a unas defensas excavadas en túneles —la bandera sobre el monte Suribachi se convierte en la fotografía más famosa de la guerra.' },
  ww2_tokyo_fire: { n: 'Bombardeo incendiario de Tokio', p: 'Tokio, Japón', d: 'En la noche del 9–10 de marzo, unos 300 B-29 sueltan incendiarias sobre el Tokio de madera —unos 100.000 muertos en horas, el ataque aéreo más mortífero de la historia, medio año antes de las bombas atómicas.' },
  ww2_okinawa: { n: 'Batalla de Okinawa', p: 'Okinawa, Japón', d: 'La última isla antes de Japón: 82 días, 12.000 estadounidenses y unos 100.000 japoneses muertos, 150.000 civiles okinawenses perdidos, kamikazes en masa —se cierne la invasión del propio Japón.' },
  ww2_battle_of_berlin: { n: 'Batalla de Berlín', p: 'Berlín, Alemania', d: 'Dos millones y medio de soldados soviéticos toman la capital del Reich calle a calle; Hitler se quita la vida en el búnker y el Reichstag cae el 30 de abril —la guerra en Europa está a días de terminar.' },
  ww2_elbe_day: { n: 'Día del Elba', p: 'Torgau, Alemania', d: 'Patrullas estadounidenses y soviéticas se dan la mano en un puente destrozado sobre el Elba —este y oeste se han encontrado; se comparte el champán, y el mapa de una Europa dividida empieza a endurecerse.' },
  ww2_ve_day: { n: 'Día de la Victoria en Europa', p: 'Reims, Francia', d: 'Alemania se rinde incondicionalmente —en Reims el 7 de mayo y de nuevo en Berlín–Karlshorst para los soviéticos el 8 de mayo. Seis años de guerra en Europa terminan con decenas de millones de muertos.' },
  ww2_nagasaki: { n: 'Bombardeo atómico de Nagasaki', p: 'Nagasaki, Japón', d: 'La nubosidad sobre Kokura cambia el objetivo: «Fat Man» detona sobre el valle de Urakami, en Nagasaki —40.000 mueren al instante y 70.000 para finales de año, y el consejo de guerra de Japón queda roto por fin.' },
  ww2_japan_surrender: { n: 'Japón se rinde', p: 'Bahía de Tokio, Japón', d: 'En la cubierta del USS Missouri, Japón firma el instrumento de rendición —la guerra más mortífera de la historia ha terminado: 70–85 millones de muertos y dos superpotencias se miran frente a frente sobre un mundo en ruinas.' },
  ww2_nuremberg: { n: 'Juicios de Núremberg', p: 'Núremberg, Alemania', d: 'Veinticuatro dirigentes nazis responden ante un tribunal internacional en la arruinada ciudad del partido: los crímenes contra la humanidad entran en el derecho, la «obediencia debida» deja de ser una defensa y doce son ahorcados.' },
  ww2_expulsions: { n: 'Expulsión de los alemanes del Este', p: 'Europa oriental', d: 'La mayor migración forzada de la historia: 12–14 millones de alemanes son expulsados de Polonia, Checoslovaquia y las tierras bálticas —medio millón muere en los caminos del traslado «ordenado y humano».' },
});
